INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95561, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整顿", "is_correct": true, "explanation": "正确答案。“整顿衣冠”指使衣冠变整齐，与站在镜子前整理仪表相符。"}, {"text": "检阅", "is_correct": false, "explanation": "语义：检阅的对象是部队或队伍，不能用于个人衣冠。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：打扫的对象是房间、场地，不说打扫衣冠。"}, {"text": "掀开", "is_correct": false, "explanation": "配价：掀开需要带可以被掀起的具体物件，不能用于“衣冠”这样的说法。"}], "explanations": {"整顿": "正确答案。“整顿衣冠”指使衣冠变整齐，与站在镜子前整理仪表相符。", "检阅": "语义：检阅的对象是部队或队伍，不能用于个人衣冠。", "打扫": "搭配：打扫的对象是房间、场地，不说打扫衣冠。", "掀开": "配价：掀开需要带可以被掀起的具体物件，不能用于“衣冠”这样的说法。"}, "sentence_index": 0, "correct_answer": "整顿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她整顿好了自己的发音。", "explanation": "这里应该用〈纠正〉。整顿指把乱的东西弄整齐，发音的改正要说纠正。"}, {"text": "他整顿了一下自己的语气。", "explanation": "这里应该用〈调整〉。整顿侧重使乱的东西变整齐，语气的变化要说调整。"}, {"text": "这个学生整顿了自己的成绩。", "explanation": "这里应该用〈提高〉。整顿指把乱的东西弄整齐，成绩的进步要说提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整顿", "is_correct": true, "explanation": "正确答案。“整顿好队伍”指使队伍整齐，与比赛开始前的安排相符。"}, {"text": "冲锋", "is_correct": false, "explanation": "语义：冲锋表示向前猛冲，不能用来“冲锋好队伍”，与裁判安排队伍的语境不符。"}, {"text": "报名", "is_correct": false, "explanation": "搭配：报名是登记参加，不能带“好队伍”这样的结果补语。"}, {"text": "解散", "is_correct": false, "explanation": "语义：解散表示使散开，与“比赛开始前整顿好队伍”的目的相反。"}], "explanations": {"整顿": "正确答案。“整顿好队伍”指使队伍整齐，与比赛开始前的安排相符。", "冲锋": "语义：冲锋表示向前猛冲，不能用来“冲锋好队伍”，与裁判安排队伍的语境不符。", "报名": "搭配：报名是登记参加，不能带“好队伍”这样的结果补语。", "解散": "语义：解散表示使散开，与“比赛开始前整顿好队伍”的目的相反。"}, "sentence_index": 6, "correct_answer": "整顿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她整顿了自己的病情。", "explanation": "这里应该用〈控制〉。整顿指把乱的东西弄整齐，病情的变化要说控制。"}, {"text": "工人整顿了坏掉的水龙头。", "explanation": "这里应该用〈修理〉。整顿指把乱的东西弄整齐，坏掉的水龙头要修理，不能说整顿。"}, {"text": "老板整顿了公司的利润。", "explanation": "这里应该用〈增加〉。整顿指把乱的东西弄整齐，利润的增长要说增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上台前，他把衣冠整顿好的了。", "corrected_sentence": "上台前，他把衣冠整顿好了。", "error_description": "“好”作结果补语后直接接“了”，多出的“的”使句子不成立，应说“整顿好了”，不能说“整顿好的了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他整顿了过队伍，很有经验。", "corrected_sentence": "他整顿过队伍，很有经验。", "error_description": "同一个动词不能同时带“了”和“过”，表示经历要只用“过”，应说“整顿过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
