INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95562, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使混乱的状况变得整齐、有秩序。", "primary_collocate": null, "pronunciation": "zhěng dùn", "ipa": "ʈʂəŋ˨˩˦ tuən˥˩", "syllable_count": 2, "sentences": [{"text": "政府决定整顿混乱的市场。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新校长上任后，先整顿学校的纪律。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司管理很乱，需要好好整顿。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察整顿了这条街的交通秩序。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过整顿，这里的市场变干净了。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板打算整顿一下公司的管理。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府要整顿街上乱停车的问题。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上任后，先整顿了队里的作风。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有关部门正在整顿网络上的坏风气。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的环境很乱，村里决定整顿。", "target_word": "整顿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "整顿了", "label": "完成体"}, {"form": "整顿过", "label": "经历体"}, {"form": "整顿整顿", "label": "重叠"}], "register": "书面语", "sense_fingerprint": "对市场、纪律、管理、作风等混乱的状况进行治理，使其有秩序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2290f97-813e-403b-b4d6-f3b690dd389f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95562, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整顿", "is_correct": true, "explanation": "正确答案。“整顿混乱的市场”指使混乱的市场变得有秩序，与句子语境相符。"}, {"text": "开放", "is_correct": false, "explanation": "语义：开放表示允许进入或放开，与“混乱的市场”需要治理的语境相反。"}, {"text": "保护", "is_correct": false, "explanation": "搭配：“保护混乱的市场”搭配不当，保护的对象应是有价值的事物。"}, {"text": "繁荣", "is_correct": false, "explanation": "语义：繁荣表示兴旺发达，与“混乱”的状况相矛盾。"}], "explanations": {"整顿": "正确答案。“整顿混乱的市场”指使混乱的市场变得有秩序，与句子语境相符。", "开放": "语义：开放表示允许进入或放开，与“混乱的市场”需要治理的语境相反。", "保护": "搭配：“保护混乱的市场”搭配不当，保护的对象应是有价值的事物。", "繁荣": "语义：繁荣表示兴旺发达，与“混乱”的状况相矛盾。"}, "sentence_index": 0, "correct_answer": "整顿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府正在整顿雾霾。", "explanation": "这里应该用〈治理〉。整顿指使混乱的秩序变有条理，雾霾、污染这类环境问题要说治理。"}, {"text": "工人整顿了河里的垃圾。", "explanation": "这里应该用〈清理〉。整顿指使混乱的秩序变有条理，河里的垃圾要说清理。"}, {"text": "他整顿了自己的性格。", "explanation": "这里应该用〈改变〉。整顿指使混乱的状况变有秩序，性格的转变要说改变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整顿", "is_correct": true, "explanation": "正确答案。“整顿街上乱停车的问题”指治理混乱的停车秩序，与句子语境相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：欢迎的对象是人或活动，不能说欢迎问题。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：赞美表示称赞，不能用于“乱停车的问题”，语义不通。"}, {"text": "穿越", "is_correct": false, "explanation": "配价：穿越需要带道路、空间等处所宾语，不能带“问题”。"}], "explanations": {"整顿": "正确答案。“整顿街上乱停车的问题”指治理混乱的停车秩序，与句子语境相符。", "欢迎": "搭配：欢迎的对象是人或活动，不能说欢迎问题。", "赞美": "语义：赞美表示称赞，不能用于“乱停车的问题”，语义不通。", "穿越": "配价：穿越需要带道路、空间等处所宾语，不能带“问题”。"}, "sentence_index": 6, "correct_answer": "整顿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他整顿了一下镜子的角度。", "explanation": "这里应该用〈调整〉。整顿指使混乱的状况变有秩序，镜子角度的调节要说调整。"}, {"text": "工人整顿了坏掉的电脑。", "explanation": "这里应该用〈修理〉。整顿指使混乱的状况变有秩序，坏掉的电脑要修理，不能说整顿。"}, {"text": "她整顿了公司的规模。", "explanation": "这里应该用〈扩大〉。整顿指使混乱的状况变有秩序，规模的扩张要说扩大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "交警决定整顿了这条街的停车秩序。", "corrected_sentence": "交警决定整顿这条街的停车秩序。", "error_description": "“决定”表示计划中的动作，后面的“整顿”不能带“了”，应说“决定整顿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她接手以后，先把部门的纪律整顿。", "corrected_sentence": "她接手以后，先把部门的纪律整顿了一遍。", "error_description": "“把”字句中的“整顿”后面要带补语或“了”等成分，只说“把……整顿”句子不完整，应说“整顿了一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95563, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "正确：「无名」指没有名声，与「有名」构成反义。"}, {"text": "干净", "is_correct": false, "explanation": "不构成反义：「干净」的反义是「肮脏」，与「有名」无关。"}, {"text": "安静", "is_correct": false, "explanation": "不构成反义：「安静」的反义是「吵闹」，与「有名」无关。"}, {"text": "清楚", "is_correct": false, "explanation": "不构成反义：「清楚」的反义是「模糊」，与「有名」无关。"}], "correct_answer": "无名", "explanations": {"无名": "正确：「无名」指没有名声，与「有名」构成反义。", "干净": "不构成反义：「干净」的反义是「肮脏」，与「有名」无关。", "安静": "不构成反义：「安静」的反义是「吵闹」，与「有名」无关。", "清楚": "不构成反义：「清楚」的反义是「模糊」，与「有名」无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95563, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "正确：「无名」指没有名声，与「有名」构成反义。"}, {"text": "温暖", "is_correct": false, "explanation": "不构成反义：「温暖」的反义是「寒冷」，与「有名」无关。"}, {"text": "模糊", "is_correct": false, "explanation": "不构成反义：「模糊」的反义是「清楚」，与「有名」无关。"}, {"text": "简单", "is_correct": false, "explanation": "不构成反义：「简单」的反义是「复杂」，与「有名」无关。"}], "correct_answer": "无名", "explanations": {"无名": "正确：「无名」指没有名声，与「有名」构成反义。", "温暖": "不构成反义：「温暖」的反义是「寒冷」，与「有名」无关。", "模糊": "不构成反义：「模糊」的反义是「清楚」，与「有名」无关。", "简单": "不构成反义：「简单」的反义是「复杂」，与「有名」无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95563, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很多人都知道他的名字。", "primary_collocate": null, "pronunciation": "yǒu míng", "ipa": "joʊ˨˩˦ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这位老医生在我们城里很有名。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位有名的歌手，很多人都听过他的歌。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆很有名，每天都有人排队。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京烤鸭非常有名，外国人也想吃。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写的书很有名，我们学校的学生都看过。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座桥是这里最有名的地方。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是有名的画家，画卖得很贵。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街以小吃有名，晚上特别热闹。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道他是谁，他有名吗？", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在全国都很有名。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "有名：人或事物被很多人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8cec2-0804-43a0-ae6c-4e8f96192c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95563, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年轻", "is_correct": false, "explanation": "语义：「年轻」与前面的「老」矛盾，“老医生”不能同时是年轻的。"}, {"text": "有名", "is_correct": true, "explanation": "正确：「有名」表示很多人知道，与“在我们城里很”搭配，符合句意。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：「圆形」是形状，不能用来形容医生，“很圆形”不成立。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：「潮湿」多形容天气或物体，不用来形容人。"}], "explanations": {"年轻": "语义：「年轻」与前面的「老」矛盾，“老医生”不能同时是年轻的。", "有名": "正确：「有名」表示很多人知道，与“在我们城里很”搭配，符合句意。", "圆形": "语义：「圆形」是形状，不能用来形容医生，“很圆形”不成立。", "潮湿": "搭配：「潮湿」多形容天气或物体，不用来形容人。"}, "sentence_index": 0, "correct_answer": "有名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的头很有名，疼得厉害。", "explanation": "这里应该用〈疼〉。有名指被很多人知道，不能用来形容身体的痛感，说头疼要用〈疼〉。"}, {"text": "我的肚子很有名，饿得咕咕叫。", "explanation": "这里应该用〈饿〉。有名不能用来形容身体的感觉，说肚子饿要用〈饿〉。"}, {"text": "这个公园的门票很有名，一张要两百块。", "explanation": "这里应该用〈贵〉。有名指被很多人知道，说价格高要用〈贵〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木头", "is_correct": false, "explanation": "语义：「木头」是材料，不能形容画家，“木头的画家”不成立。"}, {"text": "有名", "is_correct": true, "explanation": "正确：「有名」指很多人知道，修饰「画家」，符合句意。"}, {"text": "透明", "is_correct": false, "explanation": "语义：「透明」形容物体可以看透，不能形容画家。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：「便宜」多形容价格，不用来形容人。"}], "explanations": {"木头": "语义：「木头」是材料，不能形容画家，“木头的画家”不成立。", "有名": "正确：「有名」指很多人知道，修饰「画家」，符合句意。", "透明": "语义：「透明」形容物体可以看透，不能形容画家。", "便宜": "搭配：「便宜」多形容价格，不用来形容人。"}, "sentence_index": 6, "correct_answer": "有名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天很有名，大家都不想出门。", "explanation": "这里应该用〈寒冷〉。有名指被很多人知道，形容天气要用〈寒冷〉。"}, {"text": "这个地方离家很有名。", "explanation": "这里应该用〈近〉。有名不表示距离，说离家远近要用〈近〉。"}, {"text": "这个时间很有名，已经晚上十二点了。", "explanation": "这里应该用〈晚〉。有名指被很多人知道，不能用来形容时间，说时间晚要用〈晚〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认识一位有名地歌手。", "corrected_sentence": "我认识一位有名的歌手。", "error_description": "结构错误：修饰名词应用「的」，「地」用于动词前。「有名地歌手」应为「有名的歌手」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位作家在我们国家很都有名。", "corrected_sentence": "那位作家在我们国家都很有名。", "error_description": "语序错误：范围副词「都」应放在程度副词「很」前面，再接「有名」。应为「都很有名」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
