INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95564, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "名字为许多人所知；出名。", "primary_collocate": null, "pronunciation": "yǒu míng", "ipa": "joʊ˨˩˦ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个小城因为茶叶而有名。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时就有名了，大家都认识他。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个歌手一唱就有名了。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山有名的原因是风景很美。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还不太有名，但是画得很好。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说让作者一下子有名了。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城在全世界都很有名。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想成为有名的人，所以每天练习。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方以前不太有名，现在游客很多。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员演了一部电影，从此有名了。", "target_word": "有名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "有名：出了名，名声传开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8cec2-0804-43a0-ae6c-4e8f96192c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悲伤", "is_correct": false, "explanation": "语义：「悲伤」表示伤心，茶叶不会使小城悲伤，句意不合。"}, {"text": "有名", "is_correct": true, "explanation": "正确：「有名」指名声传开，与“因为茶叶而”搭配，符合句意。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：「饥饿」指肚子饿，与“小城因为茶叶而”的语境不合。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：小城不会因为茶叶而寒冷，句意不合。"}], "explanations": {"悲伤": "语义：「悲伤」表示伤心，茶叶不会使小城悲伤，句意不合。", "有名": "正确：「有名」指名声传开，与“因为茶叶而”搭配，符合句意。", "饥饿": "语义：「饥饿」指肚子饿，与“小城因为茶叶而”的语境不合。", "寒冷": "语义：小城不会因为茶叶而寒冷，句意不合。"}, "sentence_index": 0, "correct_answer": "有名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校离家很有名。", "explanation": "这里应该用〈近〉。有名指名声传开，说距离要用〈近〉。"}, {"text": "我的牙很有名，疼得睡不着。", "explanation": "这里应该用〈疼〉。有名指被很多人知道，不能用来形容身体的痛感，牙疼要用〈疼〉。"}, {"text": "我的腿很有名，走起路来很慢。", "explanation": "这里应该用〈酸〉。有名不能用来形容身体的感觉，腿酸要用〈酸〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年轻", "is_correct": false, "explanation": "语义：长城是古老的建筑，「年轻」与之矛盾，句中不成立。"}, {"text": "有名", "is_correct": true, "explanation": "正确：「有名」指被很多人知道，与“在全世界都很”搭配，符合句意。"}, {"text": "软", "is_correct": false, "explanation": "搭配：「软」多形容质地，不用来形容长城。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：「矮」形容高度或外形，长城不能用这个词来形容。"}], "explanations": {"年轻": "语义：长城是古老的建筑，「年轻」与之矛盾，句中不成立。", "有名": "正确：「有名」指被很多人知道，与“在全世界都很”搭配，符合句意。", "软": "搭配：「软」多形容质地，不用来形容长城。", "矮": "体貌：「矮」形容高度或外形，长城不能用这个词来形容。"}, "sentence_index": 6, "correct_answer": "有名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子很有名，搬起来很累。", "explanation": "这里应该用〈重〉。有名说名声传开，形容重量要用〈重〉。"}, {"text": "这里离市中心很有名。", "explanation": "这里应该用〈远〉。有名不表示距离，说离市中心远要用〈远〉。"}, {"text": "衣服洗完很有名，可以穿了。", "explanation": "这里应该用〈干〉。有名不形容干湿，形容衣服干要用〈干〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有名很。", "corrected_sentence": "这个城市很有名。", "error_description": "语序错误：程度副词「很」应放在形容词「有名」前面。「有名很」应为「很有名」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想当一个有名地人。", "corrected_sentence": "我想当一个有名的人。", "error_description": "结构错误：修饰名词「人」应用「的」，「地」用于动词前。「有名地人」应为「有名的人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95565, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失联", "is_correct": true, "explanation": "失联：失去联系、不再有往来，与“有联系”相反。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：外出游览，与“有联系”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：用声音表演歌曲，与“有联系”没有反义关系。"}, {"text": "观看", "is_correct": false, "explanation": "观看：仔细地看，与“有联系”没有反义关系。"}], "correct_answer": "失联", "explanations": {"失联": "失联：失去联系、不再有往来，与“有联系”相反。", "旅行": "旅行：外出游览，与“有联系”没有反义关系。", "唱歌": "唱歌：用声音表演歌曲，与“有联系”没有反义关系。", "观看": "观看：仔细地看，与“有联系”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95565, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隔绝", "is_correct": true, "explanation": "隔绝：彼此不相往来，与“有联系”相反。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳：在水中运动，与“有联系”没有反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "写作：用文字写成文章，与“有联系”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞：随着音乐做动作，与“有联系”没有反义关系。"}], "correct_answer": "隔绝", "explanations": {"隔绝": "隔绝：彼此不相往来，与“有联系”相反。", "游泳": "游泳：在水中运动，与“有联系”没有反义关系。", "写作": "写作：用文字写成文章，与“有联系”没有反义关系。", "跳舞": "跳舞：随着音乐做动作，与“有联系”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95565, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "两个人或两件事是连在一起的。", "primary_collocate": null, "pronunciation": "yǒu lián xì", "ipa": "jou̯˨˩˦ ljɛn˧˥ ɕi˥˩", "syllable_count": 3, "sentences": [{"text": "我和他一直有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你和这件事有联系吗？", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，我和老同学还有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和这个案子有联系，警察正在找他。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟远方的朋友很少有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两家是亲戚，所以常常有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹和那个公司有联系，可以帮你问问。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人和外面几乎没有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和那个演员有联系，所以拿到了票。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬家以后，我们还有联系吗？", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有联系", "label": "否定"}], "register": "中性", "sense_fingerprint": "有联系：人与人、事与事之间相连、有往来或有牵连", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ffb014-c98c-44e0-81a7-bd5a6b2f207a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有联系", "is_correct": true, "explanation": "有联系：两人之间保持往来、彼此相连。"}, {"text": "分手", "is_correct": false, "explanation": "体貌：分手是一次性的动作，不能与表示持续的“一直”搭配。"}, {"text": "出发", "is_correct": false, "explanation": "体貌：出发是一次性的动作，不能与表示持续的“一直”搭配。"}, {"text": "出国", "is_correct": false, "explanation": "语义：出国是离开本国的行动，与“我和他一直……”的意思不符。"}], "explanations": {"有联系": "有联系：两人之间保持往来、彼此相连。", "分手": "体貌：分手是一次性的动作，不能与表示持续的“一直”搭配。", "出发": "体貌：出发是一次性的动作，不能与表示持续的“一直”搭配。", "出国": "语义：出国是离开本国的行动，与“我和他一直……”的意思不符。"}, "sentence_index": 0, "correct_answer": "有联系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "对不起，打扰你了。——没有联系。", "explanation": "这里应该用〈没关系〉。“没关系”表示不要紧，“没有联系”说的是彼此没有往来，回答道歉不能用它。"}, {"text": "这个方案可以吗？——没有联系，可以。", "explanation": "这里应该用〈没问题〉。“没问题”表示可以、行，“没有联系”指彼此无往来，不能用来回答可否。"}, {"text": "你受伤了吗？——没有联系，没事。", "explanation": "这里应该用〈没事〉。“没事”表示没有问题，“没有联系”说的是彼此无往来，不能这样回答。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有联系", "is_correct": true, "explanation": "有联系：两者之间有往来，可以托对方帮忙。"}, {"text": "竞争", "is_correct": false, "explanation": "语义：竞争是互相争夺，与“可以帮你问问”的意思矛盾。"}, {"text": "反对", "is_correct": false, "explanation": "配价：“反对”要带宾语，“和那个公司反对”缺少对象，说不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳是水中的运动，与“和那个公司”的关系说不通。"}], "explanations": {"有联系": "有联系：两者之间有往来，可以托对方帮忙。", "竞争": "语义：竞争是互相争夺，与“可以帮你问问”的意思矛盾。", "反对": "配价：“反对”要带宾语，“和那个公司反对”缺少对象，说不通。", "游泳": "语义：游泳是水中的运动，与“和那个公司”的关系说不通。"}, "sentence_index": 6, "correct_answer": "有联系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和这张桌子有联系，每天都擦它。", "explanation": "这里应该用〈擦〉。“有联系”指人与人或事与事之间的关联或往来，不能说人和物品有联系，应直接说“擦桌子”。"}, {"text": "我和这杯咖啡有联系，每天都喝它。", "explanation": "这里应该用〈喝〉。“有联系”指人与人或事与事之间的往来或关联，不能指人和饮料，应直接说“喝咖啡”。"}, {"text": "我和这台电脑有联系，每天都用它。", "explanation": "这里应该用〈使用〉。“有联系”不能指人和物品之间的使用关系，应说“用电脑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些年我一直和小学同学的有联系。", "corrected_sentence": "这些年我一直和小学同学有联系。", "error_description": "“有联系”是谓语，前面不能加“的”，应写成“和小学同学有联系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他搬家以后，我们就不有联系了。", "corrected_sentence": "他搬家以后，我们就没有联系了。", "error_description": "否定“有联系”要用“没有联系”，“不有联系”是错误形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95566, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无关", "is_correct": true, "explanation": "无关：彼此没有关系，与“有联系”相反。"}, {"text": "圆满", "is_correct": false, "explanation": "圆满：完美、没有缺憾，与“有联系”没有反义关系。"}, {"text": "健康", "is_correct": false, "explanation": "健康：身体没有疾病，与“有联系”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：光线充足、亮堂，与“有联系”没有反义关系。"}], "correct_answer": "无关", "explanations": {"无关": "无关：彼此没有关系，与“有联系”相反。", "圆满": "圆满：完美、没有缺憾，与“有联系”没有反义关系。", "健康": "健康：身体没有疾病，与“有联系”没有反义关系。", "明亮": "明亮：光线充足、亮堂，与“有联系”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
