INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95566, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "彼此之间存在关联。", "primary_collocate": null, "pronunciation": "yǒu lián xì", "ipa": "jou̯˨˩˦ ljɛn˧˥ ɕi˥˩", "syllable_count": 3, "sentences": [{"text": "天气和心情有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉的时间和身体好不好有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个问题有联系，要一起想。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的意思和它的字形有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩和他每天看书有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃的东西和人的心情有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习汉语和了解中国文化有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得这两个现象有联系吗？", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些故事看起来不同，但其实有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他的病和天气有联系。", "target_word": "有联系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有联系", "label": "否定"}], "register": "中性", "sense_fingerprint": "有联系：事物、现象之间存在关联或因果关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ffb014-c98c-44e0-81a7-bd5a6b2f207a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有联系", "is_correct": true, "explanation": "有联系：事物之间存在关联。"}, {"text": "相识", "is_correct": false, "explanation": "语义：相识指人与人互相认识，天气和心情不能相识。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚是人与人之间的婚姻关系，天气和心情不能结婚。"}, {"text": "握手", "is_correct": false, "explanation": "搭配：“握手”的主体须是人，“天气和心情”不能握手。"}], "explanations": {"有联系": "有联系：事物之间存在关联。", "相识": "语义：相识指人与人互相认识，天气和心情不能相识。", "结婚": "语义：结婚是人与人之间的婚姻关系，天气和心情不能结婚。", "握手": "搭配：“握手”的主体须是人，“天气和心情”不能握手。"}, "sentence_index": 0, "correct_answer": "有联系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "对不起，我弄丢了你的书。——没有联系，别担心。", "explanation": "这里应该用〈没关系〉。“没关系”表示不要紧，“没有联系”说的是事物之间没有关联，不能用来安慰别人。"}, {"text": "我每天都有联系这把椅子。", "explanation": "这里的错误在「有联系」：它不能直接带「这把椅子」作宾语，应说「我每天都坐这把椅子」。"}, {"text": "你要喝水吗？——没有联系，谢谢。", "explanation": "这里应该用〈不用〉。“没有联系”说的是彼此无关，不能用来回答别人的好意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有联系", "is_correct": true, "explanation": "有联系：两者之间存在关联。"}, {"text": "对立", "is_correct": false, "explanation": "语义：对立指互相抵触，学习汉语和了解文化不是对立关系。"}, {"text": "吵架", "is_correct": false, "explanation": "搭配：“吵架”的主体须是人，“学习汉语”和“了解文化”不能吵架。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是走路消遣的动作，与学习和文化的关系说不通。"}], "explanations": {"有联系": "有联系：两者之间存在关联。", "对立": "语义：对立指互相抵触，学习汉语和了解文化不是对立关系。", "吵架": "搭配：“吵架”的主体须是人，“学习汉语”和“了解文化”不能吵架。", "散步": "语义：散步是走路消遣的动作，与学习和文化的关系说不通。"}, "sentence_index": 6, "correct_answer": "有联系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我有联系一本书，每天都看它。", "explanation": "这里的错误在「有联系」：它不能带「一本书」这样的数量宾语，应说「我有一本书，每天都看它」。"}, {"text": "谢谢你的帮助。——没有联系，不客气。", "explanation": "这里应该用〈不客气〉。「没有联系」说的是彼此无关，不能用来回答感谢。"}, {"text": "这两个问题有联系很多。", "explanation": "这里的错误在语序：「有联系」是动宾式，数量修饰应说「有很多联系」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "感冒的原因和天气的有联系吗？", "corrected_sentence": "感冒的原因和天气有联系吗？", "error_description": "“有联系”是谓语，“天气”后不能加“的”，应写成“和天气有联系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两件事情不有联系。", "corrected_sentence": "这两件事情没有联系。", "error_description": "否定“有联系”要用“没有联系”，不能用“不有联系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
