INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95567, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在大学里读的头几年的学习，学完拿到毕业证。", "primary_collocate": null, "pronunciation": "běn kē", "ipa": "pən˨˩˦ kʰɤ˥", "syllable_count": 2, "sentences": [{"text": "他在北京读了四年本科。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本科学的是经济。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她本科毕业以后去了美国。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本科的时候，我住在学校里。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥本科读完就开始工作了。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本科四年里，他认识了很多朋友。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在本科期间多去国外看看。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她本科时每天都去图书馆学习。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，本科那几年是他最难忘的日子。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从本科一年级就开始学法语了。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本科生", "label": "复合"}, {"form": "本科学历", "label": "复合"}], "register": "中性", "sense_fingerprint": "大学头几年的学习阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95567, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本科", "is_correct": true, "explanation": "正确。“本科”指大学的基本学制阶段，“读了四年本科”符合语境。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“读”的宾语是学业、学校或书，不能说读工资。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“读”指学习，饭不是学习的对象，“读饭”不成立。"}, {"text": "图书馆", "is_correct": false, "explanation": "配价：“读”的宾语应是学业或书籍，图书馆是处所，不能作“读”的宾语。"}], "explanations": {"本科": "正确。“本科”指大学的基本学制阶段，“读了四年本科”符合语境。", "工资": "搭配：“读”的宾语是学业、学校或书，不能说读工资。", "饭": "语义：“读”指学习，饭不是学习的对象，“读饭”不成立。", "图书馆": "配价：“读”的宾语应是学业或书籍，图书馆是处所，不能作“读”的宾语。"}, "sentence_index": 0, "correct_answer": "本科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的本科是硕士。", "explanation": "这里应该用〈学历〉。本科指大学的一个学制阶段，说一个人的学历层次要用学历，不能说“本科是硕士”。"}, {"text": "本科打电话给了朋友。", "explanation": "本科是一段学习时期，不是人，不能作主语去“打电话”；这里应该用〈我〉作主语。"}, {"text": "我这次在国外念了一场本科。", "explanation": "量词用错了。本科是一段学习时期，一般不加量词，直接说〈念了本科〉；场多用于比赛、活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本科", "is_correct": true, "explanation": "正确。“本科期间”指大学本科学习的时期，与“多去国外看看”相容。"}, {"text": "病房", "is_correct": false, "explanation": "语义：“在病房期间”是住院时段，与“多去国外看看”自相矛盾。"}, {"text": "医院", "is_correct": false, "explanation": "语义：在医院期间不能多去国外，句意与语境冲突。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“在……期间”不能接学费，学费不是时段或活动。"}], "explanations": {"本科": "正确。“本科期间”指大学本科学习的时期，与“多去国外看看”相容。", "病房": "语义：“在病房期间”是住院时段，与“多去国外看看”自相矛盾。", "医院": "语义：在医院期间不能多去国外，句意与语境冲突。", "学费": "搭配：“在……期间”不能接学费，学费不是时段或活动。"}, "sentence_index": 6, "correct_answer": "本科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的本科走进了教室。", "explanation": "本科是学习时期，不能走路、不能作施事主语；这里应该用〈她〉作主语。"}, {"text": "他本科地学习法语。", "explanation": "本科是名词，指一段学习时期，不能加“地”作状语；这里应该用〈在本科期间〉。"}, {"text": "我在国外读了一门本科。", "explanation": "量词用错了。本科是一段学习时期，一般不加量词，直接说〈读了本科〉；门用于课程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在国外念完了一门本科，回国后找到了工作。", "corrected_sentence": "我在国外念完了本科，回国后找到了工作。", "error_description": "“门”用于课程，不能用来计量本科；本科一般不加量词，应说“念完了本科”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在国外读了一场本科，之后回国工作。", "corrected_sentence": "他在国外读了本科，之后回国工作。", "error_description": "“场”用于比赛、活动，不能用来计量本科；本科一般不加量词，应说“读了本科”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
