INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95568, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95568, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "高等学校中的基本学制课程，区别于专科和研究生。", "primary_collocate": null, "pronunciation": "běn kē", "ipa": "pən˨˩˦ kʰɤ˥", "syllable_count": 2, "sentences": [{"text": "这所大学的本科比专科难考。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的学历是本科，不是专科。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司要求本科以上学历。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本科和研究生的课程很不一样。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学校的本科有三十个专业。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校今年的本科招生人数增加了。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学院只开本科课程，没有研究生。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先拿到了本科文凭，再读硕士。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校的本科要读四年，专科读三年。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个职位只招本科，不要专科。", "target_word": "本科", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本科生", "label": "复合"}, {"form": "本科学历", "label": "复合"}], "register": "中性", "sense_fingerprint": "高校学制层次，区别于专科和研究生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本科", "is_correct": true, "explanation": "正确。“本科”是学制层次，与“比专科难考”构成比较。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“难考”说的是录取或考试的难度，学费不能说难考。"}, {"text": "宿舍", "is_correct": false, "explanation": "搭配：“难考”搭配考试、录取、专业，不能说宿舍难考。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“难考”搭配考试、录取、专业，不能说食堂难考。"}], "explanations": {"本科": "正确。“本科”是学制层次，与“比专科难考”构成比较。", "学费": "语义：“难考”说的是录取或考试的难度，学费不能说难考。", "宿舍": "搭配：“难考”搭配考试、录取、专业，不能说宿舍难考。", "食堂": "搭配：“难考”搭配考试、录取、专业，不能说食堂难考。"}, "sentence_index": 0, "correct_answer": "本科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的本科是专科。", "explanation": "这里应该用〈学历〉。本科指学制阶段，说学历层次要用学历，“本科是专科”自相矛盾。"}, {"text": "他的本科比研究生高一级。", "explanation": "本科是比研究生低的学制层次，应说“研究生比本科高一级”，比较方向颠倒了。"}, {"text": "他拿到了一张本科。", "explanation": "这里量词不对。本科是学制层次，不是证件，不能用〈张〉，应说“本科学历”或“本科文凭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本科", "is_correct": true, "explanation": "正确。“只开本科课程”指学院开设的学制层次课程，与“没有研究生”形成对比。"}, {"text": "硕士", "is_correct": false, "explanation": "语义：硕士属于研究生，与后文“没有研究生”矛盾。"}, {"text": "小学", "is_correct": false, "explanation": "语义：学院开设的是高等教育课程，小学不属于这一层次。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“开”后接课程、专业，不能接早饭。"}], "explanations": {"本科": "正确。“只开本科课程”指学院开设的学制层次课程，与“没有研究生”形成对比。", "硕士": "语义：硕士属于研究生，与后文“没有研究生”矛盾。", "小学": "语义：学院开设的是高等教育课程，小学不属于这一层次。", "早饭": "搭配：“开”后接课程、专业，不能接早饭。"}, "sentence_index": 6, "correct_answer": "本科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我弟弟的本科一米八五高。", "explanation": "本科是学制层次，不能描述身高；这里应该用〈我弟弟〉作主语，如“我弟弟一米八五高”。"}, {"text": "他拿到了硕士本科。", "explanation": "这里应该用〈文凭〉。本科是学制层次，不能与“硕士”并列作为文凭的名称；应说“硕士文凭”或“本科文凭”。"}, {"text": "我这学期上了一门本科。", "explanation": "这里量词不对。本科指学制层次，不是一门具体的课程，不能用〈门〉计量；可以说“一门课”或“本科课程”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个研究所只招本科以内的人。", "corrected_sentence": "这个研究所只招本科以上的人。", "error_description": "“以内”用于数量或时间范围，不能用于学历层次；应说“本科以上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司只要本科以内的学历。", "corrected_sentence": "这家公司只要本科以上的学历。", "error_description": "“以内”用于数量或时间范围，不能用于学历层次；应说“本科以上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
