INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95572, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用简短文字写成、起宣传鼓动作用的口号。", "primary_collocate": null, "pronunciation": "biāo yǔ", "ipa": "pi̯ɑʊ˥ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "这条标语很短，大家一看就记住了。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的标语是“保护地球，从我做起”。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的标语是“客户第一”，员工都很熟悉。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句环保标语简单有力，很多人都喜欢。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，我们一起想了一条好标语。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把宣传标语改得更短了。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们为读书节写一条标语。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条标语告诉大家要节约用水。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好标语要短，要容易记，也要有意思。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的安全标语提醒工人注意安全。", "target_word": "标语", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条标语", "label": "量词"}, {"form": "宣传标语", "label": "复合"}, {"form": "標語", "label": "繁体"}], "register": "中性", "sense_fingerprint": "宣传鼓动用的简短口号文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6c3ec9-8bf6-4b2f-9d66-249534f22bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标语", "is_correct": true, "explanation": "正确：标语是宣传用的简短口号，可以“一看就记住”。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是自然景物，不是可以“一看就记住”的文字。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子是实物，不是宣传用的文字，不能“一看就记住”。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不是宣传用的文字，不能“一看就记住”。"}], "explanations": {"标语": "正确：标语是宣传用的简短口号，可以“一看就记住”。", "河": "语义：河是自然景物，不是可以“一看就记住”的文字。", "绳子": "语义：绳子是实物，不是宣传用的文字，不能“一看就记住”。", "饼干": "语义：饼干是食物，不是宣传用的文字，不能“一看就记住”。"}, "sentence_index": 0, "correct_answer": "标语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的标语很吸引人。", "explanation": "这里应该用〈标题〉。标语是用来宣传鼓动的简短口号，文章的题目要用标题。"}, {"text": "爷爷常说‘学而不厌’，这是孔子的标语。", "explanation": "这里应该用〈名言〉。名言指前人说过的有道理的话，标语是为宣传鼓动而写的口号，不用来指孔子说过的话。"}, {"text": "婚礼上，朋友们为新人说了一段标语，祝他们幸福。", "explanation": "这里应该用〈祝词〉。标语是宣传鼓动的口号，婚礼上祝福新人的话是祝词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标语", "is_correct": true, "explanation": "正确：“写一条标语”指写出一句宣传用的口号，符合句意。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼是动物，不能被“写”出来。"}, {"text": "被子", "is_correct": false, "explanation": "配价：“写”要求书写的内容作宾语，被子不能作“写”的对象。"}, {"text": "项链", "is_correct": false, "explanation": "搭配：“写一条项链”与“写”不搭配，项链无法被书写。"}], "explanations": {"标语": "正确：“写一条标语”指写出一句宣传用的口号，符合句意。", "鱼": "语义：鱼是动物，不能被“写”出来。", "被子": "配价：“写”要求书写的内容作宾语，被子不能作“写”的对象。", "项链": "搭配：“写一条项链”与“写”不搭配，项链无法被书写。"}, "sentence_index": 6, "correct_answer": "标语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的标语写得很感人。", "explanation": "这里应该用〈歌词〉。标语是宣传用的简短口号，歌曲的词要用歌词。"}, {"text": "他是班里的标语，成绩最好。", "explanation": "这里应该用〈标兵〉。标兵指作出好榜样的人，标语是写出来的口号，不能用来指人。"}, {"text": "这家公司的标语是一只红色的鸟。", "explanation": "这里应该用〈标志〉。标志可以是图形，标语是用文字写的口号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们写了一本标语，贴在教室门口。", "corrected_sentence": "他们写了一条标语，贴在教室门口。", "error_description": "量词错误：标语应用“条”，“本”用于书籍，不能用于标语。正确说法是“一条标语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那本标语改短了。", "corrected_sentence": "他把那条标语改短了。", "error_description": "量词错误：标语应用“条”，“本”用于书籍。正确说法是“他把那条标语改短了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
