INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "依法享有某种权利的人。", "primary_collocate": null, "pronunciation": "quán lì rén", "ipa": "tɕʰyɛn˧˥ li˥˩ ɻən˧˥", "syllable_count": 3, "sentences": [{"text": "法律保护权利人的利益。", "target_word": "权利人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "权利人有权要求别人停止使用。", "target_word": "权利人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的权利人是作者的家人。", "target_word": "权利人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "权利人可以依法去法院告对方。", "target_word": "权利人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专利的权利人拿到了一大笔钱。", "target_word": "权利人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "权利人没有同意，别人不能复制这部电影。", "target_word": "权利人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司是这个商标的权利人。", "target_word": "权利人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "权利人要求他们赔钱。", "target_word": "权利人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法院认定他是合法的权利人。", "target_word": "权利人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "找到权利人以后，我们签了合同。", "target_word": "权利人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "书面语", "sense_fingerprint": "法律上依法享有权利的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab055cd8-a036-49ec-a1fc-97881175b0a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权利人", "is_correct": true, "explanation": "权利人指依法享有权利的人，放在“法律保护……的利益”里意思通顺。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不是法律所保护利益的主体，句子意思说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“利益”与“窗户”不搭配，不能说窗户的利益。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是法律保护的对象，句意不合。"}], "explanations": {"权利人": "权利人指依法享有权利的人，放在“法律保护……的利益”里意思通顺。", "植物": "语义：植物不是法律所保护利益的主体，句子意思说不通。", "窗户": "搭配：“利益”与“窗户”不搭配，不能说窗户的利益。", "饼干": "语义：饼干不是法律保护的对象，句意不合。"}, "sentence_index": 0, "correct_answer": "权利人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同桌是权利人，每天都认真学习。", "explanation": "这里应该用〈学生〉。权利人指依法享有权利的人，与学习无关；在学校学习的人要说学生。"}, {"text": "我每天早上用权利人刷牙。", "explanation": "这里应该用〈牙刷〉。权利人指依法享有权利的人，不是用来刷牙的东西；刷牙用的东西要说牙刷。"}, {"text": "他的权利人很高大，大家都认识他。", "explanation": "这里应该用〈身材〉。权利人是法律上的身份，不能用来形容体型；描述一个人的体型要说身材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权利人", "is_correct": true, "explanation": "权利人指依法享有权利的人，放在“公司是这个商标的……”里意思通顺。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“司机”指开车的人，与“商标”没有归属关系，句子说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人，不能作为商标的权利主体，句子说不通。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”指做饭的人，与“商标”没有归属关系，句子说不通。"}], "explanations": {"权利人": "权利人指依法享有权利的人，放在“公司是这个商标的……”里意思通顺。", "司机": "语义：“司机”指开车的人，与“商标”没有归属关系，句子说不通。", "天气": "语义：“天气”不是人，不能作为商标的权利主体，句子说不通。", "厨师": "语义：“厨师”指做饭的人，与“商标”没有归属关系，句子说不通。"}, "sentence_index": 6, "correct_answer": "权利人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在操场上当权利人，跑了三圈。", "explanation": "这里不这么用。权利人指依法享有权利的人，不是运动中的角色；跑步的人要说跑者或运动员。"}, {"text": "我昨天买的权利人很好吃。", "explanation": "这里不这么用。权利人指享有权利的人，不是食物；说好吃的东西要用食物或点心等词。"}, {"text": "今天的权利人很冷，还下着雨。", "explanation": "这里应该用〈天气〉。权利人是法律上的身份，不能描述冷热和下雨；说冷热要用天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只权利人已经向法院起诉了。", "corrected_sentence": "这位权利人已经向法院起诉了。", "error_description": "“只”不用于指人，应改为量词“位”。应该说：这位权利人已经向法院起诉了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "权利人了没有收到付款。", "corrected_sentence": "权利人没有收到付款。", "error_description": "“了”不能直接加在名词“权利人”后面，它不表示动态变化。应该说：权利人没有收到付款。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
