INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "建筑材料，由石灰石等烧成的灰色粉末，遇水硬化。", "primary_collocate": null, "pronunciation": "shuǐ ní", "ipa": "ʂueɪ˨˩˦ ni˧˥", "syllable_count": 2, "sentences": [{"text": "这个国家每年生产很多水泥。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泥是用石灰石烧成的。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖大楼要用大量的水泥和钢铁。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泥遇到水就会变硬。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥的下面是水泥做的柱子。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门卖水泥给建筑公司。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泥的价格这个月涨了。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建大坝需要很多水泥。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泥放得太久，会吸水变坏。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条高速公路用了几万吨水泥。", "target_word": "水泥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "袋", "label": "量词"}, {"form": "吨", "label": "量词"}], "register": "中性", "sense_fingerprint": "水泥：石灰石烧成的建筑材料，遇水硬化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6c3ec9-8bf6-4b2f-9d66-249534f22bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以大量生产的产品，“生产很多空气”句意不通。"}, {"text": "水泥", "is_correct": true, "explanation": "正确答案。水泥是可以大量生产的建筑材料，与“生产很多”相合。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“生产”与“时间”搭配不当，时间不能被生产。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声不是产品，“生产很多笑声”句意不通。"}], "explanations": {"空气": "语义：空气不是可以大量生产的产品，“生产很多空气”句意不通。", "水泥": "正确答案。水泥是可以大量生产的建筑材料，与“生产很多”相合。", "时间": "搭配：“生产”与“时间”搭配不当，时间不能被生产。", "笑声": "语义：笑声不是产品，“生产很多笑声”句意不通。"}, "sentence_index": 0, "correct_answer": "水泥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给他的胳膊打了水泥，三周后再来复查。", "explanation": "这里应该用〈石膏〉。“打石膏”指医疗固定骨折，水泥是建筑材料，不能用来固定骨头。"}, {"text": "养殖场里有一头水泥。", "explanation": "量词错误：“头”用于牲畜，水泥应该用“袋”或“吨”。"}, {"text": "妈妈用水泥做了一块蛋糕。", "explanation": "这里应该用〈面粉〉。水泥是建筑材料，不能食用，不能用来做蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼神", "is_correct": false, "explanation": "配价：“价格”要求可以买卖的商品作领属，“眼神”没有价格。"}, {"text": "春天", "is_correct": false, "explanation": "配价：“春天”不是可以交易的商品，不能有“价格”。"}, {"text": "水泥", "is_correct": true, "explanation": "正确答案。水泥是可以买卖的商品，有价格，与“价格这个月涨了”相合。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“月亮”与“价格”搭配不当，句意不通。"}], "explanations": {"眼神": "配价：“价格”要求可以买卖的商品作领属，“眼神”没有价格。", "春天": "配价：“春天”不是可以交易的商品，不能有“价格”。", "水泥": "正确答案。水泥是可以买卖的商品，有价格，与“价格这个月涨了”相合。", "月亮": "搭配：“月亮”与“价格”搭配不当，句意不通。"}, "sentence_index": 6, "correct_answer": "水泥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用水泥煮了一锅粥。", "explanation": "这里应该用〈大米〉。水泥是建筑材料，不能用来煮粥。"}, {"text": "院子里放着一座水泥。", "explanation": "量词错误：“座”用于山、楼等，水泥应该用“袋”或“吨”。"}, {"text": "这只水泥很重，他搬不动。", "explanation": "量词错误：“只”多用于动物，应说“这袋水泥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂去年把水泥们都运走了。", "corrected_sentence": "这家工厂去年把水泥都运走了。", "error_description": "“水泥”是物质名词，不能加复数词尾“们”，应说“把水泥都运走了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座大桥用了很多个水泥，修得很结实。", "corrected_sentence": "这座大桥用了很多水泥，修得很结实。", "error_description": "“水泥”是物质名词，不能加量词“个”。应说“用了很多水泥”，去掉“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95577, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
