INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95578, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个体进行活动、行动的能力。", "primary_collocate": null, "pronunciation": "huó dòng néng lì", "ipa": "xuo˧˥ tʊŋ˥˩ nɤŋ˧˥ li˥˩", "syllable_count": 4, "sentences": [{"text": "疫情期间，大家的活动能力受到了很大限制。", "target_word": "活动能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小动物到了晚上，活动能力会变强。", "target_word": "活动能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种鱼在冷水里活动能力很弱，几乎不动。", "target_word": "活动能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台小机器的活动能力有限，只能在房间里工作。", "target_word": "活动能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，虫子的活动能力会下降。", "target_word": "活动能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检查了病人的活动能力，看他能不能自己吃饭。", "target_word": "活动能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子越大，独立活动能力越强。", "target_word": "活动能力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器人要有活动能力，才能在家里帮忙做事。", "target_word": "活动能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过训练，这只狗的活动能力提高了不少。", "target_word": "活动能力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天天气变暖，青蛙的活动能力慢慢变强了。", "target_word": "活动能力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "个体进行活动、行动的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1895556-f649-4d14-bbf1-60be23bb54b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活动能力", "is_correct": true, "explanation": "活动能力：个体进行活动、行动的能力，与“受到很大限制”相符。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能说“受到限制”，与句意不合。"}, {"text": "学历", "is_correct": false, "explanation": "语义：疫情限制的是人的行动，“学历”与此无关。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不能说“受到很大限制”，搭配不当。"}], "explanations": {"活动能力": "活动能力：个体进行活动、行动的能力，与“受到很大限制”相符。", "身高": "搭配：“身高”不能说“受到限制”，与句意不合。", "学历": "语义：疫情限制的是人的行动，“学历”与此无关。", "体温": "搭配：“体温”不能说“受到很大限制”，搭配不当。"}, "sentence_index": 0, "correct_answer": "活动能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯茶的活动能力很强，喝了很提神。", "explanation": "这里应该用〈提神效果〉。活动能力指个体的行动能力，不能用来形容茶。"}, {"text": "这篇文章的活动能力很强，读起来很有意思。", "explanation": "这里应该用〈吸引力〉。活动能力指个体的行动能力，不能用来形容文章的吸引力。"}, {"text": "他的活动能力很好，能背下整本书。", "explanation": "这里应该用〈记忆力〉。活动能力指行动的能力，不指背诵和记忆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活动能力", "is_correct": true, "explanation": "活动能力：个体行动的能力，与“孩子越大，独立……越强”相符。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”不能用于“独立……越强”这样的结构。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身材，不指独立能力，句子不通。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”与孩子的独立能力无关，句子荒谬。"}], "explanations": {"活动能力": "活动能力：个体行动的能力，与“孩子越大，独立……越强”相符。", "工资": "搭配：“工资”不能用于“独立……越强”这样的结构。", "身高": "体貌：“身高”指身材，不指独立能力，句子不通。", "学费": "语义：“学费”与孩子的独立能力无关，句子荒谬。"}, "sentence_index": 6, "correct_answer": "活动能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的活动能力很容易分散，上课总是走神。", "explanation": "这里应该用〈注意力〉。活动能力指行动的能力，不能说“分散”。"}, {"text": "这家餐厅的活动能力很强，菜品很快就上来。", "explanation": "这里应该用〈效率〉。活动能力指个体的行动能力，不能用来形容餐厅的服务效率。"}, {"text": "他活动能力很强，一点就通。", "explanation": "这里应该用〈理解力〉。活动能力指行动的能力，不指理解和领悟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过训练，这只狗的活动能力很厚。", "corrected_sentence": "经过训练，这只狗的活动能力很强。", "error_description": "“厚”形容物体的厚薄，不能用来形容活动能力，应说“强”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只小狗的活动能力很长，经常跑来跑去。", "corrected_sentence": "这只小狗的活动能力很强，经常跑来跑去。", "error_description": "“活动能力”的高低用“强、弱”描述，不能用“长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'babe99dc-53e0-4a57-b715-5a88805c563c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
