INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95580, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被怀疑与某违法事件有关。", "primary_collocate": null, "pronunciation": "shè xián", "ipa": "ʂɤ˥˩ ɕi̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "警方说他涉嫌诈骗，正在调查。", "target_word": "涉嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这名男子涉嫌盗窃，昨天接受了警察的调查。", "target_word": "涉嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司老板涉嫌违法，警察已经带走了他。", "target_word": "涉嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两名司机涉嫌酒后开车，警察对他们做了检查。", "target_word": "涉嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂涉嫌污染河水，环保部门正在查。", "target_word": "涉嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他涉嫌参与一起走私案，法院还没有判决。", "target_word": "涉嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，这个人涉嫌多起抢劫案。", "target_word": "涉嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位官员涉嫌收钱办事，检察院已经立案。", "target_word": "涉嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有人涉嫌卖假药，警方正在追查。", "target_word": "涉嫌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个年轻人涉嫌打架伤人，昨晚都到了派出所。", "target_word": "涉嫌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "警方等怀疑某人与违法犯罪事件有关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '246cb159-8ced-40af-9dd4-ae34aecf1ef8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95580, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "涉嫌", "is_correct": true, "explanation": "正确。涉嫌表示被怀疑与违法事件有关，与释义一致。"}, {"text": "射线", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）声调不同，“射线”指射出的光线，意思与“涉嫌”不同。"}, {"text": "涉险", "is_correct": false, "explanation": "xián（第二声）与 xiǎn（第三声）只差声调，“涉险”指冒险，意思与“涉嫌”不同。"}, {"text": "设限", "is_correct": false, "explanation": "xián（第二声）与 xiàn（第四声）只差声调，“设限”指设定界限，意思与“涉嫌”不同。"}], "explanations": {"涉嫌": "正确。涉嫌表示被怀疑与违法事件有关，与释义一致。", "射线": "xián（第二声）与 xiàn（第四声）声调不同，“射线”指射出的光线，意思与“涉嫌”不同。", "涉险": "xián（第二声）与 xiǎn（第三声）只差声调，“涉险”指冒险，意思与“涉嫌”不同。", "设限": "xián（第二声）与 xiàn（第四声）只差声调，“设限”指设定界限，意思与“涉嫌”不同。"}, "sentence_index": null, "correct_answer": "涉嫌"}, "level_3": {"options": [{"text": "涉嫌", "is_correct": true, "explanation": "正确。“警方说”和“正在调查”表示被怀疑，只有“涉嫌”符合语境。"}, {"text": "赞扬", "is_correct": false, "explanation": "语义：“赞扬”是称赞，说别人赞扬诈骗与法律语境相悖。"}, {"text": "证明", "is_correct": false, "explanation": "配价：“证明”要接一件待证的事实，不能直接带“诈骗”这样的动作宾语。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”表示为喜事欢庆，与“诈骗”及“正在调查”的语境不符。"}], "explanations": {"涉嫌": "正确。“警方说”和“正在调查”表示被怀疑，只有“涉嫌”符合语境。", "赞扬": "语义：“赞扬”是称赞，说别人赞扬诈骗与法律语境相悖。", "证明": "配价：“证明”要接一件待证的事实，不能直接带“诈骗”这样的动作宾语。", "庆祝": "语义：“庆祝”表示为喜事欢庆，与“诈骗”及“正在调查”的语境不符。"}, "sentence_index": 0, "correct_answer": "涉嫌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他涉嫌经常迟到，老板很不满意。", "explanation": "涉嫌只用于违法或犯罪行为，经常迟到不属于这类事情，这个词不这么用。"}, {"text": "大家涉嫌他说谎，所以不相信他。", "explanation": "这里应该用〈怀疑〉。涉嫌描述的是被怀疑与违法有关的人，说话人的怀疑只能用怀疑。"}, {"text": "这个问题涉嫌很多方面，需要慢慢研究。", "explanation": "这里应该用〈涉及〉。涉嫌表示被怀疑与违法事件有关，问题牵扯的方面只能说涉及。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "涉嫌", "is_correct": true, "explanation": "正确。“多起抢劫案”属于违法行为，只有“涉嫌”表示被怀疑与之有关。"}, {"text": "歌颂", "is_correct": false, "explanation": "语域：“歌颂”是书面语的颂扬，且语义正面，不能用于抢劫案。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”搭配作品、才能，不能接“抢劫案”这样的违法事件。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，与“抢劫案”的违法语境完全相悖。"}], "explanations": {"涉嫌": "正确。“多起抢劫案”属于违法行为，只有“涉嫌”表示被怀疑与之有关。", "歌颂": "语域：“歌颂”是书面语的颂扬，且语义正面，不能用于抢劫案。", "欣赏": "搭配：“欣赏”搭配作品、才能，不能接“抢劫案”这样的违法事件。", "夸": "语义：“夸”是称赞，与“抢劫案”的违法语境完全相悖。"}, "sentence_index": 6, "correct_answer": "涉嫌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这三个年轻人涉嫌获奖，学校很高兴。", "explanation": "涉嫌只用于违法或不良行为，获奖是正面的事，这个词不这么用。"}, {"text": "他涉嫌借书给同学，同学们都很感谢他。", "explanation": "涉嫌表示被怀疑与违法事件有关，正常借书不能用涉嫌。"}, {"text": "他涉嫌公司太远，就辞职了。", "explanation": "这里应该用〈嫌〉。嫌表示不满意，涉嫌只用于被怀疑违法的事，不能用来说公司太远。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他涉嫌着诈骗，警方正在调查。", "corrected_sentence": "他涉嫌诈骗，警方正在调查。", "error_description": "“着”用错了。“涉嫌”表示被怀疑的状态，不能带“着”，应说“涉嫌诈骗”，不能说“涉嫌着诈骗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他涉嫌了抢劫，警察正在找他。", "corrected_sentence": "他涉嫌抢劫，警察正在找他。", "error_description": "“了”用错了位置。“涉嫌”表示被怀疑的状态，后面不能直接加“了”，应说“涉嫌抢劫”，不能说“涉嫌了抢劫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
