INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95581, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一件事变得越来越深入。", "primary_collocate": null, "pronunciation": "shēn huà", "ipa": "ʂən˥ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "我们要深化对这个问题的理解。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次学习深化了我对中国文化的认识。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想进一步深化两国的合作。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望通过讨论深化大家对这个话题的认识。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书能深化你对生活的理解。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校决定深化教学改革。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行深化了我们之间的友谊。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想深化自己对法律的认识。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要深化这项工作，需要更多的时间。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该深化对课文的理解，不能只看表面。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深化了", "label": "体标"}, {"form": "深化着", "label": "体标"}, {"form": "深化过", "label": "体标"}], "register": "书面", "sense_fingerprint": "及物，使认识、合作、改革等更深入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95581, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深化", "is_correct": true, "explanation": "正确答案。深化：让认识、合作、改革等变得更深入。"}, {"text": "神话", "is_correct": false, "explanation": "shén（第二声）与 shēn（第一声）声调不同，意思是神话故事。"}, {"text": "真话", "is_correct": false, "explanation": "zhēn 与 shēn 声母不同（zh 与 sh），意思是真话。"}, {"text": "生化", "is_correct": false, "explanation": "shēng 与 shēn 韵母不同（ng 与 n），意思是生物化学。"}], "explanations": {"深化": "正确答案。深化：让认识、合作、改革等变得更深入。", "神话": "shén（第二声）与 shēn（第一声）声调不同，意思是神话故事。", "真话": "zhēn 与 shēn 声母不同（zh 与 sh），意思是真话。", "生化": "shēng 与 shēn 韵母不同（ng 与 n），意思是生物化学。"}, "sentence_index": null, "correct_answer": "深化"}, "level_3": {"options": [{"text": "深化", "is_correct": true, "explanation": "正确答案。“深化对……的理解”表示使理解更深入，与句意一致。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”意为不再要，与“要……理解”的意图相反，句意矛盾。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”的对象是文字、文件或记录，不能接“对……的理解”。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“要……理解”的目标相反，句子不通。"}], "explanations": {"深化": "正确答案。“深化对……的理解”表示使理解更深入，与句意一致。", "放弃": "语义：“放弃”意为不再要，与“要……理解”的意图相反，句意矛盾。", "删除": "搭配：“删除”的对象是文字、文件或记录，不能接“对……的理解”。", "忘记": "语义：“忘记”与“要……理解”的目标相反，句子不通。"}, "sentence_index": 0, "correct_answer": "深化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司今年深化了员工的人数。", "explanation": "这里应该用〈增加〉。深化指认识、合作等程度加深，员工人数这类数量要用增加。"}, {"text": "这家公司决定深化业务的范围。", "explanation": "这里应该用〈扩大〉。深化指程度加深，业务范围讲的是广度，要用扩大。"}, {"text": "工人们深化了那个水池。", "explanation": "这里应该用〈加深〉。深化用于认识、关系等抽象事物的程度加深，水池的深浅是具体的物理深度，要用加深。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深化", "is_correct": true, "explanation": "正确答案。“深化了友谊”表示使友谊更深厚，与句意一致。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造出新事物，友谊不能被发明，句意不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：句子说旅行使友谊加深，“拒绝”与这个结果相反，且旅行不能拒绝友谊。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言文字，不能接“友谊”作宾语。"}], "explanations": {"深化": "正确答案。“深化了友谊”表示使友谊更深厚，与句意一致。", "发明": "语义：“发明”指创造出新事物，友谊不能被发明，句意不通。", "拒绝": "语义：句子说旅行使友谊加深，“拒绝”与这个结果相反，且旅行不能拒绝友谊。", "翻译": "搭配：“翻译”的对象是语言文字，不能接“友谊”作宾语。"}, "sentence_index": 6, "correct_answer": "深化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次培训深化了学习的时间。", "explanation": "这里应该用〈延长〉。深化指认识、关系等程度加深，时间的长短要用延长。"}, {"text": "两家公司决定深化一份合同。", "explanation": "这里应该用〈订立〉。深化用于抽象的认识或关系，具体的合同要用订立。"}, {"text": "这家店决定深化三家分店。", "explanation": "这里应该用〈开设〉。深化不用于可以计数的具体机构，开设分店要用开设。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要进一步深化得对这个问题的理解。", "corrected_sentence": "我们要进一步深化对这个问题的理解。", "error_description": "错误形式“深化得”；“得”要引出补语，后面需接形容词或程度短语，这里直接接“对……理解”，结构不成立。应去掉“得”，写作“深化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校正在深化了教学改革。", "corrected_sentence": "学校正在深化教学改革。", "error_description": "错误形式“正在深化了”；“正在”表示动作进行中，不能与“了”同用。应去掉“了”，写作“正在深化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
