INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95582, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事物自身逐步向更深的程度发展。", "primary_collocate": null, "pronunciation": "shēn huà", "ipa": "ʂən˥ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "两国的合作不断深化。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着学习，我们的理解慢慢深化了。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改革正在一步一步深化。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "矛盾深化以后，事情更难解决了。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过几年努力，两地关系深化了。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题深化到这个地步，大家都没想到。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间的了解逐渐深化。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划会在明年继续深化。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "危机深化时，公司只好关门。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的感情随着相处不断深化。", "target_word": "深化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深化了", "label": "体标"}, {"form": "深化着", "label": "体标"}, {"form": "深化过", "label": "体标"}], "register": "书面", "sense_fingerprint": "不及物，事物自身向更深程度发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95582, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深化", "is_correct": true, "explanation": "正确答案。深化：事物向更深的程度发展。"}, {"text": "神话", "is_correct": false, "explanation": "shén（第二声）与 shēn（第一声）声调不同，意思是神话故事。"}, {"text": "真话", "is_correct": false, "explanation": "zhēn 与 shēn 声母不同（zh 与 sh），意思是真话。"}, {"text": "生化", "is_correct": false, "explanation": "shēng 与 shēn 韵母不同（ng 与 n），意思是生物化学。"}], "explanations": {"深化": "正确答案。深化：事物向更深的程度发展。", "神话": "shén（第二声）与 shēn（第一声）声调不同，意思是神话故事。", "真话": "zhēn 与 shēn 声母不同（zh 与 sh），意思是真话。", "生化": "shēng 与 shēn 韵母不同（ng 与 n），意思是生物化学。"}, "sentence_index": null, "correct_answer": "深化"}, "level_3": {"options": [{"text": "深化", "is_correct": true, "explanation": "正确答案。“合作不断深化”表示合作自身向更深的程度发展。"}, {"text": "切断", "is_correct": false, "explanation": "配价：“切断”需要带宾语，“合作不断切断”缺少宾语，且合作不能被直接切断。"}, {"text": "生病", "is_correct": false, "explanation": "语义：合作不会生病，这个词用在“合作”上句子不通。"}, {"text": "打破", "is_correct": false, "explanation": "配价：“打破”必须带宾语，如“打破僵局”，这里没有宾语，配价不符。"}], "explanations": {"深化": "正确答案。“合作不断深化”表示合作自身向更深的程度发展。", "切断": "配价：“切断”需要带宾语，“合作不断切断”缺少宾语，且合作不能被直接切断。", "生病": "语义：合作不会生病，这个词用在“合作”上句子不通。", "打破": "配价：“打破”必须带宾语，如“打破僵局”，这里没有宾语，配价不符。"}, "sentence_index": 0, "correct_answer": "深化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条铁路不断深化。", "explanation": "这里应该用〈延伸〉。深化指程度加深，铁路的长度增加要用延伸。"}, {"text": "这家公司的员工数量不断深化。", "explanation": "这里应该用〈增长〉。深化说的是程度加深，数量的变化要用增长。"}, {"text": "两国的贸易规模不断深化。", "explanation": "这里应该用〈扩大〉。深化说的是程度加深，规模讲的是广度，要用扩大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深化", "is_correct": true, "explanation": "正确答案。“了解逐渐深化”表示了解自身逐步加深。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：“煮沸”指液体加热到沸腾，“了解”不能被煮沸，句意不通。"}, {"text": "挂号", "is_correct": false, "explanation": "搭配：“挂号”用于就医等场合，不能与“了解逐渐”搭配。"}, {"text": "打印", "is_correct": false, "explanation": "配价：“打印”需要带宾语，这里没有宾语，不能直接作谓语。"}], "explanations": {"深化": "正确答案。“了解逐渐深化”表示了解自身逐步加深。", "煮沸": "语义：“煮沸”指液体加热到沸腾，“了解”不能被煮沸，句意不通。", "挂号": "搭配：“挂号”用于就医等场合，不能与“了解逐渐”搭配。", "打印": "配价：“打印”需要带宾语，这里没有宾语，不能直接作谓语。"}, "sentence_index": 6, "correct_answer": "深化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的时间不断深化。", "explanation": "这里应该用〈延长〉。深化说的是程度加深，时间的长短要用延长。"}, {"text": "城市的人口不断深化。", "explanation": "这里应该用〈增长〉。深化说的是程度加深，人口数量的变化要用增长。"}, {"text": "这个消息在网上不断深化。", "explanation": "这里应该用〈传播〉。深化说的是程度加深，消息的扩散要用传播。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国的合作很深化。", "corrected_sentence": "两国的合作正在深化。", "error_description": "错误形式“很深化”；“很”一般修饰形容词或状态性词语，“深化”是动词，不能用“很”修饰。应改为“正在深化”，表示进行中。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国的合作还在深化得。", "corrected_sentence": "两国的合作还在深化。", "error_description": "错误形式“深化得”；“得”后面要接补语，句中没有补语，应去掉“得”，写作“还在深化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
