INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95584, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "以某段时间为限期。", "primary_collocate": null, "pronunciation": "wéi qī", "ipa": "weɪ˧˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这项工作为期一个月，必须按时做完。", "target_word": "为期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给我们的任务为期两周。", "target_word": "为期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的复习为期十天，时间很紧。", "target_word": "为期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的签证为期三十天，到期要离开。", "target_word": "为期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张借书证为期一年，过了就不能用。", "target_word": "为期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目为期三个月，到时必须完成。", "target_word": "为期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张优惠券为期一周，过期就不能用了。", "target_word": "为期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房合同为期一年，到期要重新签。", "target_word": "为期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名时间为期五天，请大家抓紧时间。", "target_word": "为期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔借款为期半年，到期必须还清。", "target_word": "为期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "以一段时间作为期限，到期要完成或失效", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2290f97-813e-403b-b4d6-f3b690dd389f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95584, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为期", "is_correct": true, "explanation": "正确答案：为期（wéi qī）。"}, {"text": "围棋", "is_correct": false, "explanation": "wéi qí（第二声）与 wéi qī（第一声）只有第二个音节声调不同，围棋指一种棋类游戏。"}, {"text": "尾气", "is_correct": false, "explanation": "wěi qì 与 wéi qī 两个音节声调都不同，尾气指汽车排出的废气。"}, {"text": "维基", "is_correct": false, "explanation": "wéi jī 与 wéi qī 的第二个音节声母不同（j 与 q），维基指维基百科等网络百科。"}, {"text": "为之", "is_correct": false, "explanation": "wéi zhī 与 wéi qī 的第二个音节声母不同（zh 与 q），为之指做、办某件事。"}], "explanations": {"为期": "正确答案：为期（wéi qī）。", "围棋": "wéi qí（第二声）与 wéi qī（第一声）只有第二个音节声调不同，围棋指一种棋类游戏。", "尾气": "wěi qì 与 wéi qī 两个音节声调都不同，尾气指汽车排出的废气。", "维基": "wéi jī 与 wéi qī 的第二个音节声母不同（j 与 q），维基指维基百科等网络百科。", "为之": "wéi zhī 与 wéi qī 的第二个音节声母不同（zh 与 q），为之指做、办某件事。"}, "sentence_index": null, "correct_answer": "为期"}, "level_3": {"options": [{"text": "为期", "is_correct": true, "explanation": "正确答案。“为期一个月”说明工作规定的时限，与“必须按时做完”相符。"}, {"text": "完成", "is_correct": false, "explanation": "配价：完成的宾语是任务本身，不能直接带一段时间。"}, {"text": "发布", "is_correct": false, "explanation": "搭配：发布的对象是消息或文件，不能带一段时间，句子说不通。"}, {"text": "拖", "is_correct": false, "explanation": "语义：拖表示拖延，与后文“必须按时做完”的要求相矛盾。"}], "explanations": {"为期": "正确答案。“为期一个月”说明工作规定的时限，与“必须按时做完”相符。", "完成": "配价：完成的宾语是任务本身，不能直接带一段时间。", "发布": "搭配：发布的对象是消息或文件，不能带一段时间，句子说不通。", "拖": "语义：拖表示拖延，与后文“必须按时做完”的要求相矛盾。"}, "sentence_index": 0, "correct_answer": "为期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心情为期一周。", "explanation": "这里应该用〈维持〉。为期指事先定好的期限，心情的保持不是事先约定的，不能说为期。"}, {"text": "他的感冒为期一周。", "explanation": "这里应该用〈拖〉。为期用于事先定下的时限，病情拖延的时间不说为期。"}, {"text": "他在朋友家为期一天。", "explanation": "这里应该用〈逗留〉。为期指事先定好的期限，人在某处的停留要说逗留。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95584, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "为期", "is_correct": true, "explanation": "正确答案：为期（wéi qī）。"}, {"text": "胃气", "is_correct": false, "explanation": "wèi qì 与 wéi qī 声调不同，胃气指中医所说的脾胃功能。"}, {"text": "为其", "is_correct": false, "explanation": "wèi qí 与 wéi qī 两个音节声调都不同，为其指“为了它”。"}, {"text": "喂鸡", "is_correct": false, "explanation": "wèi jī 与 wéi qī 声调不同，第二个音节声母也不同（j 与 q），喂鸡指给鸡喂食。"}], "explanations": {"为期": "正确答案：为期（wéi qī）。", "胃气": "wèi qì 与 wéi qī 声调不同，胃气指中医所说的脾胃功能。", "为其": "wèi qí 与 wéi qī 两个音节声调都不同，为其指“为了它”。", "喂鸡": "wèi jī 与 wéi qī 声调不同，第二个音节声母也不同（j 与 q），喂鸡指给鸡喂食。"}, "sentence_index": null, "correct_answer": "为期"}, "level_3": {"options": [{"text": "为期", "is_correct": true, "explanation": "正确答案。“为期一周”说明优惠券的有效期限，与“过期就不能用了”相符。"}, {"text": "兑换", "is_correct": false, "explanation": "搭配：兑换的对象是物品或积分，不能带一段时间，与“过期就不能用了”的语境也不合。"}, {"text": "报废", "is_correct": false, "explanation": "语义：报废表示作废、不能再用，与“一周”的有效期限相矛盾。"}, {"text": "领取", "is_correct": false, "explanation": "搭配：领取的宾语是物品，不能带时段，且与后文的过期说法不合。"}], "explanations": {"为期": "正确答案。“为期一周”说明优惠券的有效期限，与“过期就不能用了”相符。", "兑换": "搭配：兑换的对象是物品或积分，不能带一段时间，与“过期就不能用了”的语境也不合。", "报废": "语义：报废表示作废、不能再用，与“一周”的有效期限相矛盾。", "领取": "搭配：领取的宾语是物品，不能带时段，且与后文的过期说法不合。"}, "sentence_index": 6, "correct_answer": "为期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的回信为期两天。", "explanation": "这里应该用〈延误〉。为期指事先定好的期限，回信的迟延不说为期。"}, {"text": "我们为期一个下午。", "explanation": "这里应该用〈等待〉。为期用于事先定下的时限，等人的时间不说为期。"}, {"text": "这桩纠纷为期三年。", "explanation": "这里应该用〈拖延〉。为期指事先约定的期限，纠纷拖延的时间不能用为期来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个活动为期一次，报名从明天开始。", "corrected_sentence": "这个活动为期一天，报名从明天开始。", "error_description": "“为期”后面的时段要用时间单位，“一次”说的是次数，不能表示期限，应说“为期一天”，不能说“为期一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次展览为期一个，门票很便宜。", "corrected_sentence": "这次展览为期一个月，门票很便宜。", "error_description": "表示时长要带时间单位，应说“为期一个月”，不能只说“为期一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '581bafa4-6afc-4440-932f-ec1251b66e5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
