INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95586, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95586, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "旧指统治者残暴、不行正道。", "primary_collocate": null, "pronunciation": "wú dào", "ipa": "u˧˥ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "昏君无道，百姓的日子很苦。", "target_word": "无道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候有个国王无道，人人都怕他。", "target_word": "无道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位皇帝无道，最后被人推翻了。", "target_word": "无道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王无道，国家很快就乱了。", "target_word": "无道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里说，这个朝代的皇帝非常无道。", "target_word": "无道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个无道的君王，杀了很多好人。", "target_word": "无道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "百姓们都说，这位皇帝太无道了。", "target_word": "无道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国君无道，大臣们都离开了他。", "target_word": "无道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，无道的皇帝常常失去天下。", "target_word": "无道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝无道，农民只好起来反抗。", "target_word": "无道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "旧时形容君王、统治者残暴不行正道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68172a49-6bff-4d36-b5dd-387d44ec8460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95586, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无道", "is_correct": true, "explanation": "正确答案。无道（wú dào）：旧指统治者残暴，不行正道。"}, {"text": "武道", "is_correct": false, "explanation": "wǔ dào（第三声）与 wú dào（第二声）第一音节声调不同，意思是武术之道。"}, {"text": "误导", "is_correct": false, "explanation": "wù dǎo 两个音节的声调都与 wú dào 不同，意思是引人误解、把人带偏。"}, {"text": "悟道", "is_correct": false, "explanation": "第一音节 wù（第四声）与 wú（第二声）声调不同，意思是领悟道理。"}, {"text": "鱼道", "is_correct": false, "explanation": "yú 与 wú 只差一个元音（ü 与 u），声调相同，意思是供鱼类洄游通过的水道。"}], "explanations": {"无道": "正确答案。无道（wú dào）：旧指统治者残暴，不行正道。", "武道": "wǔ dào（第三声）与 wú dào（第二声）第一音节声调不同，意思是武术之道。", "误导": "wù dǎo 两个音节的声调都与 wú dào 不同，意思是引人误解、把人带偏。", "悟道": "第一音节 wù（第四声）与 wú（第二声）声调不同，意思是领悟道理。", "鱼道": "yú 与 wú 只差一个元音（ü 与 u），声调相同，意思是供鱼类洄游通过的水道。"}, "sentence_index": null, "correct_answer": "无道"}, "level_3": {"options": [{"text": "慈祥", "is_correct": false, "explanation": "语义：“慈祥”指温和仁爱，与“昏君……，百姓的日子很苦”的语境矛盾。"}, {"text": "无道", "is_correct": true, "explanation": "正确答案。“无道”指统治者残暴、不行正道，与“昏君……，百姓的日子很苦”的语境相符。"}, {"text": "清醒", "is_correct": false, "explanation": "语义：“清醒”指头脑明白，与“昏君”的“昏”相反。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描写人的体形，不能用来评价统治者的行为。"}], "explanations": {"慈祥": "语义：“慈祥”指温和仁爱，与“昏君……，百姓的日子很苦”的语境矛盾。", "无道": "正确答案。“无道”指统治者残暴、不行正道，与“昏君……，百姓的日子很苦”的语境相符。", "清醒": "语义：“清醒”指头脑明白，与“昏君”的“昏”相反。", "瘦": "体貌：“瘦”描写人的体形，不能用来评价统治者的行为。"}, "sentence_index": 0, "correct_answer": "无道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小镇的天气很无道，连下了一个月的雨。", "explanation": "这里应该用〈恶劣〉。“无道”指统治者残暴、不行正道，只用于说统治者的所作所为，不能形容天气。"}, {"text": "这道数学题很无道，我一点也做不出来。", "explanation": "这里应该用〈难〉。“无道”指统治者残暴、不行正道，不能用来形容题目的难易。"}, {"text": "这种药很无道，吃下去胃里火辣辣的。", "explanation": "这里应该用〈猛烈〉。“无道”指统治者残暴、不行正道，不能用来形容药性的强弱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95586, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无道", "is_correct": true, "explanation": "正确答案。无道（wú dào）：旧指统治者残暴，不行正道。"}, {"text": "武道", "is_correct": false, "explanation": "wǔ dào（第三声）与 wú dào（第二声）第一音节声调不同，意思是武术之道。"}, {"text": "误导", "is_correct": false, "explanation": "wù dǎo 两个音节的声调都与 wú dào 不同，意思是引人误解、把人带偏。"}, {"text": "舞刀", "is_correct": false, "explanation": "wǔ dāo 第一音节声调与 wú 不同，第二音节 dāo（第一声）与 dào（第四声）声调不同，意思是挥舞刀具。"}, {"text": "舞蹈", "is_correct": false, "explanation": "wǔ dǎo 两个音节声调都与 wú dào 不同，意思是跳舞。"}], "explanations": {"无道": "正确答案。无道（wú dào）：旧指统治者残暴，不行正道。", "武道": "wǔ dào（第三声）与 wú dào（第二声）第一音节声调不同，意思是武术之道。", "误导": "wù dǎo 两个音节的声调都与 wú dào 不同，意思是引人误解、把人带偏。", "舞刀": "wǔ dāo 第一音节声调与 wú 不同，第二音节 dāo（第一声）与 dào（第四声）声调不同，意思是挥舞刀具。", "舞蹈": "wǔ dǎo 两个音节声调都与 wú dào 不同，意思是跳舞。"}, "sentence_index": null, "correct_answer": "无道"}, "level_3": {"options": [{"text": "细长", "is_correct": false, "explanation": "体貌：“细长”描写形体，不能用来评价皇帝的统治。"}, {"text": "无道", "is_correct": true, "explanation": "正确答案。“无道”指统治者残暴、不行正道，与“百姓们都说，这位皇帝太……了”的语境相符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不用来形容皇帝。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，与评价皇帝的语境不相符。"}], "explanations": {"细长": "体貌：“细长”描写形体，不能用来评价皇帝的统治。", "无道": "正确答案。“无道”指统治者残暴、不行正道，与“百姓们都说，这位皇帝太……了”的语境相符。", "热闹": "搭配：“热闹”形容场面或气氛，不用来形容皇帝。", "清脆": "语义：“清脆”形容声音，与评价皇帝的语境不相符。"}, "sentence_index": 6, "correct_answer": "无道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座老房子很无道，墙上裂着大缝。", "explanation": "这里应该用〈破旧〉。“无道”指统治者残暴、不行正道，不能用来形容房屋的新旧和破损。"}, {"text": "这篇文章很无道，句子都不通顺。", "explanation": "这里应该用〈拙劣〉。“无道”指统治者残暴、不行正道，不能用来评价文章的质量。"}, {"text": "这首歌很无道，大家都很爱听。", "explanation": "这里应该用〈动听〉。“无道”指统治者残暴、不行正道，不能用来评价歌曲好听与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个君主越来越了无道，百姓的日子也越来越苦。", "corrected_sentence": "那个君主越来越无道，百姓的日子也越来越苦。", "error_description": "错误形式「越来越了无道」在“无道”前多加了“了”；正确形式「越来越无道」中，“越来越”直接修饰形容词“无道”，不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个皇帝太了无道了，大家都不敢说话。", "corrected_sentence": "那个皇帝太无道了，大家都不敢说话。", "error_description": "错误形式「太了无道了」在“太”和“无道”之间多加了“了”；正确形式「太无道了」中，“太”直接修饰形容词“无道”，“了”只放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ccbd355-7150-4b47-8fcf-b045294aacf4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
