INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95587, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "花力气把一个地方做成某种样子。", "primary_collocate": null, "pronunciation": "yíng zào", "ipa": "iŋ˧˥ tsau˥˩", "syllable_count": 2, "sentences": [{"text": "她花了很多时间，把小房间营造成一个温馨的书房。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想把这家小店营造成安静的咖啡馆。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用花和灯营造出一个漂亮的小院子。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天打扫，营造一个干净的家。", "target_word": "营造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想在阳台上营造一个小花园。", "target_word": "营造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校花了一年，把废弃的教室营造成了一个安静的读书角。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师把客厅营造成了森林一样的空间。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想营造一个适合孩子玩的小乐园。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人花钱营造了一个安静的小花园。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了住得舒服，她用木头营造出一个温暖的角落。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "营造了", "label": "体标"}, {"form": "营造着", "label": "体标"}, {"form": "营造过", "label": "体标"}, {"form": "營造", "label": "繁体"}], "register": "书面", "sense_fingerprint": "花力气把某个地方布置、打造成某种样子（如温馨的家、安静的咖啡馆）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7505f76d-2f05-4bdb-821e-935ffba3ab82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95587, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "营造", "is_correct": true, "explanation": "正确答案。“营造”指花力气把地方布置成某种样子，符合“把小房间营造成一个温馨的书房”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”只表示清除脏物，不能使房间变成书房。"}, {"text": "出租", "is_correct": false, "explanation": "语义：“出租”是把房子租给别人，与“变成温馨的书房”无关。"}, {"text": "使用", "is_correct": false, "explanation": "配价：“使用”后接宾语，不能接“成”构成“把……成……”结构。"}], "explanations": {"营造": "正确答案。“营造”指花力气把地方布置成某种样子，符合“把小房间营造成一个温馨的书房”。", "打扫": "语义：“打扫”只表示清除脏物，不能使房间变成书房。", "出租": "语义：“出租”是把房子租给别人，与“变成温馨的书房”无关。", "使用": "配价：“使用”后接宾语，不能接“成”构成“把……成……”结构。"}, "sentence_index": 0, "correct_answer": "营造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位科学家营造了一个新的理论。", "explanation": "这里应该用〈创造〉。营造用于环境、气氛，不用于理论、成果。"}, {"text": "工厂营造了很多汽车。", "explanation": "这里应该用〈制造〉。营造指布置环境或创造气氛，不用于产品的生产。"}, {"text": "公司营造了一款新手机。", "explanation": "这里应该用〈打造〉。营造用于环境、氛围，不用于具体的产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95587, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "营造", "is_correct": true, "explanation": "正确答案。“营造”指有意识地把客厅布置成某种环境，符合“营造成了森林一样的空间”。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护卫，不能把客厅保护成森林一样的空间。"}, {"text": "砍伐", "is_correct": false, "explanation": "搭配：“砍伐”的对象是树木，不能用于客厅。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”是拆掉，与“造出森林一样的空间”的意思相反。"}], "explanations": {"营造": "正确答案。“营造”指有意识地把客厅布置成某种环境，符合“营造成了森林一样的空间”。", "保护": "语义：“保护”是护卫，不能把客厅保护成森林一样的空间。", "砍伐": "搭配：“砍伐”的对象是树木，不能用于客厅。", "拆除": "语义：“拆除”是拆掉，与“造出森林一样的空间”的意思相反。"}, "sentence_index": 6, "correct_answer": "营造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校营造了一场音乐会。", "explanation": "这里应该用〈举办〉。营造指布置或创造环境、气氛，不用于一场活动。"}, {"text": "医生营造了一次手术。", "explanation": "这里应该用〈进行〉。营造不能用于手术这类具体操作。"}, {"text": "他营造了一次登山活动。", "explanation": "这里应该用〈组织〉。营造不能用于组织活动，活动应说“组织”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95587, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐想在窗台上营造了一个小花园。", "corrected_sentence": "姐姐想在窗台上营造一个小花园。", "error_description": "体标误用：“想”表示意愿，其后的动词不能直接带“了”，应为“想营造一个小花园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95587, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把旧仓库营造了温馨的书店。", "corrected_sentence": "他把旧仓库营造成了温馨的书店。", "error_description": "补语缺失：“把……营造成……”中的补语“成”不可省略，应为“营造成了温馨的书店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
