INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95588, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "建造；有意识地创造某种环境或气氛。", "primary_collocate": null, "pronunciation": "yíng zào", "ipa": "iŋ˧˥ tsau˥˩", "syllable_count": 2, "sentences": [{"text": "老师用游戏营造轻松的课堂气氛。", "target_word": "营造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯光和音乐营造出浪漫的气氛。", "target_word": "营造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想为员工营造一个好的工作环境。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝色的墙营造出安静、舒服的感觉。", "target_word": "营造", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他讲了个笑话，营造了轻松的气氛。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影用黑白画面营造着紧张的气氛。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母应该给孩子营造良好的成长环境。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她点了蜡烛，营造出过生日的气氛。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要一起营造干净、安全的学习环境。", "target_word": "营造", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热闹的音乐营造了节日的气氛。", "target_word": "营造", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "营造了", "label": "体标"}, {"form": "营造着", "label": "体标"}, {"form": "营造过", "label": "体标"}, {"form": "營造", "label": "繁体"}], "register": "书面", "sense_fingerprint": "有意识地创造某种气氛、环境或感觉（如轻松的气氛、良好的环境）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7505f76d-2f05-4bdb-821e-935ffba3ab82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "营造", "is_correct": true, "explanation": "正确答案。“营造”指有意识地创造某种气氛，符合“营造轻松的课堂气氛”。"}, {"text": "讲解", "is_correct": false, "explanation": "搭配：“讲解”的对象是知识或内容，不能说“讲解气氛”。"}, {"text": "检查", "is_correct": false, "explanation": "搭配：“检查”的对象是作业、质量等，不能用于“课堂气氛”。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”是毁坏，与“轻松的课堂气氛”的意思相反。"}], "explanations": {"营造": "正确答案。“营造”指有意识地创造某种气氛，符合“营造轻松的课堂气氛”。", "讲解": "搭配：“讲解”的对象是知识或内容，不能说“讲解气氛”。", "检查": "搭配：“检查”的对象是作业、质量等，不能用于“课堂气氛”。", "破坏": "语义：“破坏”是毁坏，与“轻松的课堂气氛”的意思相反。"}, "sentence_index": 0, "correct_answer": "营造"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场雨营造了严重的交通堵塞。", "explanation": "这里应该用〈造成〉。营造用于环境、气氛，不用于交通堵塞等负面后果。"}, {"text": "这件事营造了大家的关注。", "explanation": "这里应该用〈引起〉。营造的对象是环境或气氛，不能是“关注”。"}, {"text": "这项新技术营造了很大的影响。", "explanation": "这里应该用〈产生〉。营造的对象是环境或气氛，不用于“影响”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "营造", "is_correct": true, "explanation": "正确答案。“营造”指有意识地创造良好的环境，符合“营造良好的成长环境”。"}, {"text": "教育", "is_correct": false, "explanation": "搭配：“教育”的对象是人，不能说“教育成长环境”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、街道等具体地方，不能说“打扫成长环境”。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：“摧毁”是彻底毁掉，与“应该为孩子营造良好环境”的意思相反。"}], "explanations": {"营造": "正确答案。“营造”指有意识地创造良好的环境，符合“营造良好的成长环境”。", "教育": "搭配：“教育”的对象是人，不能说“教育成长环境”。", "打扫": "搭配：“打扫”的对象是房间、街道等具体地方，不能说“打扫成长环境”。", "摧毁": "语义：“摧毁”是彻底毁掉，与“应该为孩子营造良好环境”的意思相反。"}, "sentence_index": 6, "correct_answer": "营造"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这起事故营造了三人受伤。", "explanation": "这里应该用〈导致〉。营造用于环境、气氛，不用于事故的后果。"}, {"text": "这位运动员营造了一项新纪录。", "explanation": "这里应该用〈创造〉。营造用于环境、气氛，不用于纪录。"}, {"text": "工人们营造了一项任务。", "explanation": "这里应该用〈完成〉。营造不能用于任务，任务应说“完成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们为学生营造了一个安静的学习成绩。", "corrected_sentence": "他们为学生营造了一个安静的学习环境。", "error_description": "搭配错误：“营造”的对象是环境、气氛，不能说“营造学习成绩”，应为“营造了一个安静的学习环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节日，大家挂满红灯笼，营造了出喜庆的气氛。", "corrected_sentence": "这个节日，大家挂满红灯笼，营造出喜庆的气氛。", "error_description": "补语位置错误：结果补语“出”必须紧跟动词“营造”，中间不能插入“了”，应为“营造出喜庆的气氛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
