INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95589, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "特别激动，什么都不管。", "primary_collocate": null, "pronunciation": "kuáng", "ipa": "kʰuaŋ˧˥", "syllable_count": 1, "sentences": [{"text": "球赢了，全场的人都狂了。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到偶像，女孩们高兴得快狂了。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到中奖的消息，他激动得快狂了。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会上，歌迷们个个都狂了。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天晚上，大家喝着酒，唱着歌，狂了一夜。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一听说要放假，就高兴得狂起来。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在雪地里又跑又叫，玩得太狂了。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛最后一分钟进球，球迷们彻底狂了。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一看到打折，买起东西来就狂了。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，年轻人在街上又唱又跳，狂得什么都不管。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "狂：激动得什么都不管，失去控制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6c3ec9-8bf6-4b2f-9d66-249534f22bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95589, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "狂", "is_correct": true, "explanation": "狂（kuáng，第二声）是本词，指激动得什么都不管。"}, {"text": "况", "is_correct": false, "explanation": "况 kuàng（第四声）与 kuáng（第二声）声调不同，意思是情况。"}, {"text": "矿", "is_correct": false, "explanation": "矿 kuàng（第四声）与 kuáng 声调不同，意思是矿山。"}, {"text": "框", "is_correct": false, "explanation": "框 kuàng（第四声）与 kuáng 声调不同，意思是边框。"}, {"text": "筐", "is_correct": false, "explanation": "筐 kuāng（第一声）与 kuáng（第二声）声母韵母相同，仅声调不同，意思是竹筐。"}], "explanations": {"狂": "狂（kuáng，第二声）是本词，指激动得什么都不管。", "况": "况 kuàng（第四声）与 kuáng（第二声）声调不同，意思是情况。", "矿": "矿 kuàng（第四声）与 kuáng 声调不同，意思是矿山。", "框": "框 kuàng（第四声）与 kuáng 声调不同，意思是边框。", "筐": "筐 kuāng（第一声）与 kuáng（第二声）声母韵母相同，仅声调不同，意思是竹筐。"}, "sentence_index": null, "correct_answer": "狂"}, "level_3": {"options": [{"text": "狂", "is_correct": true, "explanation": "“狂”表示激动得什么都不管，与“球赢了”及“全场的人都……了”的场面相符。"}, {"text": "平静", "is_correct": false, "explanation": "语义：“球赢了”令全场兴奋，“平静”与此情境矛盾。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所或气氛，不用来形容人。"}, {"text": "沮丧", "is_correct": false, "explanation": "语义：“球赢了”是高兴的事，不会让全场的人“沮丧”。"}], "explanations": {"狂": "“狂”表示激动得什么都不管，与“球赢了”及“全场的人都……了”的场面相符。", "平静": "语义：“球赢了”令全场兴奋，“平静”与此情境矛盾。", "冷清": "搭配：“冷清”形容场所或气氛，不用来形容人。", "沮丧": "语义：“球赢了”是高兴的事，不会让全场的人“沮丧”。"}, "sentence_index": 0, "correct_answer": "狂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "演唱会结束后，那个歌手很狂，连歌迷的合影请求都拒绝了。", "explanation": "此处“狂”指放肆自大，是另一义项，与“特别激动、什么都不管”不同。"}, {"text": "这场风很狂，把树都吹倒了。", "explanation": "此处“狂”指风势极其猛烈，是另一义项，不是激动得什么都不管。"}, {"text": "他从来不把别人放在眼里，态度很狂。", "explanation": "此处“狂”指放肆自大，是另一义项，与“特别激动、什么都不管”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95589, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "狂", "is_correct": true, "explanation": "狂（kuáng，第二声）是本词，指激动得什么都不管。"}, {"text": "筐", "is_correct": false, "explanation": "筐 kuāng（第一声）与 kuáng 声调不同，意思是竹筐。"}, {"text": "旷", "is_correct": false, "explanation": "旷 kuàng（第四声）与 kuáng 声调不同，如“旷课”，意思是缺席或空阔。"}, {"text": "匡", "is_correct": false, "explanation": "匡 kuāng（第一声）与 kuáng（第二声）声母韵母相同，仅声调不同，意思是纠正。"}, {"text": "眶", "is_correct": false, "explanation": "眶 kuàng（第四声）与 kuáng 声调不同，意思是眼眶。"}], "explanations": {"狂": "狂（kuáng，第二声）是本词，指激动得什么都不管。", "筐": "筐 kuāng（第一声）与 kuáng 声调不同，意思是竹筐。", "旷": "旷 kuàng（第四声）与 kuáng 声调不同，如“旷课”，意思是缺席或空阔。", "匡": "匡 kuāng（第一声）与 kuáng（第二声）声母韵母相同，仅声调不同，意思是纠正。", "眶": "眶 kuàng（第四声）与 kuáng 声调不同，意思是眼眶。"}, "sentence_index": null, "correct_answer": "狂"}, "level_3": {"options": [{"text": "狂", "is_correct": true, "explanation": "“狂”表示玩得失去控制，与“又跑又叫”的状态一致。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“又跑又叫”与“安静”的状态相互矛盾。"}, {"text": "乖", "is_correct": false, "explanation": "语义：“乖”形容听话守规矩，与“又跑又叫”不符。"}, {"text": "严肃", "is_correct": false, "explanation": "搭配：“玩”不能与“严肃”搭配，“玩得严肃”不自然。"}], "explanations": {"狂": "“狂”表示玩得失去控制，与“又跑又叫”的状态一致。", "安静": "语义：“又跑又叫”与“安静”的状态相互矛盾。", "乖": "语义：“乖”形容听话守规矩，与“又跑又叫”不符。", "严肃": "搭配：“玩”不能与“严肃”搭配，“玩得严肃”不自然。"}, "sentence_index": 6, "correct_answer": "狂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他走路很狂，慢慢悠悠的，一点都不着急。", "explanation": "此处“狂”被用来表示缓慢，“狂”没有这个意思，它指激动失控、放肆或猛烈，与“慢慢悠悠”不符。"}, {"text": "他对老师说话很狂，老师气得直发抖。", "explanation": "此处“狂”指放肆自大，是另一义项，与“激动得什么都不管”不同。"}, {"text": "这个小姑娘很狂，说话轻声细语，从不大声。", "explanation": "此处“狂”被用来表示温和，“狂”没有这个意思，它指激动失控、放肆或猛烈，与“轻声细语”不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到好消息，大家高兴的狂起来了。", "corrected_sentence": "听到好消息，大家高兴得狂起来了。", "error_description": "错误：“高兴”后的补语标记应为“得”，不能用“的”。“的”用于修饰名词，这里要用“得”引出状态补语，即“高兴得狂起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到好消息，大家都狂下来了。", "corrected_sentence": "听到好消息，大家都狂起来了。", "error_description": "错误：“狂”后的趋向补语应为“起来”，表示情绪开始失控。“下来”表示由动到静或向下，不能说“狂下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
