INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95590, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "疯狂；极其猛烈或放肆。", "primary_collocate": null, "pronunciation": "kuáng", "ipa": "kʰuaŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他说话太狂了，大家都不喜欢他。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别那么狂，没人会喜欢你。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人一点都不狂，对谁都很客气。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻的时候很狂，谁的话都不听。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考了第一名，说话就变得有点狂。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人开车太狂了，差点撞到人。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑得太狂了，别人都看着他。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的口气真狂，好像什么都能做到。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个球员很狂，常常不听教练的话。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这个人狂得很，从来不把别人放在眼里。", "target_word": "狂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "狂：放肆自大，或风雨等极其猛烈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6c3ec9-8bf6-4b2f-9d66-249534f22bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95590, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "狂", "is_correct": true, "explanation": "狂（kuáng，第二声）是本词，指放肆自大或风雨极其猛烈。"}, {"text": "筐", "is_correct": false, "explanation": "筐 kuāng（第一声）与 kuáng 声调不同，意思是竹筐。"}, {"text": "匡", "is_correct": false, "explanation": "匡 kuāng（第一声）与 kuáng（第二声）声母韵母相同，仅声调不同，意思是纠正。"}, {"text": "眶", "is_correct": false, "explanation": "眶 kuàng（第四声）与 kuáng 声调不同，意思是眼眶。"}, {"text": "况", "is_correct": false, "explanation": "况 kuàng（第四声）与 kuáng（第二声）声调不同，意思是情况。"}], "explanations": {"狂": "狂（kuáng，第二声）是本词，指放肆自大或风雨极其猛烈。", "筐": "筐 kuāng（第一声）与 kuáng 声调不同，意思是竹筐。", "匡": "匡 kuāng（第一声）与 kuáng（第二声）声母韵母相同，仅声调不同，意思是纠正。", "眶": "眶 kuàng（第四声）与 kuáng 声调不同，意思是眼眶。", "况": "况 kuàng（第四声）与 kuáng（第二声）声调不同，意思是情况。"}, "sentence_index": null, "correct_answer": "狂"}, "level_3": {"options": [{"text": "狂", "is_correct": true, "explanation": "“狂”表示放肆自大，与“太……了”及“大家都不喜欢他”的评价相符。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所或气氛，不用来形容说话的样子。"}, {"text": "蓝", "is_correct": false, "explanation": "体貌：“蓝”描写颜色，不能用来形容说话。"}, {"text": "红", "is_correct": false, "explanation": "体貌：“红”描写颜色，不能用来形容说话。"}], "explanations": {"狂": "“狂”表示放肆自大，与“太……了”及“大家都不喜欢他”的评价相符。", "冷清": "搭配：“冷清”形容场所或气氛，不用来形容说话的样子。", "蓝": "体貌：“蓝”描写颜色，不能用来形容说话。", "红": "体貌：“红”描写颜色，不能用来形容说话。"}, "sentence_index": 0, "correct_answer": "狂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个女孩很狂，说话总是温温柔柔的。", "explanation": "此处“狂”被用来表示温柔，“狂”没有这个意思，它指疯狂或放肆，与“温温柔柔”不符。"}, {"text": "这位老奶奶很狂，走路慢慢的，从不着急。", "explanation": "此处“狂”被用来表示缓慢，“狂”没有这个意思，它指疯狂、猛烈或放肆，与“慢慢的”不符。"}, {"text": "这条小河很狂，水流得安安静静的。", "explanation": "此处“狂”被用来表示平静，“狂”没有这个意思，它指猛烈或放肆，与“安安静静”不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95590, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "狂", "is_correct": true, "explanation": "狂（kuáng，第二声）是本词，指放肆自大或风雨极其猛烈。"}, {"text": "矿", "is_correct": false, "explanation": "矿 kuàng（第四声）与 kuáng 声调不同，意思是矿山。"}, {"text": "框", "is_correct": false, "explanation": "框 kuàng（第四声）与 kuáng 声调不同，意思是边框。"}, {"text": "筐", "is_correct": false, "explanation": "筐 kuāng（第一声）与 kuáng（第二声）声母韵母相同，仅声调不同，意思是竹筐。"}, {"text": "旷", "is_correct": false, "explanation": "旷 kuàng（第四声）与 kuáng 声调不同，意思是空阔。"}], "explanations": {"狂": "狂（kuáng，第二声）是本词，指放肆自大或风雨极其猛烈。", "矿": "矿 kuàng（第四声）与 kuáng 声调不同，意思是矿山。", "框": "框 kuàng（第四声）与 kuáng 声调不同，意思是边框。", "筐": "筐 kuāng（第一声）与 kuáng（第二声）声母韵母相同，仅声调不同，意思是竹筐。", "旷": "旷 kuàng（第四声）与 kuáng 声调不同，意思是空阔。"}, "sentence_index": null, "correct_answer": "狂"}, "level_3": {"options": [{"text": "狂", "is_correct": true, "explanation": "“狂”表示放肆自大，与“笑得太……了”及“别人都看着他”的情境相符。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“笑”与“严肃”的表情相互矛盾，笑得严肃不合常理。"}, {"text": "沉默", "is_correct": false, "explanation": "搭配：“沉默”不能用来形容“笑”。"}, {"text": "白", "is_correct": false, "explanation": "体貌：“白”描写颜色，不能用来形容笑的程度。"}], "explanations": {"狂": "“狂”表示放肆自大，与“笑得太……了”及“别人都看着他”的情境相符。", "严肃": "语义：“笑”与“严肃”的表情相互矛盾，笑得严肃不合常理。", "沉默": "搭配：“沉默”不能用来形容“笑”。", "白": "体貌：“白”描写颜色，不能用来形容笑的程度。"}, "sentence_index": 6, "correct_answer": "狂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人性格很狂，说话软绵绵的，从来不敢反抗别人。", "explanation": "此处“狂”被用来表示软弱，“狂”没有这个意思，它指疯狂或放肆，与“软绵绵”“不敢反抗”不符。"}, {"text": "这间屋子很狂，干干净净的，一尘不染。", "explanation": "此处“狂”被用来表示干净，“狂”没有这个意思，它指疯狂、猛烈或放肆，与“干干净净”不符。"}, {"text": "他很狂，见到长辈总是鞠躬问好，特别懂礼貌。", "explanation": "此处“狂”被用来表示礼貌，“狂”没有这个意思，它指放肆或疯狂，与“鞠躬问好”不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他赢了一场比赛，就变得狂很。", "corrected_sentence": "他赢了一场比赛，就变得很狂。", "error_description": "错误：程度副词“很”应放在形容词“狂”前面，说“很狂”，不能说“狂很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人狂很得，谁的话都不听。", "corrected_sentence": "这个人狂得很，谁的话都不听。", "error_description": "错误：补语“得”应放在“狂”后，程度副词“很”放在“得”后，说“狂得很”，不能说“狂很得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
