INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "团体组织中负责处理事务的成员。", "primary_collocate": null, "pronunciation": "lǐ shì", "ipa": "li˨˩˦ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他是这个基金会的理事之一。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "协会新选了三位理事。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理事要负责处理会里的事务。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了很多年理事，对工作很熟。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公益组织的理事都不拿钱。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会的理事们开会讨论了预算。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选他为协会理事，他很高兴。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位理事每周都去学会处理事务。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张女士是我们社团的理事。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老理事要退休了，会里要选新人。", "target_word": "理事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "理事会", "label": "复合"}], "register": "书面", "sense_fingerprint": "理事：团体组织里负责处理事务的成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8cec2-0804-43a0-ae6c-4e8f96192c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95592, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "理事", "is_correct": true, "explanation": "理事：团体组织中负责处理事务的成员，即听到的词。"}, {"text": "历史", "is_correct": false, "explanation": "历史 lìshǐ 的两个音节声调都与理事 lǐshì 不同（lì 与 lǐ，shǐ 与 shì），意思是过去发生的事情。"}, {"text": "历时", "is_correct": false, "explanation": "历时 lìshí 第一音节声调不同（lì 与 lǐ），第二音节也不同（shí 与 shì），意思是经历的时间。"}, {"text": "力士", "is_correct": false, "explanation": "力士 lìshì 只有第一音节声调不同（lì 与 lǐ），意思是力气大的人。"}], "explanations": {"理事": "理事：团体组织中负责处理事务的成员，即听到的词。", "历史": "历史 lìshǐ 的两个音节声调都与理事 lǐshì 不同（lì 与 lǐ，shǐ 与 shì），意思是过去发生的事情。", "历时": "历时 lìshí 第一音节声调不同（lì 与 lǐ），第二音节也不同（shí 与 shì），意思是经历的时间。", "力士": "力士 lìshì 只有第一音节声调不同（lì 与 lǐ），意思是力气大的人。"}, "sentence_index": null, "correct_answer": "理事"}, "level_3": {"options": [{"text": "理事", "is_correct": true, "explanation": "理事：基金会中负责处理事务的成员，可以放在“……之一”前。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”指报酬，不指人，不能说成“基金会的工资之一”的身份。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是处所，不指担任职务的人。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：「黑板」是物品，不能作人的身份，“基金会的黑板之一”不成立。"}], "explanations": {"理事": "理事：基金会中负责处理事务的成员，可以放在“……之一”前。", "工资": "语义：“工资”指报酬，不指人，不能说成“基金会的工资之一”的身份。", "厨房": "语义：“厨房”是处所，不指担任职务的人。", "黑板": "语义：「黑板」是物品，不能作人的身份，“基金会的黑板之一”不成立。"}, "sentence_index": 0, "correct_answer": "理事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的理事每天给员工开会。", "explanation": "这里应该用〈经理〉。经理负责公司的日常管理，可以说“公司的经理”；理事用于协会、基金会等非营利团体，不用于公司。"}, {"text": "她是我们协会的一朵理事。", "explanation": "这里应该用〈位〉。指人的量词用“位”，“朵”用于花等物品。"}, {"text": "这棵大树是协会的理事。", "explanation": "这里应该用〈标志〉。标志是象征协会的事物，可以说“协会的标志”；理事指人，不能指植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理事", "is_correct": true, "explanation": "理事：协会里管事的成员，符合“选他为……”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物品，不能被选为职务。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人，不能被选为职务。"}, {"text": "小偷", "is_correct": false, "explanation": "配价：“选……为”后要接职务，“小偷”不是可选任的职务，句子也不合理。"}], "explanations": {"理事": "理事：协会里管事的成员，符合“选他为……”的语境。", "桌子": "语义：“桌子”是物品，不能被选为职务。", "天气": "语义：“天气”不是人，不能被选为职务。", "小偷": "配价：“选……为”后要接职务，“小偷”不是可选任的职务，句子也不合理。"}, "sentence_index": 6, "correct_answer": "理事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家银行有五位理事。", "explanation": "这里应该用〈董事〉。董事是银行等公司的管理成员，可以说“银行的董事”；理事用于协会、基金会等非营利团体，不用于银行。"}, {"text": "我们学会的一颗老理事今天来了。", "explanation": "这里应该用〈位〉。指人的量词用“位”，“颗”用于粒状或圆形的东西，不用于指人。"}, {"text": "这把椅子是老理事。", "explanation": "这里应该用〈老物件〉。老物件指旧的器物，可以说“这把椅子是老物件”；理事指人，不能指器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44041f6b-0e42-44e7-8ea2-cd747f944582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
