INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95593, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量田地大小的一个单位。", "primary_collocate": null, "pronunciation": "mǔ", "ipa": "mu˨˩˦", "syllable_count": 1, "sentences": [{"text": "你家的田有多少亩？", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农场有一百亩地。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想租五亩水田种菜。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的果园有四十亩。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块田只有一亩，种不了太多。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸种着八亩麦子。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片地大约二十亩，够种很多菜。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的地不大，才三亩。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王大叔养鱼的池塘有六亩。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李卖掉了十亩地。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "畝", "label": "繁体"}, {"form": "亩产", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用来说明田地大小的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95593, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亩", "is_correct": true, "explanation": "正确：亩（mǔ，第三声），量田地大小的单位。"}, {"text": "木", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是木头。"}, {"text": "慕", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是羡慕。"}, {"text": "墓", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是坟墓。"}, {"text": "募", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是募集。"}], "explanations": {"亩": "正确：亩（mǔ，第三声），量田地大小的单位。", "木": "mù（第四声）与 mǔ（第三声）声调不同，意思是木头。", "慕": "mù（第四声）与 mǔ（第三声）声调不同，意思是羡慕。", "墓": "mù（第四声）与 mǔ（第三声）声调不同，意思是坟墓。", "募": "mù（第四声）与 mǔ（第三声）声调不同，意思是募集。"}, "sentence_index": null, "correct_answer": "亩"}, "level_3": {"options": [{"text": "亩", "is_correct": true, "explanation": "正确：“亩”是量田地的单位，“多少亩”问田地的大小，符合句意。"}, {"text": "斤", "is_correct": false, "explanation": "搭配：“斤”是重量单位，不能用来问田地的大小。"}, {"text": "升", "is_correct": false, "explanation": "语义：“升”是容量单位，不能用来量田地。"}, {"text": "度", "is_correct": false, "explanation": "搭配：“度”用于温度、电量等，不说田地有多少度。"}], "explanations": {"亩": "正确：“亩”是量田地的单位，“多少亩”问田地的大小，符合句意。", "斤": "搭配：“斤”是重量单位，不能用来问田地的大小。", "升": "语义：“升”是容量单位，不能用来量田地。", "度": "搭配：“度”用于温度、电量等，不说田地有多少度。"}, "sentence_index": 0, "correct_answer": "亩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "从村子到镇上有五亩。", "explanation": "这里应该用〈公里〉。“亩”是面积单位，不能表示距离。"}, {"text": "我们班有三亩学生。", "explanation": "“亩”只用来量土地，不能用来量人；这里应该用“名”。"}, {"text": "她买了一亩衣服。", "explanation": "“亩”只用来量土地，不用来量衣服；买衣服应该用“件”或“套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
