INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95594, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "地积单位，一亩约为六百六十七平方米。", "primary_collocate": null, "pronunciation": "mǔ", "ipa": "mu˨˩˦", "syllable_count": 1, "sentences": [{"text": "一亩约六百六十七平方米。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家有三亩地。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地一共五亩。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷种了两亩玉米。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村每人分到一亩田。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一亩等于多少平方米？", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片菜地不到半亩。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民今年多种了十亩稻子。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十亩地约有六千多平方米。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在乡下买了一块两亩大的地。", "target_word": "亩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "畝", "label": "繁体"}, {"form": "亩产", "label": "复合词"}], "register": "中性", "sense_fingerprint": "土地面积单位，一亩约六百六十七平方米", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLU