INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亩", "is_correct": true, "explanation": "正确：亩（mǔ，第三声），土地面积单位。"}, {"text": "木", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是木头。"}, {"text": "目", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是眼睛。"}, {"text": "幕", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是帷幕。"}, {"text": "墓", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是坟墓。"}], "explanations": {"亩": "正确：亩（mǔ，第三声），土地面积单位。", "木": "mù（第四声）与 mǔ（第三声）声调不同，意思是木头。", "目": "mù（第四声）与 mǔ（第三声）声调不同，意思是眼睛。", "幕": "mù（第四声）与 mǔ（第三声）声调不同，意思是帷幕。", "墓": "mù（第四声）与 mǔ（第三声）声调不同，意思是坟墓。"}, "sentence_index": null, "correct_answer": "亩"}, "level_3": {"options": [{"text": "亩", "is_correct": true, "explanation": "正确：“亩”是土地面积单位，一亩约六百六十七平方米，符合句意。"}, {"text": "公里", "is_correct": false, "explanation": "语义：“公里”是长度单位，不能用来量面积。"}, {"text": "厘米", "is_correct": false, "explanation": "语义：“厘米”是长度单位，不能用来量面积。"}, {"text": "公顷", "is_correct": false, "explanation": "语义：一公顷约一万平方米，与“约六百六十七平方米”数值不符。"}], "explanations": {"亩": "正确：“亩”是土地面积单位，一亩约六百六十七平方米，符合句意。", "公里": "语义：“公里”是长度单位，不能用来量面积。", "厘米": "语义：“厘米”是长度单位，不能用来量面积。", "公顷": "语义：一公顷约一万平方米，与“约六百六十七平方米”数值不符。"}, "sentence_index": 0, "correct_answer": "亩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子大约有二十亩。", "explanation": "这里应该用〈平方米〉。“亩”只用来量土地，房间面积要用“平方米”。"}, {"text": "我们班有三亩学生。", "explanation": "“亩”只用来量土地，不能用来量人；这里应该用“名”。"}, {"text": "他买了一亩书。", "explanation": "“亩”只用来量土地，不用来量书；买书应该用“本”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95594, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亩", "is_correct": true, "explanation": "正确：亩（mǔ，第三声），土地面积单位。"}, {"text": "牧", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是放牧。"}, {"text": "慕", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是羡慕。"}, {"text": "募", "is_correct": false, "explanation": "mù（第四声）与 mǔ（第三声）声调不同，意思是募集。"}], "explanations": {"亩": "正确：亩（mǔ，第三声），土地面积单位。", "牧": "mù（第四声）与 mǔ（第三声）声调不同，意思是放牧。", "慕": "mù（第四声）与 mǔ（第三声）声调不同，意思是羡慕。", "募": "mù（第四声）与 mǔ（第三声）声调不同，意思是募集。"}, "sentence_index": null, "correct_answer": "亩"}, "level_3": {"options": [{"text": "亩", "is_correct": true, "explanation": "正确：“亩”是土地面积单位，“不到半亩”说菜地的大小，符合句意。"}, {"text": "米", "is_correct": false, "explanation": "语义：“米”是长度单位，不用来说菜地的面积。"}, {"text": "斤", "is_correct": false, "explanation": "搭配：“斤”是重量单位，不能用来量菜地。"}, {"text": "升", "is_correct": false, "explanation": "语义：“升”是容量单位，不能用来量面积。"}], "explanations": {"亩": "正确：“亩”是土地面积单位，“不到半亩”说菜地的大小，符合句意。", "米": "语义：“米”是长度单位，不用来说菜地的面积。", "斤": "搭配：“斤”是重量单位，不能用来量菜地。", "升": "语义：“升”是容量单位，不能用来量面积。"}, "sentence_index": 6, "correct_answer": "亩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家养了三亩鸡。", "explanation": "“亩”只用来量土地，不用来量动物；养鸡应该用“只”。"}, {"text": "车站离这里有五亩远。", "explanation": "“亩”是面积单位，不能表示距离；这里应该用“公里”。"}, {"text": "我们等了他两亩。", "explanation": "“亩”不能表示时间；这里应该用“个小时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爸爸在村里有两个亩地。", "corrected_sentence": "我爸爸在村里有两亩地。", "error_description": "量词误用：应为“两亩地”。“亩”本身是量词，前面不能再加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片菜地只有半块亩。", "corrected_sentence": "这片菜地只有半亩。", "error_description": "量词误用：应为“半亩”。“亩”前面不能再加“块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
