INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由中央政府直接管辖的城市，如北京。", "primary_collocate": null, "pronunciation": "zhí xiá shì", "ipa": "ʈʂɨ˧˥ ɕja˧˥ ʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "直辖市由中央政府直接管理。", "target_word": "直辖市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "四个直辖市都有自己的市长。", "target_word": "直辖市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "重庆是西部唯一的直辖市。", "target_word": "直辖市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直辖市不属于任何一个省。", "target_word": "直辖市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中央政府直接管辖直辖市。", "target_word": "直辖市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天津这个直辖市离海很近。", "target_word": "直辖市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直辖市的人口比一般城市多。", "target_word": "直辖市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上海是中国经济很发达的直辖市。", "target_word": "直辖市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央为直辖市派了新的市长。", "target_word": "直辖市", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一个直辖市当老师。", "target_word": "直辖市", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "由中央政府直接管辖的城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab055cd8-a036-49ec-a1fc-97881175b0a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直辖市", "is_correct": true, "explanation": "直辖市：由中央政府直接管理的城市，符合句意。"}, {"text": "村", "is_correct": false, "explanation": "语义：村由乡镇管理，不由中央政府直接管理。"}, {"text": "县", "is_correct": false, "explanation": "搭配：县通常说“归省管”或“属于某市”，不与“由中央政府直接管理”搭配。"}, {"text": "镇", "is_correct": false, "explanation": "语义：镇是乡级行政单位，不由中央政府直接管理。"}], "explanations": {"直辖市": "直辖市：由中央政府直接管理的城市，符合句意。", "村": "语义：村由乡镇管理，不由中央政府直接管理。", "县": "搭配：县通常说“归省管”或“属于某市”，不与“由中央政府直接管理”搭配。", "镇": "语义：镇是乡级行政单位，不由中央政府直接管理。"}, "sentence_index": 0, "correct_answer": "直辖市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个直辖市归省里管，省长负责它的事务。", "explanation": "这里应该用〈地级市〉。地级市归省管辖；直辖市直接由中央管辖，不归省管。"}, {"text": "拉萨是西藏的直辖市。", "explanation": "这里应该用〈首府〉。首府是自治区政府所在地，拉萨属于西藏自治区，不是直辖市。"}, {"text": "妈妈在厨房里做了一个直辖市。", "explanation": "这里应该用〈蛋糕〉。直辖市是城市，不能在厨房里做出来；做出来的食物要用蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直辖市", "is_correct": true, "explanation": "直辖市：人口多、城市规模大，“的人口比一般城市多”符合句意。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“人口”一般用于地区或城市，不用来说公园。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流没有人口，与“人口比一般城市多”不合。"}, {"text": "博物馆", "is_correct": false, "explanation": "搭配：博物馆不用“人口”来比较多少，与句意不搭配。"}], "explanations": {"直辖市": "直辖市：人口多、城市规模大，“的人口比一般城市多”符合句意。", "公园": "搭配：“人口”一般用于地区或城市，不用来说公园。", "河流": "语义：河流没有人口，与“人口比一般城市多”不合。", "博物馆": "搭配：博物馆不用“人口”来比较多少，与句意不搭配。"}, "sentence_index": 6, "correct_answer": "直辖市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "武汉是湖北的直辖市。", "explanation": "这里应该用〈省会〉。省会是省级政府所在城市，归省管辖，武汉不是直辖市。"}, {"text": "新疆是中国的直辖市，面积很大。", "explanation": "这里应该用〈自治区〉。新疆是自治区，属于省级行政区，不是由中央直接管辖的直辖市。"}, {"text": "西双版纳是一个直辖市，风景很美。", "explanation": "这里应该用〈自治州〉。自治州属于省或自治区管辖，直辖市不属于任何一个省。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条直辖市由中央直接管辖。", "corrected_sentence": "这座直辖市由中央直接管辖。", "error_description": "错误形式：“这条直辖市”；正确形式：“这座直辖市”。直辖市是城市，量词应用“座”，不能用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天津是北方一条很重要的直辖市。", "corrected_sentence": "天津是北方一座很重要的直辖市。", "error_description": "错误形式：“一条直辖市”；正确形式：“一座直辖市”。直辖市是城市，量词应用“座”，“条”只用于河流、道路等长条形的事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ce3d2f-4652-4a0f-9d71-e2c63ebe74fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
