INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95597, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在事情开始以前，先把要用的东西准备好。", "primary_collocate": null, "pronunciation": "chóu bèi", "ipa": "ʈʂʰoʊ˧˥ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我们正在筹备下周的生日会。", "target_word": "筹备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们筹备了一个月，运动会终于开始了。", "target_word": "筹备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在筹备新年晚会，大家都很忙。", "target_word": "筹备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先筹备好开会要用的东西。", "target_word": "筹备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在筹备明天的新产品发布会。", "target_word": "筹备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了筹备这次旅行，她买了地图和药。", "target_word": "筹备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校筹备毕业典礼的时候，我也去帮忙了。", "target_word": "筹备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们筹备着一场很大的音乐会。", "target_word": "筹备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的婚礼筹备得很好，客人都很满意。", "target_word": "筹备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们筹备了半年，书店今天终于开业了。", "target_word": "筹备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "筹备了", "label": "体标"}, {"form": "筹备着", "label": "体标"}, {"form": "筹备过", "label": "体标"}], "register": "中性", "sense_fingerprint": "筹备：活动开始前先备好要用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c6c3ec9-8bf6-4b2f-9d66-249534f22bfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95597, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "筹备", "is_correct": true, "explanation": "“筹备”指事先准备活动，与“下周的生日会”这一未来安排相符。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”针对过去，与“下周的生日会”的未来安排矛盾。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”针对已经过去的事，与“正在……下周”的时间不合。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”是不及物动词，不能带“生日会”作宾语。"}], "explanations": {"筹备": "“筹备”指事先准备活动，与“下周的生日会”这一未来安排相符。", "回忆": "语义：“回忆”针对过去，与“下周的生日会”的未来安排矛盾。", "怀念": "语义：“怀念”针对已经过去的事，与“正在……下周”的时间不合。", "散步": "搭配：“散步”是不及物动词，不能带“生日会”作宾语。"}, "sentence_index": 0, "correct_answer": "筹备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天都筹备早饭。", "explanation": "这里应该用〈准备〉。“筹备”指为活动或大事事先谋划准备，日常做早饭应说“准备”。"}, {"text": "他提前筹备了两个朋友，周末可以一起玩。", "explanation": "这里应该用〈结交〉。“筹备”指事先把要用的东西准备好，不能用于结交朋友。"}, {"text": "老师筹备了明天的值日。", "explanation": "这里应该用〈安排〉。“筹备”指事先准备活动，不能用来说安排值日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "筹备", "is_correct": true, "explanation": "“筹备”指事先准备，与“学校……毕业典礼的时候，我也去帮忙了”的情境相符。"}, {"text": "遗忘", "is_correct": false, "explanation": "语义：“遗忘”指忘记，与“去帮忙”的积极行动相矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“毕业典礼”作宾语。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”不能带“毕业典礼”作宾语，与“典礼”的搭配不合。"}], "explanations": {"筹备": "“筹备”指事先准备，与“学校……毕业典礼的时候，我也去帮忙了”的情境相符。", "遗忘": "语义：“遗忘”指忘记，与“去帮忙”的积极行动相矛盾。", "吃": "搭配：“吃”不能带“毕业典礼”作宾语。", "拆": "搭配：“拆”不能带“毕业典礼”作宾语，与“典礼”的搭配不合。"}, "sentence_index": 6, "correct_answer": "筹备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他筹备了这个问题三年。", "explanation": "这里应该用〈研究〉。“筹备”指事先准备，不用于深入探讨问题。"}, {"text": "他把这个词筹备成了一首歌，唱得很好听。", "explanation": "这里“筹备”被用来表示创作，但它只指事先把要用的东西准备好，不能把词变成歌。"}, {"text": "医生筹备了病人。", "explanation": "这里应该用〈治疗〉。“筹备”不能与“病人”搭配，不能用于治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚会我们还没筹备好了。", "corrected_sentence": "晚会我们还没筹备好。", "error_description": "错误：“没（有）”否定动作已经完成，后面不能再用“了”。“还没筹备好了”应去掉“了”，说成“还没筹备好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把运动会筹备的很好。", "corrected_sentence": "学校把运动会筹备得很好。", "error_description": "错误：补语标记应为“得”，不能用“的”。“筹备得很好”中“得”引出状态补语“很好”，“的”用于修饰名词，不能直接接在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc9d8dfb-a0ad-42f8-bf27-2f07f8189687') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
