INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95601, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事情到这里完了，不再继续。", "primary_collocate": null, "pronunciation": "zhōng jié", "ipa": "ʈʂʊŋ˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这场争论到这里终结了。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一封信终结了我们多年的误会。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的决定终结了这场讨论。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想终结这段没有结果的感情。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议终结了两国之间的争吵。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要尽快终结这场闹剧。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次失败终结了他的足球生涯。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大雨终结了这次比赛。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的话终结了他的梦想。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次谈判没有终结双方的争执。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "终结了", "label": "完成体"}, {"form": "终结过", "label": "经历体"}, {"form": "终结者", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "事情、争论、关系到此完了，不再继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95601, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终结", "is_correct": true, "explanation": "正确答案。“这场争论到这里终结了”表示争论到此为止。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物发育，争论不能生长，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”用于歌曲或戏剧，不能用于争论。"}, {"text": "怀孕", "is_correct": false, "explanation": "语义：“怀孕”只用于生物体，争论不能怀孕，句意不通。"}], "explanations": {"终结": "正确答案。“这场争论到这里终结了”表示争论到此为止。", "生长": "语义：“生长”指生物发育，争论不能生长，句意不通。", "唱": "搭配：“唱”用于歌曲或戏剧，不能用于争论。", "怀孕": "语义：“怀孕”只用于生物体，争论不能怀孕，句意不通。"}, "sentence_index": 0, "correct_answer": "终结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于终结了一碗面。", "explanation": "这里应该用〈吃完〉。终结指事情、关系到此为止，不用于饭菜这类具体事物。"}, {"text": "他终于终结了那句话。", "explanation": "这里应该用〈说完〉。终结指事情或关系到此为止，不用于话语，说完这句话要用说完。"}, {"text": "孩子们终结了玩具。", "explanation": "这里应该用〈收拾〉。终结不用于具体物品的整理，把玩具收好要用收拾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95601, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终结", "is_correct": true, "explanation": "正确答案。“那次失败终结了他的足球生涯”表示失败使生涯结束。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：足球生涯是经历，不能被挑选，句意不通。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：生涯不能被烘干，这个词与句意不合。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言文字，不能接“足球生涯”。"}], "explanations": {"终结": "正确答案。“那次失败终结了他的足球生涯”表示失败使生涯结束。", "挑选": "语义：足球生涯是经历，不能被挑选，句意不通。", "烘干": "语义：生涯不能被烘干，这个词与句意不合。", "翻译": "搭配：“翻译”的对象是语言文字，不能接“足球生涯”。"}, "sentence_index": 6, "correct_answer": "终结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于终结了电视。", "explanation": "这里应该用〈关掉〉。终结指事情、关系到此为止，不用于电器等具体物品的开关，要用关掉。"}, {"text": "妈妈终于终结了衣服。", "explanation": "这里应该用〈洗完〉。终结不用于衣物等具体事情的完成，洗完衣服要用洗完。"}, {"text": "工人终于终结了那座桥。", "explanation": "这里应该用〈修好〉。终结不用于建成的具体物体，修好桥要用修好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场争论今天终结着。", "corrected_sentence": "这场争论今天终结了。", "error_description": "错误形式“终结着”；“终结”表示事情已经完了，是完成性动作，不能用“着”表示持续。应改为“终结了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次会谈没有终结了两家公司的矛盾。", "corrected_sentence": "那次会谈没有终结两家公司的矛盾。", "error_description": "错误形式“没有终结了”；用“没有”否定已然的动作时，动词后不能再加“了”。应去掉“了”，写作“没有终结”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
