INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95602, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "结束；最后了结。", "primary_collocate": null, "pronunciation": "zhōng jié", "ipa": "ʈʂʊŋ˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "战争终结了，人们终于可以回家了。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段合作将在年底终结。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的比赛生涯在三十岁时终结。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈判终结后，两国签了协议。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场战争终结了一个时代。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定终结这项旧业务。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场车祸终结了他年轻的生命。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店的历史在今年终结了。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们终结了三年的合作关系。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年的友谊在那天终结了。", "target_word": "终结", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "终结了", "label": "完成体"}, {"form": "终结过", "label": "经历体"}, {"form": "终结者", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "战争、生命、合作等彻底结束、画上句号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终结", "is_correct": true, "explanation": "正确答案。“战争终结了”表示战争结束，人们可以回家。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：“诞生”指新事物出现，与“人们终于可以回家”的结局矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能用于战争，这个搭配不成立。"}, {"text": "复制", "is_correct": false, "explanation": "配价：“复制”需要带宾语，这里没有宾语，配价不符。"}], "explanations": {"终结": "正确答案。“战争终结了”表示战争结束，人们可以回家。", "诞生": "语义：“诞生”指新事物出现，与“人们终于可以回家”的结局矛盾。", "吃": "搭配：“吃”不能用于战争，这个搭配不成立。", "复制": "配价：“复制”需要带宾语，这里没有宾语，配价不符。"}, "sentence_index": 0, "correct_answer": "终结"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于终结了那本字典。", "explanation": "这里应该用〈查完〉。终结指事情或关系的结束，不用于工具书的查阅，查完字典要用查完。"}, {"text": "工人们终于终结了那堵墙。", "explanation": "这里应该用〈盖好〉。终结指事情或关系的结束，不用于已建成的具体物体，盖好墙要用盖好。"}, {"text": "他终于终结了那杯水。", "explanation": "这里应该用〈喝完〉。终结不用于饮品等具体事物，喝完水要用喝完。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终结", "is_correct": true, "explanation": "正确答案。“一场车祸终结了他年轻的生命”表示生命就此结束。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：“赠送”的对象是物品，不能把“生命”送出去，句意不通。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“认识”的对象是人或事物，“年轻的生命”不能被认识，句意不合。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言文字，不能接“生命”作宾语。"}], "explanations": {"终结": "正确答案。“一场车祸终结了他年轻的生命”表示生命就此结束。", "赠送": "语义：“赠送”的对象是物品，不能把“生命”送出去，句意不通。", "认识": "语义：“认识”的对象是人或事物，“年轻的生命”不能被认识，句意不合。", "翻译": "搭配：“翻译”的对象是语言文字，不能接“生命”作宾语。"}, "sentence_index": 6, "correct_answer": "终结"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计终于终结了账单。", "explanation": "这里应该用〈结算〉。终结指事情或关系的结束，账目的结清要用结算。"}, {"text": "我终于终结了那封信。", "explanation": "这里应该用〈写完〉。终结不用于书写等具体动作的完成，写完信要用写完。"}, {"text": "妈妈终于终结了那锅饭。", "explanation": "这里应该用〈煮好〉。终结不用于饭菜等具体事物，煮好饭要用煮好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场战争终结着，人们终于可以回家了。", "corrected_sentence": "这场战争终结了，人们终于可以回家了。", "error_description": "错误形式“终结着”；“终结”表示事情已经结束，是完成性动作，不能用“着”表示持续。应改为“终结了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家老店的历史很终结了。", "corrected_sentence": "这家老店的历史终于终结了。", "error_description": "错误形式“很终结了”；“很”是程度副词，不能修饰表示完成的动词“终结”。应改为“终于”，表示最后结束。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
