INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95605, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年纪很大的男人。", "primary_collocate": null, "pronunciation": "lǎo tóu", "ipa": "lau˨˩ tʰou˧˥", "syllable_count": 2, "sentences": [{"text": "那个老头已经九十岁了。", "target_word": "老头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个头发白了的老头走进了商店。", "target_word": "老头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个老头年纪很大，走路要用拐杖。", "target_word": "老头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在医院门口遇到一个很瘦的老头。", "target_word": "老头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个老头的背都弯了，还在地里工作。", "target_word": "老头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老头戴着一副旧眼镜，认真地看报纸。", "target_word": "老头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村口坐着几个头发都白了的老头。", "target_word": "老头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老头拿着一根长长的拐杖慢慢走。", "target_word": "老头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候，村里有个脾气很大的老头。", "target_word": "老头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个老头虽然很老，但是身体还不错。", "target_word": "老头", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "老头子", "label": "复合"}, {"form": "老頭", "label": "繁体"}], "register": "口语", "sense_fingerprint": "口语中指年纪很大、头发花白、行动迟缓的男人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7505f76d-2f05-4bdb-821e-935ffba3ab82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95605, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老头", "is_correct": true, "explanation": "正确答案。老头 lǎo tóu，指年纪很大的男人。"}, {"text": "老楼", "is_correct": false, "explanation": "lóu（第二声）与 tóu（第二声）声母不同，“老楼”意思是旧楼房。"}, {"text": "倒头", "is_correct": false, "explanation": "dǎo（第三声）与 lǎo（第三声）声母不同，“倒头”意思是头朝下倒下、躺下。"}, {"text": "好头", "is_correct": false, "explanation": "hǎo（第三声）与 lǎo（第三声）声母不同，“好头”意思是好的开端。"}], "explanations": {"老头": "正确答案。老头 lǎo tóu，指年纪很大的男人。", "老楼": "lóu（第二声）与 tóu（第二声）声母不同，“老楼”意思是旧楼房。", "倒头": "dǎo（第三声）与 lǎo（第三声）声母不同，“倒头”意思是头朝下倒下、躺下。", "好头": "hǎo（第三声）与 lǎo（第三声）声母不同，“好头”意思是好的开端。"}, "sentence_index": null, "correct_answer": "老头"}, "level_3": {"options": [{"text": "老头", "is_correct": true, "explanation": "正确答案。“老头”指年纪很大的男人，符合“已经九十岁了”。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩不可能已经九十岁，与句子的意思相矛盾。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生一般年纪很小，不可能已经九十岁。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“九十岁”的年龄一般只用于人，不说猫的年龄。"}], "explanations": {"老头": "正确答案。“老头”指年纪很大的男人，符合“已经九十岁了”。", "小孩": "语义：小孩不可能已经九十岁，与句子的意思相矛盾。", "学生": "语义：学生一般年纪很小，不可能已经九十岁。", "小猫": "搭配：“九十岁”的年龄一般只用于人，不说猫的年龄。"}, "sentence_index": 0, "correct_answer": "老头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在门口遇到一个刚满十八岁的老头。", "explanation": "这里应该用〈小伙子〉。老头指年纪很大的男人，十八岁的人不能称为老头。"}, {"text": "我姑姑是一位很和蔼的老头。", "explanation": "这里应该用〈老太太〉。老头只指男性，“姑姑”是女性。"}, {"text": "那只狗正在草地上跑，它是个老头。", "explanation": "这里应该用〈老狗〉。老头只指年纪很大的男人，不能用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95605, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "老头", "is_correct": true, "explanation": "正确答案。老头 lǎo tóu，指年纪很大的男人。"}, {"text": "老土", "is_correct": false, "explanation": "tǔ（第三声）与 tóu（第二声）仅韵母与声调有别，“老土”意思是过时、不时髦。"}, {"text": "草头", "is_correct": false, "explanation": "cǎo（第三声）与 lǎo（第三声）声母不同，“草头”意思是草的顶端。"}, {"text": "捞头", "is_correct": false, "explanation": "lāo（第一声）与 lǎo（第三声）声调不同，“捞头”意思是好处、油水。"}], "explanations": {"老头": "正确答案。老头 lǎo tóu，指年纪很大的男人。", "老土": "tǔ（第三声）与 tóu（第二声）仅韵母与声调有别，“老土”意思是过时、不时髦。", "草头": "cǎo（第三声）与 lǎo（第三声）声母不同，“草头”意思是草的顶端。", "捞头": "lāo（第一声）与 lǎo（第三声）声调不同，“捞头”意思是好处、油水。"}, "sentence_index": null, "correct_answer": "老头"}, "level_3": {"options": [{"text": "老头", "is_correct": true, "explanation": "正确答案。“老头”指年纪很大的男人，符合“头发都白了的老头”。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿的头发不可能白了，与句子的意思相矛盾。"}, {"text": "年轻人", "is_correct": false, "explanation": "语义：年轻人一般头发不白，与“头发都白了”的意思相矛盾。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：“头发”一般指人的头发，不能说小狗的头发白了。"}], "explanations": {"老头": "正确答案。“老头”指年纪很大的男人，符合“头发都白了的老头”。", "婴儿": "语义：婴儿的头发不可能白了，与句子的意思相矛盾。", "年轻人": "语义：年轻人一般头发不白，与“头发都白了”的意思相矛盾。", "小狗": "搭配：“头发”一般指人的头发，不能说小狗的头发白了。"}, "sentence_index": 6, "correct_answer": "老头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一个刚会走路的老头在院子里玩。", "explanation": "这里应该用〈小孩〉。老头指年纪很大的男人，刚会走路的幼儿不能称为老头。"}, {"text": "尊敬的王老头，请您上台发言。", "explanation": "这里应该用〈老先生〉。老头带有随意甚至轻视的色彩，不能用于正式、尊敬的称呼。"}, {"text": "这辆老头自行车还能骑。", "explanation": "这里应该用〈旧〉。老头是名词，指年纪很大的男人，不能用来修饰自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口坐着一个戴帽子老头。", "corrected_sentence": "门口坐着一个戴帽子的老头。", "error_description": "助词缺失：“戴帽子”修饰“老头”，中间必须加“的”，应为“戴帽子的老头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "广场边有一只老头在看报。", "corrected_sentence": "广场边有一个老头在看报。", "error_description": "量词错误：指人的“老头”应用量词“个”，不能用“只”，应为“一个老头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
