INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机关、企业等单位中从事一般事务的工作人员。", "primary_collocate": null, "pronunciation": "zhí yuán", "ipa": "ʈʂɻ̩˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他是政府机关的一名职员。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位职员负责处理单位的日常事务。", "target_word": "职员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "局里的职员每天要整理很多文件。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学毕业后，他进了一家企业当职员。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不是领导，只是普通职员。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个单位有三十多名职员。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理让职员把材料送到办公室。", "target_word": "职员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机关职员的工资每月按时发放。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "办公室的职员正在准备明天的会议。", "target_word": "职员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生在这个单位做了十年职员。", "target_word": "职员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "机关职员", "label": "复合"}, {"form": "企业职员", "label": "复合"}, {"form": "職員", "label": "繁体"}], "register": "正式", "sense_fingerprint": "机关或企业单位里处理一般事务的工作人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b229690-7d9a-4ce2-8b0a-679d95c7c30a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95608, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "职员", "is_correct": true, "explanation": "正确：听到的是“职员”（zhí yuán），指机关或企业里处理一般事务的人。"}, {"text": "支援", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是援助、支持。"}, {"text": "志愿", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是自愿，如志愿者。"}, {"text": "职院", "is_correct": false, "explanation": "yuàn（第四声）与 yuán（第二声）声调不同，意思是职业技术学院。"}], "explanations": {"职员": "正确：听到的是“职员”（zhí yuán），指机关或企业里处理一般事务的人。", "支援": "zhī（第一声）与 zhí（第二声）声调不同，意思是援助、支持。", "志愿": "zhì（第四声）与 zhí（第二声）、yuàn（第四声）与 yuán（第二声）声调都不同，意思是自愿，如志愿者。", "职院": "yuàn（第四声）与 yuán（第二声）声调不同，意思是职业技术学院。"}, "sentence_index": null, "correct_answer": "职员"}, "level_3": {"options": [{"text": "职员", "is_correct": true, "explanation": "正确：“职员”指机关或企业中做一般事务的人，符合“政府机关的”这一语境。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”指在学校读书的人，与政府机关的工作人员不符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指接受治疗的人，与政府机关的工作不符。"}, {"text": "旅客", "is_correct": false, "explanation": "搭配：“旅客”指乘车或乘船出行的人，不能说“政府机关的旅客”。"}], "explanations": {"职员": "正确：“职员”指机关或企业中做一般事务的人，符合“政府机关的”这一语境。", "学生": "语义：“学生”指在学校读书的人，与政府机关的工作人员不符。", "病人": "语义：“病人”指接受治疗的人，与政府机关的工作不符。", "旅客": "搭配：“旅客”指乘车或乘船出行的人，不能说“政府机关的旅客”。"}, "sentence_index": 0, "correct_answer": "职员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位职员在学校里教我们数学课。", "explanation": "这里应该用〈老师〉。给学生上课的是老师；“职员”指在单位从事一般事务的人。"}, {"text": "这位职员负责率领部队出征。", "explanation": "这里应该用〈军官〉。率领部队出征的是军官；职员只处理单位的一般事务。"}, {"text": "这台电脑是我们单位的职员。", "explanation": "这里应该用〈设备〉。电脑是设备，“职员”指人，不能指机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职员", "is_correct": true, "explanation": "正确：“职员”能把材料送到办公室，符合“经理让”的语境。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不能去办公室送材料，与“经理让”的语境不符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能把材料送到办公室，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“石头”不能作为“让”的执行者去完成送材料的动作。"}], "explanations": {"职员": "正确：“职员”能把材料送到办公室，符合“经理让”的语境。", "猫": "语义：猫不能去办公室送材料，与“经理让”的语境不符。", "小狗": "语义：小狗不能把材料送到办公室，句意不通。", "石头": "配价：“石头”不能作为“让”的执行者去完成送材料的动作。"}, "sentence_index": 6, "correct_answer": "职员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位职员每天在手术台上为病人开刀。", "explanation": "这里应该用〈医生〉。为病人开刀的是医生；职员只负责一般事务，不做这类工作。"}, {"text": "这张桌子是我们单位的职员。", "explanation": "这里应该用〈家具〉。桌子是家具，“职员”指人，不能用来指物品。"}, {"text": "这位职员把飞机开上了天空。", "explanation": "这里应该用〈飞行员〉。开飞机的是飞行员；“职员”指在单位做一般事务的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位职员们很认真。", "corrected_sentence": "这位职员很认真。", "error_description": "错误：“们”表示复数，不能与“这位”这种指单个人的词同用。正确说法是“这位职员很认真”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
