INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95609, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认真听别人说的话。", "primary_collocate": null, "pronunciation": "tīng qǔ", "ipa": "tʰiŋ˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "你要先听取他的解释，再做决定。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官认真听取了双方的话。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师坐在椅子上，认真听取学生说的话。", "target_word": "听取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生耐心听取病人的讲话。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈认真听取了孩子的解释。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听取别人说的话，是一种好习惯。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有听取我说的话，就走了。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在听取目击者说的话。", "target_word": "听取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先听取大家的发言，再说你的看法。", "target_word": "听取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她静静地坐着，听取朋友的诉说。", "target_word": "听取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听取了", "label": "体标"}, {"form": "听取过", "label": "体标"}, {"form": "聽取", "label": "繁体"}], "register": "正式", "sense_fingerprint": "认真听别人讲话、解释或发言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b229690-7d9a-4ce2-8b0a-679d95c7c30a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95609, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听取", "is_correct": true, "explanation": "听取：表示先认真听他的解释，与句意相符。"}, {"text": "编造", "is_correct": false, "explanation": "语义：“编造”是虚构，与“听他的解释再做决定”的认真态度相反，句子说不通。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”的对象是人或成就，不能接“他的解释”作宾语。"}, {"text": "测量", "is_correct": false, "explanation": "配价：“测量”需要可以量度的物理量作宾语，“解释”不是可以测量的对象。"}], "explanations": {"听取": "听取：表示先认真听他的解释，与句意相符。", "编造": "语义：“编造”是虚构，与“听他的解释再做决定”的认真态度相反，句子说不通。", "祝贺": "搭配：“祝贺”的对象是人或成就，不能接“他的解释”作宾语。", "测量": "配价：“测量”需要可以量度的物理量作宾语，“解释”不是可以测量的对象。"}, "sentence_index": 0, "correct_answer": "听取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在走廊里听取有人在哭。", "explanation": "这里应该用〈听见〉。“听取”用于认真听别人说的话，不能用来说听见有人哭这类声音。"}, {"text": "周末我去医院听取奶奶。", "explanation": "这里应该用〈看望〉。“听取”的对象是别人说的话，不能用来指人，不能说“听取奶奶”。"}, {"text": "她听取完了朋友的来信，很开心。", "explanation": "这里应该用〈读〉。“听取”要听别人说的话，来信是书面的，应该用“读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听取", "is_correct": true, "explanation": "听取：表示他没有听我说的话就走了，与句意相符。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”的对象是产品、方法，不能接“我说的话”作宾语。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”是卖东西，与“听我说的话”无关，句子说不通。"}, {"text": "煮", "is_correct": false, "explanation": "配价：“煮”需要食物作宾语，“我说的话”不能下锅煮。"}], "explanations": {"听取": "听取：表示他没有听我说的话就走了，与句意相符。", "发明": "搭配：“发明”的对象是产品、方法，不能接“我说的话”作宾语。", "出售": "语义：“出售”是卖东西，与“听我说的话”无关，句子说不通。", "煮": "配价：“煮”需要食物作宾语，“我说的话”不能下锅煮。"}, "sentence_index": 6, "correct_answer": "听取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈听取了这盘菜的味道。", "explanation": "这里应该用〈尝〉。“听取”指认真听别人说的话，味道要靠味觉品尝，应该用“尝”。"}, {"text": "我听取了这件衣服的颜色。", "explanation": "这里应该用〈看〉。“听取”指认真听别人说的话，颜色要用眼睛看，应该用“看”。"}, {"text": "他听取了一幅画的构图。", "explanation": "这里应该用〈欣赏〉。“听取”指认真听别人说的话，构图要用眼睛看，应该用“欣赏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师耐心听取了着学生的解释。", "corrected_sentence": "老师耐心听取了学生的解释。", "error_description": "错误：多出了“着”。“听取了”已经表示动作完成，“了”和“着”不能同时用在动词后面，句中只保留“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈仔细被听取了孩子的心里话。", "corrected_sentence": "妈妈仔细听取了孩子的心里话。", "error_description": "错误：多出了“被”。“听取”的主语“妈妈”是听的人，应用主动形式；“被听取”是被动结构，主语应是被听的内容，这里用在“妈妈”身上不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
