INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95611, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有大事发生时，临时多出的一张报纸。", "primary_collocate": null, "pronunciation": "hào wài", "ipa": "xɑʊ˥˩ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "报童在街上喊着：号外！号外！", "target_word": "号外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁口有人在发号外。", "target_word": "号外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一张号外，想看看出了什么大事。", "target_word": "号外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天发生了大地震，今天早上就有号外了。", "target_word": "号外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷还留着一张老号外。", "target_word": "号外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛赢了以后，报社马上出了号外。", "target_word": "号外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着号外跑回家，告诉大家好消息。", "target_word": "号外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都围着看那份号外。", "target_word": "号外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看过号外吗？", "target_word": "号外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上的号外一会儿就发完了。", "target_word": "号外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张号外", "label": "量词"}, {"form": "一份号外", "label": "量词"}], "register": "中性", "sense_fingerprint": "大事发生时临时多出的一张报纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7505f76d-2f05-4bdb-821e-935ffba3ab82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地图", "is_correct": false, "explanation": "语义：报童沿街叫卖的是新闻印刷品，“地图”不能这样被喊着卖。"}, {"text": "号外", "is_correct": true, "explanation": "号外是有大事发生时临时加印的报纸，报童在街上叫卖，正合语境。"}, {"text": "公告", "is_correct": false, "explanation": "语义：“公告”是张贴或发布的正式通知，不是报童沿街叫卖的报纸。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“喊着”的对象须是可以沿街叫卖的东西，“钥匙”说不通。"}], "explanations": {"地图": "语义：报童沿街叫卖的是新闻印刷品，“地图”不能这样被喊着卖。", "号外": "号外是有大事发生时临时加印的报纸，报童在街上叫卖，正合语境。", "公告": "语义：“公告”是张贴或发布的正式通知，不是报童沿街叫卖的报纸。", "钥匙": "搭配：“喊着”的对象须是可以沿街叫卖的东西，“钥匙”说不通。"}, "sentence_index": 0, "correct_answer": "号外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家每天早上都会收到一份号外。", "explanation": "这里应该用〈报纸〉。号外是为重大消息临时加印的，不会每天固定送到家里。"}, {"text": "店员在路口发号外，希望大家来买东西。", "explanation": "这里应该用〈传单〉。号外是报社为重大新闻临时加印的报纸，店家的宣传要用传单，不用号外。"}, {"text": "这本杂志每个月都出一期号外，内容很丰富。", "explanation": "这里应该用〈增刊〉。号外是为重大新闻临时加印的，不定期出版；每月定期出的专题册要用〈增刊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大山", "is_correct": false, "explanation": "体貌：大山体积庞大，拿不着也跑不动，形态与“拿着跑回家”不符。"}, {"text": "号外", "is_correct": true, "explanation": "号外是临时加印的报纸，拿在手里跑回家告诉大家，正合语境。"}, {"text": "太阳", "is_correct": false, "explanation": "体貌：太阳是天体，无法被拿着跑回家，形态上说不通。"}, {"text": "名字", "is_correct": false, "explanation": "配价：“拿着”要求具体可拿的物件作宾语，“名字”不能被拿。"}], "explanations": {"大山": "体貌：大山体积庞大，拿不着也跑不动，形态与“拿着跑回家”不符。", "号外": "号外是临时加印的报纸，拿在手里跑回家告诉大家，正合语境。", "太阳": "体貌：太阳是天体，无法被拿着跑回家，形态上说不通。", "名字": "配价：“拿着”要求具体可拿的物件作宾语，“名字”不能被拿。"}, "sentence_index": 6, "correct_answer": "号外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校发了号外，通知大家放假的时间。", "explanation": "这里应该用〈通知〉。号外是报社临时加印的报纸，学校的放假消息要用通知。"}, {"text": "我每个月都会收到一张号外。", "explanation": "这里应该用〈账单〉。号外是临时加印的报纸，不会定期寄来，每月收到的是账单。"}, {"text": "饭馆给我们一张号外，让我们点菜。", "explanation": "这里应该用〈菜单〉。号外是报纸，点菜用的是菜单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在地铁站买到了一只号外。", "corrected_sentence": "我在地铁站买到了一份号外。", "error_description": "量词错误：“号外”是纸张，应说“一份号外”或“一张号外”，不能用“一只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐在车站买了到一份号外。", "corrected_sentence": "姐姐在车站买到了一份号外。", "error_description": "语序错误：结果补语“到”应紧跟动词“买”，动词、补语与“了”的顺序应为“买到了”，不能写作“买了到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
