INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95613, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被别人说他做了错事。", "primary_collocate": null, "pronunciation": "bèi zhǐ", "ipa": "peɪ˥˩ ʈʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他被指偷了同学的钱。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个司机被指撞了人就跑。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理被指收了别人的钱。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王被指在考试时作弊。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师被指打过学生。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被指说了谎。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个年轻人被指拿走了别人的包。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居被指把垃圾倒在门口。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被指骗过很多老人。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那名学生被指在网上说同学的坏话。", "target_word": "被指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "某人被别人说做了错事或坏事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b229690-7d9a-4ce2-8b0a-679d95c7c30a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95613, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被指", "is_correct": true, "explanation": "被指：表示他被别人说偷了同学的钱，与句意相符。"}, {"text": "希望", "is_correct": false, "explanation": "语义：“希望”表示期望，不能接“偷了同学的钱”这种已经发生的错事。"}, {"text": "夸奖", "is_correct": false, "explanation": "配价：“夸奖”要求带受表扬的人作宾语，不能接“偷了同学的钱”这样的行为。"}, {"text": "打算", "is_correct": false, "explanation": "语义：“打算”表示计划，不能指已经完成的“偷了同学的钱”。"}], "explanations": {"被指": "被指：表示他被别人说偷了同学的钱，与句意相符。", "希望": "语义：“希望”表示期望，不能接“偷了同学的钱”这种已经发生的错事。", "夸奖": "配价：“夸奖”要求带受表扬的人作宾语，不能接“偷了同学的钱”这样的行为。", "打算": "语义：“打算”表示计划，不能指已经完成的“偷了同学的钱”。"}, "sentence_index": 0, "correct_answer": "被指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被指帮助了很多老人。", "explanation": "这里应该用〈被表扬〉。“被指”表示被别人说做了错事，帮助老人是好事，不能用“被指”，应该用“被表扬”。"}, {"text": "那个司机被指救了一个落水的孩子。", "explanation": "这里应该用〈被表彰〉。“被指”表示被别人说做了错事，救人是英勇的好事，应该用“被表彰”。"}, {"text": "经理被指主动给员工加了工资。", "explanation": "这里应该用〈被称赞〉。“被指”表示被别人说做了错事，主动给员工加工资是好事，应该用“被称赞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被指", "is_correct": true, "explanation": "被指：表示那个年轻人被别人说拿走了别人的包，与句意相符。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，与“拿走了别人的包”这种过错相矛盾。"}, {"text": "祝福", "is_correct": false, "explanation": "配价：“祝福”要求带人或事作宾语，不能接“拿走了别人的包”这样的行为。"}, {"text": "请求", "is_correct": false, "explanation": "搭配：“请求”一般接帮助、允许等内容，不能接“拿走了别人的包”。"}], "explanations": {"被指": "被指：表示那个年轻人被别人说拿走了别人的包，与句意相符。", "感谢": "语义：“感谢”表示感激，与“拿走了别人的包”这种过错相矛盾。", "祝福": "配价：“祝福”要求带人或事作宾语，不能接“拿走了别人的包”这样的行为。", "请求": "搭配：“请求”一般接帮助、允许等内容，不能接“拿走了别人的包”。"}, "sentence_index": 6, "correct_answer": "被指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那名学生被指扶起了摔倒的老人。", "explanation": "这里应该用〈被夸奖〉。“被指”表示被别人说做了错事，扶老人是好事，应该用“被夸奖”。"}, {"text": "那名学生被指很热心地帮助了同学。", "explanation": "这里应该用〈被称赞〉。“被指”表示被别人说做了错事，热心帮助同学是好事，应该用“被称赞”。"}, {"text": "那名学生被指把捡到的钱包还给了失主。", "explanation": "这里应该用〈被表扬〉。“被指”表示被别人说做了错事，还钱包是好事，应该用“被表扬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长被被指偷了班费。", "corrected_sentence": "班长被指偷了班费。", "error_description": "错误：多写了一个“被”，写成“被被指”。“被指”已经是被动结构，再加一个“被”是重复，应直接说“被指偷了班费”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个店员被指了骗过顾客。", "corrected_sentence": "那个店员被指骗过顾客。", "error_description": "错误：“被指”后面多了“了”，写成“被指了”。“被指”表示被别人说做了错事，是不带体标的被动结构，后面直接接所指的行为，不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e3432a7-86e2-4ef1-8295-0c09570caded') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
