INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95617, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "先说好要，过些天再来拿。", "primary_collocate": null, "pronunciation": "dìng", "ipa": "tiŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我在店里订了一个蛋糕。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我订了一本书，明天去拿。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他订了两斤新鲜的鱼，晚上来取。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在面包店订了一个生日蛋糕，周五来拿。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想订一双鞋，下周来拿。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板，我订的衣服好了吗？", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服我先订下，明天来拿。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我订一瓶牛奶，晚点来拿。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我订了五个包子，下午来拿。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她订的花明天才能取。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "在店里先说好要某样东西，之后再去取", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95617, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "订", "is_correct": true, "explanation": "正确：订（dìng），意思是先说好要、过后再取。"}, {"text": "丁", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）只差声调，意思是天干第四位、姓氏。"}, {"text": "顶", "is_correct": false, "explanation": "dǐng（第三声）与 dìng（第四声）声调不同，意思是顶。"}, {"text": "盯", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，意思是盯着。"}, {"text": "鼎", "is_correct": false, "explanation": "dǐng（第三声）与 dìng（第四声）只差声调，意思是古代的锅。"}], "explanations": {"订": "正确：订（dìng），意思是先说好要、过后再取。", "丁": "dīng（第一声）与 dìng（第四声）只差声调，意思是天干第四位、姓氏。", "顶": "dǐng（第三声）与 dìng（第四声）声调不同，意思是顶。", "盯": "dīng（第一声）与 dìng（第四声）声调不同，意思是盯着。", "鼎": "dǐng（第三声）与 dìng（第四声）只差声调，意思是古代的锅。"}, "sentence_index": null, "correct_answer": "订"}, "level_3": {"options": [{"text": "修", "is_correct": false, "explanation": "搭配：“修”多用于器物、机器，蛋糕不能修，“修了一个蛋糕”说不通。"}, {"text": "订", "is_correct": true, "explanation": "正确：订，表示先约定好要买，过后再来取。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是桌面、玻璃等表面，不能擦蛋糕。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与在店里预先要蛋糕的意思无关，句子不通。"}], "explanations": {"修": "搭配：“修”多用于器物、机器，蛋糕不能修，“修了一个蛋糕”说不通。", "订": "正确：订，表示先约定好要买，过后再来取。", "擦": "搭配：“擦”的对象是桌面、玻璃等表面，不能擦蛋糕。", "唱": "语义：“唱”指发声演唱，与在店里预先要蛋糕的意思无关，句子不通。"}, "sentence_index": 0, "correct_answer": "订"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在超市订了一瓶水，现在就喝。", "explanation": "这里应该用〈买〉。订是先约好、过后再取，“现在就喝”要用买。"}, {"text": "我在饭馆订了一碗面，马上就吃。", "explanation": "这里应该用〈点〉。订是先约好、过后再取，“马上就吃”要用点，当场吃的饭要说点。"}, {"text": "我订了一个好主意，大家都很满意。", "explanation": "这里应该用〈想〉。订是预先约定或拟定，“好主意”是想出来的，要说想出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95617, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "订", "is_correct": true, "explanation": "正确：订（dìng），意思是预先约定购买。"}, {"text": "命", "is_correct": false, "explanation": "mìng 与 dìng 只差声母（m 与 d），声调相同，意思是性命、命令。"}, {"text": "病", "is_correct": false, "explanation": "bìng 与 dìng 只差声母（b 与 d），声调相同，意思是疾病。"}, {"text": "令", "is_correct": false, "explanation": "lìng 与 dìng 只差声母（l 与 d），声调相同，意思是命令、使。"}, {"text": "叮", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）只差声调，意思是叮嘱。"}], "explanations": {"订": "正确：订（dìng），意思是预先约定购买。", "命": "mìng 与 dìng 只差声母（m 与 d），声调相同，意思是性命、命令。", "病": "bìng 与 dìng 只差声母（b 与 d），声调相同，意思是疾病。", "令": "lìng 与 dìng 只差声母（l 与 d），声调相同，意思是命令、使。", "叮": "dīng（第一声）与 dìng（第四声）只差声调，意思是叮嘱。"}, "sentence_index": null, "correct_answer": "订"}, "level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，衣服不能煮，与“先订下、明天来拿”不搭。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，衣服不能唱，句子不通。"}, {"text": "订", "is_correct": true, "explanation": "正确：订，表示先约定好，明天再来拿。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，“吃下”与衣服搭配不通。"}], "explanations": {"煮": "搭配：“煮”的对象是食物，衣服不能煮，与“先订下、明天来拿”不搭。", "唱": "语义：“唱”指发声演唱，衣服不能唱，句子不通。", "订": "正确：订，表示先约定好，明天再来拿。", "吃": "搭配：“吃”的对象是食物，“吃下”与衣服搭配不通。"}, "sentence_index": 6, "correct_answer": "订"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我订了牙医，下午去看病。", "explanation": "这里应该用〈预约〉。订用于票、房间、餐、货物等，约见医生要用预约。"}, {"text": "这个问题的结论我们已经订好了。", "explanation": "这里应该用〈得出〉。订指预先约定或购买，结论要通过研究得出。"}, {"text": "我早上去医院订了号，排队看病。", "explanation": "这里应该用〈挂〉。在医院取得就诊的号要说挂号，订用于预先买票、订房间、订餐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95617, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在店里了订一个蛋糕。", "corrected_sentence": "我昨天在店里订了一个蛋糕。", "error_description": "“了”应紧跟动词，说“订了一个蛋糕”，不能把“了”放在“订”前面（“了订”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95617, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天没订了这件衣服。", "corrected_sentence": "我昨天没订这件衣服。", "error_description": "“没”否定已经发生的动作时，句中不能再用“了”，应说“没订这件衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
