INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95618, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预先约定或购买；订购。", "primary_collocate": null, "pronunciation": "dìng", "ipa": "tiŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我想订一张去北京的火车票。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他订了一间安静的房间。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在网上订了酒店。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她订好了明天晚上的位子。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给每人订了一份午饭。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你订机票了吗？", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经订了三张电影票。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上订了一台新电脑。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末去饭店吃饭，要先订桌子。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期人多，最好早点订票。", "target_word": "订", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "预先约定或购买票、房间、座位等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ea03b26-13d4-42c6-b4dd-6754678089d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "订", "is_correct": true, "explanation": "正确：订（dìng），意思是预先约定购买或座位。"}, {"text": "镜", "is_correct": false, "explanation": "jìng 与 dìng 声母不同（j 与 d），声调相同，意思是镜子。"}, {"text": "病", "is_correct": false, "explanation": "bìng 与 dìng 声母不同（b 与 d），声调相同，意思是疾病。"}, {"text": "丁", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）只差声调，意思是天干第四位、姓氏。"}, {"text": "鼎", "is_correct": false, "explanation": "dǐng（第三声）与 dìng（第四声）只差声调，意思是古代的锅。"}, {"text": "顶", "is_correct": false, "explanation": "dǐng（第三声）与 dìng（第四声）声调不同，意思是顶。"}], "explanations": {"订": "正确：订（dìng），意思是预先约定购买或座位。", "镜": "jìng 与 dìng 声母不同（j 与 d），声调相同，意思是镜子。", "病": "bìng 与 dìng 声母不同（b 与 d），声调相同，意思是疾病。", "丁": "dīng（第一声）与 dìng（第四声）只差声调，意思是天干第四位、姓氏。", "鼎": "dǐng（第三声）与 dìng（第四声）只差声调，意思是古代的锅。", "顶": "dǐng（第三声）与 dìng（第四声）声调不同，意思是顶。"}, "sentence_index": null, "correct_answer": "订"}, "level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与买火车票的意思无关，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，火车票不能吃。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物或液体，不能煮车票。"}, {"text": "订", "is_correct": true, "explanation": "正确：订，表示预先约定购买去北京的火车票。"}], "explanations": {"唱": "语义：“唱”指发声演唱，与买火车票的意思无关，句子不通。", "吃": "搭配：“吃”的对象是食物，火车票不能吃。", "煮": "搭配：“煮”的对象是食物或液体，不能煮车票。", "订": "正确：订，表示预先约定购买去北京的火车票。"}, "sentence_index": 0, "correct_answer": "订"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在书店订了一本小说，现在就读。", "explanation": "这里应该用〈买〉。订是先约好、过后再取，“现在就读”要用买。"}, {"text": "妈妈在厨房订了一锅汤，今天就喝完了。", "explanation": "这里应该用〈煮〉。订是预先约定或购买，在自己家的厨房做汤要说煮。"}, {"text": "他已经订好了一份新工作，下周就去上班。", "explanation": "这里应该用〈找到〉。订是预先约定或购买，工作要通过求职得到，应说找到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95618, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "订", "is_correct": true, "explanation": "正确：订（dìng），意思是预先约定购买或座位。"}, {"text": "盯", "is_correct": false, "explanation": "dīng（第一声）与 dìng（第四声）声调不同，意思是盯着。"}, {"text": "病", "is_correct": false, "explanation": "bìng 与 dìng 只差声母（b 与 d），声调相同，意思是疾病。"}, {"text": "静", "is_correct": false, "explanation": "jìng 与 dìng 声母不同（j 与 d），声调相同，意思是安静。"}, {"text": "顶", "is_correct": false, "explanation": "dǐng（第三声）与 dìng（第四声）只差声调，意思是顶。"}], "explanations": {"订": "正确：订（dìng），意思是预先约定购买或座位。", "盯": "dīng（第一声）与 dìng（第四声）声调不同，意思是盯着。", "病": "bìng 与 dìng 只差声母（b 与 d），声调相同，意思是疾病。", "静": "jìng 与 dìng 声母不同（j 与 d），声调相同，意思是安静。", "顶": "dǐng（第三声）与 dìng（第四声）只差声调，意思是顶。"}, "sentence_index": null, "correct_answer": "订"}, "level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，电影票不能喝。"}, {"text": "炒", "is_correct": false, "explanation": "搭配：“炒”的对象是菜肴、食材，电影票不能炒。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用刀劈，与购买电影票的意思无关，句子不通。"}, {"text": "订", "is_correct": true, "explanation": "正确：订，表示预先买下了三张电影票。"}], "explanations": {"喝": "搭配：“喝”的对象是饮品，电影票不能喝。", "炒": "搭配：“炒”的对象是菜肴、食材，电影票不能炒。", "砍": "语义：“砍”指用刀劈，与购买电影票的意思无关，句子不通。", "订": "正确：订，表示预先买下了三张电影票。"}, "sentence_index": 6, "correct_answer": "订"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下午订了理发师，马上去剪头发。", "explanation": "这里应该用〈预约〉。订用于票、房间、餐、货物等，约定理发师的服务要用预约。"}, {"text": "我在学校订了一个好朋友，每天一起玩。", "explanation": "这里应该用〈交〉。订是预先约定或购买，结交朋友要说交。"}, {"text": "我早上去医院订了门诊号，排队看病。", "explanation": "这里应该用〈挂〉。在医院取得就诊的号要说挂号，订用于预先买票、订房间、订餐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我订了好了两张去上海的火车票。", "corrected_sentence": "我订好了两张去上海的火车票。", "error_description": "结果补语“好”应紧跟动词，应说“订好了两张”，不能说“订了好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经把电影票订。", "corrected_sentence": "我已经把电影票订了。", "error_description": "“把”字句中动词后面必须带其他成分，“订”后要加“了”，应说“把电影票订了”，不能只说“把电影票订”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '669d8bcb-9613-42c5-863e-321a5ff88abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
