INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95619, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把人或东西挡着，不让坏事碰到。", "primary_collocate": null, "pronunciation": "hù", "ipa": "xu˥˩", "syllable_count": 1, "sentences": [{"text": "他用手护着火，不让风吹灭。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，她用书包护着头。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把孩子护在怀里。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手护住了脸。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用外衣护着手机，怕雨淋湿。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球飞过来，他赶紧护住头。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，他用雨衣护着相机，怕水弄坏。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口风大，你用手护一下火。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把包护在身前，慢慢往前走。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子摔倒时，她用手护着他的头。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "护着", "label": "体标"}, {"form": "护了", "label": "体标"}, {"form": "护过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用身体或物品遮挡，使人或物不受伤害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95619, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "护", "is_correct": true, "explanation": "正确。护 hù 意思是用身体或物品挡住，使人或物不受伤害。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ（第三声）与 hù（第四声）声调不同，意思是老虎。"}, {"text": "富", "is_correct": false, "explanation": "fù 与 hù 声母不同（f 与 h），意思是富有。"}, {"text": "混", "is_correct": false, "explanation": "hùn 与 hù 韵母不同（-un 与 -u），意思是混合。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 hù（第四声）声调不同，意思是呼喊。"}], "explanations": {"护": "正确。护 hù 意思是用身体或物品挡住，使人或物不受伤害。", "虎": "hǔ（第三声）与 hù（第四声）声调不同，意思是老虎。", "富": "fù 与 hù 声母不同（f 与 h），意思是富有。", "混": "hùn 与 hù 韵母不同（-un 与 -u），意思是混合。", "呼": "hū（第一声）与 hù（第四声）声调不同，意思是呼喊。"}, "sentence_index": null, "correct_answer": "护"}, "level_3": {"options": [{"text": "护", "is_correct": true, "explanation": "正确。“用手护着火，不让风吹灭”表示用手挡住火，符合语境。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物，不能说穿着火。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”是用鼻子嗅，与“用手挡风”的动作不符。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”指击打，不能说拍着火。"}], "explanations": {"护": "正确。“用手护着火，不让风吹灭”表示用手挡住火，符合语境。", "穿": "搭配：“穿”的宾语是衣物，不能说穿着火。", "闻": "语义：“闻”是用鼻子嗅，与“用手挡风”的动作不符。", "拍": "搭配：“拍”指击打，不能说拍着火。"}, "sentence_index": 0, "correct_answer": "护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她打伞护住了阳光。", "explanation": "这里应该用〈遮〉。护用于保护人或物免受伤害，不说护住阳光。"}, {"text": "他用力护住了诱惑。", "explanation": "这里应该用〈抵挡〉。护是挡住会伤人的东西，不说护住诱惑。"}, {"text": "墙护住了风。", "explanation": "这里应该用〈挡〉。护用于保护人或物免受伤害，不说护住风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95619, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "护", "is_correct": true, "explanation": "正确。护 hù 意思是用身体或物品挡住，使人或物不受伤害。"}, {"text": "壶", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，意思是水壶。"}, {"text": "付", "is_correct": false, "explanation": "fù 与 hù 声母不同（f 与 h），意思是付钱。"}, {"text": "话", "is_correct": false, "explanation": "huà 与 hù 韵母不同（-ua 与 -u），意思是话语。"}, {"text": "胡", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，意思是胡同。"}], "explanations": {"护": "正确。护 hù 意思是用身体或物品挡住，使人或物不受伤害。", "壶": "hú（第二声）与 hù（第四声）声调不同，意思是水壶。", "付": "fù 与 hù 声母不同（f 与 h），意思是付钱。", "话": "huà 与 hù 韵母不同（-ua 与 -u），意思是话语。", "胡": "hú（第二声）与 hù（第四声）声调不同，意思是胡同。"}, "sentence_index": null, "correct_answer": "护"}, "level_3": {"options": [{"text": "护", "is_correct": true, "explanation": "正确。“用雨衣护着相机，怕水弄坏”表示用雨衣挡住，符合语境。"}, {"text": "晒", "is_correct": false, "explanation": "语义：下雨天用雨衣去晒相机，与“怕水弄坏”的语境矛盾。"}, {"text": "舔", "is_correct": false, "explanation": "语义：“舔”是用舌头，不能用雨衣去舔相机。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”的宾语是歌曲，不能带相机作宾语。"}], "explanations": {"护": "正确。“用雨衣护着相机，怕水弄坏”表示用雨衣挡住，符合语境。", "晒": "语义：下雨天用雨衣去晒相机，与“怕水弄坏”的语境矛盾。", "舔": "语义：“舔”是用舌头，不能用雨衣去舔相机。", "唱": "配价：“唱”的宾语是歌曲，不能带相机作宾语。"}, "sentence_index": 6, "correct_answer": "护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他护紧了鞋带。", "explanation": "这里应该用〈系〉。护指挡住坏事、不让东西受伤，不表示捆绑或系紧东西；系鞋带要说“系”。"}, {"text": "他护完了那本书。", "explanation": "这里应该用〈读〉。护指挡住坏事，不表示看或读书；读书要说“读”。"}, {"text": "他护开了窗户。", "explanation": "这里应该用〈打开〉。护指挡住坏事，不表示开启；开窗户要说“打开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95619, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他赶紧用手护了住头。", "corrected_sentence": "他赶紧用手护住了头。", "error_description": "“住”是结果补语，应紧跟动词，“了”放在句尾，应说“护住了头”，不说“护了住头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95619, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用手护了着火苗，直到风停了。", "corrected_sentence": "他用手护着火苗，直到风停了。", "error_description": "“护着”是持续体，“了”与“着”顺序颠倒，应说“护着”，不说“护了着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
