INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保护；看护。", "primary_collocate": null, "pronunciation": "hù", "ipa": "xu˥˩", "syllable_count": 1, "sentences": [{"text": "妈妈总是护着弟弟。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师护着学生，不让别人欺负他。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗妈妈拼命护着自己的孩子。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，她一直在床边护着发烧的孩子。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就护着妹妹。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别总护着他，他得自己学会。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都护着这只受伤的小鸟。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人护着孙女过马路。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥护着我，没让别人欺负我。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长一直护着那个犯了错的同学。", "target_word": "护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "护着", "label": "体标"}, {"form": "护了", "label": "体标"}, {"form": "护过", "label": "体标"}], "register": "中性", "sense_fingerprint": "保护、照看某人，偏向袒护和看护", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95620, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "护", "is_correct": true, "explanation": "正确。护 hù 意思是保护、看护。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ（第三声）与 hù（第四声）声调不同，意思是老虎。"}, {"text": "付", "is_correct": false, "explanation": "fù 与 hù 声母不同（f 与 h），意思是付钱。"}, {"text": "混", "is_correct": false, "explanation": "hùn 与 hù 韵母不同（-un 与 -u），意思是混合。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 hù（第四声）声调不同，意思是呼喊。"}], "explanations": {"护": "正确。护 hù 意思是保护、看护。", "虎": "hǔ（第三声）与 hù（第四声）声调不同，意思是老虎。", "付": "fù 与 hù 声母不同（f 与 h），意思是付钱。", "混": "hùn 与 hù 韵母不同（-un 与 -u），意思是混合。", "呼": "hū（第一声）与 hù（第四声）声调不同，意思是呼喊。"}, "sentence_index": null, "correct_answer": "护"}, "level_3": {"options": [{"text": "护", "is_correct": true, "explanation": "正确。“护着弟弟”表示照看、保护，符合语境。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”的宾语多为物品，不能说搬着弟弟。"}, {"text": "挂", "is_correct": false, "explanation": "语义：“挂”是悬挂，“挂着弟弟”不成立。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”是采下，不能用来表示对弟弟的照看。"}], "explanations": {"护": "正确。“护着弟弟”表示照看、保护，符合语境。", "搬": "搭配：“搬”的宾语多为物品，不能说搬着弟弟。", "挂": "语义：“挂”是悬挂，“挂着弟弟”不成立。", "摘": "语义：“摘”是采下，不能用来表示对弟弟的照看。"}, "sentence_index": 0, "correct_answer": "护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要护着知识产权。", "explanation": "这里应该用〈保护〉。护多用于照看人或小动物，不说护知识产权这类抽象事物。"}, {"text": "律师在法庭上为他护着。", "explanation": "这里应该用〈辩护〉。护指照看或保护，不表示在法庭上替人辩护。"}, {"text": "他努力护着公司的声誉。", "explanation": "这里应该用〈维护〉。护不用于声誉、秩序等抽象事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95620, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "护", "is_correct": true, "explanation": "正确。护 hù 意思是保护、看护。"}, {"text": "壶", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，意思是水壶。"}, {"text": "富", "is_correct": false, "explanation": "fù 与 hù 声母不同（f 与 h），意思是富有。"}, {"text": "话", "is_correct": false, "explanation": "huà 与 hù 韵母不同（-ua 与 -u），意思是话语。"}, {"text": "胡", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，意思是胡同。"}], "explanations": {"护": "正确。护 hù 意思是保护、看护。", "壶": "hú（第二声）与 hù（第四声）声调不同，意思是水壶。", "富": "fù 与 hù 声母不同（f 与 h），意思是富有。", "话": "huà 与 hù 韵母不同（-ua 与 -u），意思是话语。", "胡": "hú（第二声）与 hù（第四声）声调不同，意思是胡同。"}, "sentence_index": null, "correct_answer": "护"}, "level_3": {"options": [{"text": "护", "is_correct": true, "explanation": "正确。“大家都护着这只受伤的小鸟”表示照看、保护，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是进食，“吃着这只受伤的小鸟”不成立。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物，不能用于受伤的小鸟。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的宾语多为器物，不能说修这只小鸟。"}], "explanations": {"护": "正确。“大家都护着这只受伤的小鸟”表示照看、保护，符合语境。", "吃": "语义：“吃”是进食，“吃着这只受伤的小鸟”不成立。", "烤": "语义：“烤”是加热食物，不能用于受伤的小鸟。", "修": "搭配：“修”的宾语多为器物，不能说修这只小鸟。"}, "sentence_index": 6, "correct_answer": "护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个规定护着交通秩序。", "explanation": "这里应该用〈维护〉。护多用于照看、偏袒人或小动物，不用于秩序这类抽象事物。"}, {"text": "人民护着政府的政策。", "explanation": "这里应该用〈拥护〉。护不表示支持政府的政策。"}, {"text": "士兵护着领土。", "explanation": "这里应该用〈保卫〉。护多用于照看人或小动物，不用于领土的防卫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把孩子护很好。", "corrected_sentence": "她把孩子护得很好。", "error_description": "动词与程度补语之间要用“得”连接，应说“护得很好”，不说“护很好”，省略了“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐一直护过着我，从不让我受委屈。", "corrected_sentence": "姐姐一直护着我，从不让我受委屈。", "error_description": "“护着”是持续体，“过”与“着”不能同时出现，应说“护着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
