INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95623, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿了不是自己的公家的钱。", "primary_collocate": null, "pronunciation": "tān wū", "ipa": "tʰan˥ u˥", "syllable_count": 2, "sentences": [{"text": "会计贪污了单位的钱，后来大家都知道了。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿公家的钱买车，这就是贪污。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出纳偷偷贪污了学校的一万元。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李贪污过公家的钱，现在很后悔。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贪污单位的钱是不对的，一定要还回去。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把村里的钱贪污了，家人都很难过。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，谁也不能贪污公家的钱。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他贪污了公家的钱，赔了好几万元。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小官为什么要贪污国家的钱呢？", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂是国家的，他拿工厂的钱就是贪污。", "target_word": "贪污", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贪污了", "label": "体标"}, {"form": "贪污过", "label": "体标"}, {"form": "贪污犯", "label": "复合"}, {"form": "贪污罪", "label": "复合"}, {"form": "貪污", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "私自拿走单位或国家的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bf5a98-c423-433d-921e-c8cc89de37cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贪污", "is_correct": true, "explanation": "正确。“会计贪污了单位的钱”指私自拿走公家的钱，只有“贪污”符合句意。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”接的是申请或计划，不能直接接“单位的钱”。"}, {"text": "栽培", "is_correct": false, "explanation": "语义：“栽培”指培育植物或人才，与“单位的钱”搭配不通，句意荒谬。"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：“浇灌”指给植物或田地浇水，与“单位的钱”搭配不通，句意荒谬。"}], "explanations": {"贪污": "正确。“会计贪污了单位的钱”指私自拿走公家的钱，只有“贪污”符合句意。", "批准": "搭配：“批准”接的是申请或计划，不能直接接“单位的钱”。", "栽培": "语义：“栽培”指培育植物或人才，与“单位的钱”搭配不通，句意荒谬。", "浇灌": "语义：“浇灌”指给植物或田地浇水，与“单位的钱”搭配不通，句意荒谬。"}, "sentence_index": 0, "correct_answer": "贪污"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他贪污了朋友的房子。", "explanation": "这里应该用〈侵占〉。贪污针对公家的财物，朋友的房子属于个人，非法据为己有应说〈侵占〉。"}, {"text": "他靠做生意贪污了很多钱。", "explanation": "这里应该用〈赚〉。贪污指私自拿走公家的钱，不是靠劳动或生意得来，应该说〈赚〉。"}, {"text": "他贪污了邻居的钱。", "explanation": "这里应该用〈偷〉。贪污只用于公家的钱，邻居的钱属于个人，拿别人的东西应说〈偷〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贪污", "is_correct": true, "explanation": "正确。“谁也不能……公家的钱”是禁止私自拿走公款，只有“贪污”符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指把坏了的东西修好，与“公家的钱”不搭，句意不通。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”接的是器物表面，不能用来处置“钱”，句意不通。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化物品或场所，与“谁也不能……公家的钱”的禁令无关，句意荒谬。"}], "explanations": {"贪污": "正确。“谁也不能……公家的钱”是禁止私自拿走公款，只有“贪污”符合句意。", "修理": "语义：“修理”指把坏了的东西修好，与“公家的钱”不搭，句意不通。", "擦拭": "搭配：“擦拭”接的是器物表面，不能用来处置“钱”，句意不通。", "装饰": "语义：“装饰”指美化物品或场所，与“谁也不能……公家的钱”的禁令无关，句意荒谬。"}, "sentence_index": 6, "correct_answer": "贪污"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家私营公司的老板贪污了员工的工资。", "explanation": "这里应该用〈克扣〉。贪污针对公家的钱，私营公司老板扣下员工的工资应说〈克扣〉。"}, {"text": "他贪污了邻居的养老金。", "explanation": "这里应该用〈侵占〉。贪污针对公家的钱，邻居的养老金属于个人，非法据为己有应说〈侵占〉。"}, {"text": "他贪污了同事送的红包。", "explanation": "这里应该用〈收受〉。贪污针对公家的财物，同事送的红包是私人馈赠，接受应说〈收受〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把单位的钱贪污，后来被辞退了。", "corrected_sentence": "他把单位的钱贪污了，后来被辞退了。", "error_description": "错误：“把单位的钱贪污”。正确：“把单位的钱贪污了”。“把”字句中动词后面必须有“了”等成分，句子才完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从没贪污了公家的钱。", "corrected_sentence": "他从没贪污过公家的钱。", "error_description": "错误：“从没贪污了”。正确：“从没贪污过”。表示从未有过的经历要用“过”，不用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
