INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95627, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在路上，还没有到目的地。", "primary_collocate": null, "pronunciation": "tú zhōng", "ipa": "/tʰu˧˥ ʈʂʊŋ˥˥/", "syllable_count": 2, "sentences": [{"text": "我们在去机场的途中遇到了老朋友。", "target_word": "途中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在回家的途中买了一些水果。", "target_word": "途中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机还在途中，请你再等一会儿。", "target_word": "途中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在去学校的途中遇到了大雨。", "target_word": "途中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在出差途中给我打了电话。", "target_word": "途中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在去上班的途中看了一本书。", "target_word": "途中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行途中，我们一直听着音乐。", "target_word": "途中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递还在途中，明天才能到。", "target_word": "途中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在回国的途中，他一直在睡觉。", "target_word": "途中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在去公园的途中，他的鞋带松了。", "target_word": "途中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "在前往目的地的路上，尚未到达", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a21a23-df6a-4cf9-ac6b-c8fd9560ff2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95627, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "语义：房间是室内空间，不是行路的过程，“去机场的房间”说不通。"}, {"text": "途中", "is_correct": true, "explanation": "途中指在去机场的路上、尚未到达，与句意相符。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“去机场的”后接的应是地点或行程，不能修饰课本。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是供人休息赏花的地方，与去机场的行程无关。"}], "explanations": {"房间": "语义：房间是室内空间，不是行路的过程，“去机场的房间”说不通。", "途中": "途中指在去机场的路上、尚未到达，与句意相符。", "课本": "搭配：“去机场的”后接的应是地点或行程，不能修饰课本。", "花园": "语义：花园是供人休息赏花的地方，与去机场的行程无关。"}, "sentence_index": 0, "correct_answer": "途中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次途中考试，他考得很好。", "explanation": "这里应该用〈期中〉。途中指行路的过程，不能指学期中间的考试，说“期中考试”才对。"}, {"text": "公司今年途中的业绩很好。", "explanation": "这里应该用〈中期〉。途中指行路的过程，不能指年度中间阶段的业绩，说“中期业绩”才对。"}, {"text": "我家的途中有一家超市。", "explanation": "这里应该用〈路上〉。途中表示行进的过程，不表示地点；说某处有店铺，要用“路上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95627, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，“旅行厨房”与旅途的过程无关。"}, {"text": "途中", "is_correct": true, "explanation": "途中指旅行的过程之中，与句意相符。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“旅行”后接的是过程或时段，不能与“手机”组合表示时间或场所。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱用来储存食物，与旅行的过程无关。"}], "explanations": {"厨房": "语义：厨房是做饭的地方，“旅行厨房”与旅途的过程无关。", "途中": "途中指旅行的过程之中，与句意相符。", "手机": "搭配：“旅行”后接的是过程或时段，不能与“手机”组合表示时间或场所。", "冰箱": "语义：冰箱用来储存食物，与旅行的过程无关。"}, "sentence_index": 6, "correct_answer": "途中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他八点的途中到了学校。", "explanation": "这里应该用〈时候〉。途中指行路的过程，不能与具体的时间点连用，说“八点的时候”即可。"}, {"text": "我们终于到了途中。", "explanation": "这里应该用〈目的地〉。途中指还在路上、没有到达，不能说“到了途中”；到达的地方是目的地。"}, {"text": "他在出发前的途中收拾了行李。", "explanation": "这里应该用〈出门以前〉。途中指已经在路上的过程，出门以前还没有上路，不能说在途中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95627, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在去上海的途中的遇到了一位老同学。", "corrected_sentence": "我们在去上海的途中遇到了一位老同学。", "error_description": "多加了“的”：“途中”后直接接动词“遇到”，不能再加“的”。正确为「我们在去上海的途中遇到了一位老同学。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95627, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在下班途中里买了一束花。", "corrected_sentence": "他在下班途中买了一束花。", "error_description": "多加了“里”：“途中”已含“中”，后面不能再加方位词“里”。正确为「他在下班途中买了一束花。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95629, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "文明", "is_correct": true, "explanation": "正确答案：“文明”与“野蛮”是反义词，指有礼貌、讲道理，与“不讲道理、很凶”相对。"}, {"text": "勤劳", "is_correct": false, "explanation": "“勤劳”形容做事努力，与“野蛮”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指头脑灵活，与“野蛮”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”指排列有序，与“野蛮”没有反义关系。"}], "correct_answer": "文明", "explanations": {"文明": "正确答案：“文明”与“野蛮”是反义词，指有礼貌、讲道理，与“不讲道理、很凶”相对。", "勤劳": "“勤劳”形容做事努力，与“野蛮”没有反义关系。", "聪明": "“聪明”指头脑灵活，与“野蛮”没有反义关系。", "整齐": "“整齐”指排列有序，与“野蛮”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95629, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "文明", "is_correct": true, "explanation": "正确答案：“文明”与“野蛮”是反义词，指有礼貌、讲道理，与“不讲道理、很凶”相对。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音或不吵闹，与“野蛮”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌或事物美观，与“野蛮”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指人多、有声响，与“野蛮”没有反义关系。"}], "correct_answer": "文明", "explanations": {"文明": "正确答案：“文明”与“野蛮”是反义词，指有礼貌、讲道理，与“不讲道理、很凶”相对。", "安静": "“安静”指没有声音或不吵闹，与“野蛮”没有反义关系。", "漂亮": "“漂亮”形容外貌或事物美观，与“野蛮”没有反义关系。", "热闹": "“热闹”指人多、有声响，与“野蛮”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95629, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不讲道理，很凶，不文明。", "primary_collocate": null, "pronunciation": "yě mán", "ipa": "jɛ˨˩˦ man˧˥", "syllable_count": 2, "sentences": [{"text": "他说话很野蛮，一点道理也不讲。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要这么野蛮，好好说话。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人野蛮地推开了我。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对孩子太野蛮了。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野蛮的行为会让人害怕。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他野蛮地把门踢开了。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个司机很野蛮，总是大声骂人。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们野蛮得不讲一点道理。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的态度很野蛮，大家都怕他。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人说错了，也不能野蛮地打人。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "野蠻", "label": "繁体"}, {"form": "野蛮人", "label": "复合"}], "register": "中性", "sense_fingerprint": "人说话做事不讲道理、很凶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba864ba-6cc7-447b-a4fb-522b2fbca27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95629, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "野蛮", "is_correct": true, "explanation": "正确答案：“野蛮”指不讲道理、很凶，与“一点道理也不讲”一致。"}, {"text": "文明", "is_correct": false, "explanation": "语义：“文明”指有礼貌、讲道理，与后半句“一点道理也不讲”矛盾。"}, {"text": "讲理", "is_correct": false, "explanation": "语义：“讲理”与“一点道理也不讲”正好相反。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地，不用来形容人说话的方式。"}], "explanations": {"野蛮": "正确答案：“野蛮”指不讲道理、很凶，与“一点道理也不讲”一致。", "文明": "语义：“文明”指有礼貌、讲道理，与后半句“一点道理也不讲”矛盾。", "讲理": "语义：“讲理”与“一点道理也不讲”正好相反。", "柔软": "搭配：“柔软”形容质地，不用来形容人说话的方式。"}, "sentence_index": 0, "correct_answer": "野蛮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他野蛮地向我道了谢。", "explanation": "这里应该用〈礼貌〉。“野蛮”形容言行粗暴、不讲理，与道谢这种礼貌的举动相反。"}, {"text": "奶奶很野蛮地给孙子讲故事。", "explanation": "这里应该用〈温和〉。“野蛮”形容言行粗暴、不讲理，不能用来形容讲故事时的态度。"}, {"text": "她野蛮地给老人端了一杯热茶。", "explanation": "这里应该用〈热情〉。“野蛮”形容言行粗暴、不讲理，与给老人端茶的热情态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95629, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "野蛮", "is_correct": true, "explanation": "正确答案：“野蛮”指很凶、不讲道理，与“总是大声骂人”相符。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”与“总是大声骂人”矛盾。"}, {"text": "文雅", "is_correct": false, "explanation": "语义：“文雅”与“总是大声骂人”矛盾。"}, {"text": "轻柔", "is_correct": false, "explanation": "搭配：“轻柔”形容声音或动作，不用来形容司机的性格。"}], "explanations": {"野蛮": "正确答案：“野蛮”指很凶、不讲道理，与“总是大声骂人”相符。", "温柔": "语义：“温柔”与“总是大声骂人”矛盾。", "文雅": "语义：“文雅”与“总是大声骂人”矛盾。", "轻柔": "搭配：“轻柔”形容声音或动作，不用来形容司机的性格。"}, "sentence_index": 6, "correct_answer": "野蛮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师野蛮地表扬了每个学生。", "explanation": "这里应该用〈温和〉。“野蛮”形容言行粗暴、不讲理，不能修饰“表扬”这种礼貌的举动。"}, {"text": "他野蛮地向邻居问好。", "explanation": "这里应该用〈友好〉。“野蛮”形容粗暴、不讲理，不能修饰“问好”这种友善的举动。"}, {"text": "他野蛮地关心病人。", "explanation": "这里应该用〈体贴〉。“野蛮”形容粗暴的言行，与关心病人的态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他野蛮的推开了门。", "corrected_sentence": "他野蛮地推开了门。", "error_description": "“的”与“地”用错：“野蛮”修饰动词“推开”，作状语要用“地”，应说“野蛮地推开”，不能说“野蛮的推开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说很野蛮，大家都不敢说话。", "corrected_sentence": "他说得很野蛮，大家都不敢说话。", "error_description": "补语标记缺失：“说得很野蛮”中要用“得”引出补语，不能直接说“说很野蛮”，应加上“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95630, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "文明", "is_correct": true, "explanation": "正确答案：“文明”与“野蛮”是反义词，指礼貌、和善，与“凶狠粗暴、不文明”相对。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音或不吵闹，与“野蛮”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌或事物美观，与“野蛮”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指人多、有声响，与“野蛮”没有反义关系。"}], "correct_answer": "文明", "explanations": {"文明": "正确答案：“文明”与“野蛮”是反义词，指礼貌、和善，与“凶狠粗暴、不文明”相对。", "安静": "“安静”指没有声音或不吵闹，与“野蛮”没有反义关系。", "漂亮": "“漂亮”形容外貌或事物美观，与“野蛮”没有反义关系。", "热闹": "“热闹”指人多、有声响，与“野蛮”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
