INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95630, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不文明；凶狠粗暴。", "primary_collocate": null, "pronunciation": "yě mán", "ipa": "jɛ˨˩˦ man˧˥", "syllable_count": 2, "sentences": [{"text": "在古代，有些战争非常野蛮。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打动物是一种野蛮的做法。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们野蛮地砍倒了所有的树。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野蛮的人只会用拳头说话。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏太野蛮了，不适合孩子。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的刑罚很野蛮。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些士兵非常野蛮，烧毁了整个村子。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野蛮的行为不应该出现在学校里。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种野蛮的做法已经没有了。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用武力抢别人的东西是野蛮的行为。", "target_word": "野蛮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "野蠻", "label": "繁体"}, {"form": "野蛮人", "label": "复合"}], "register": "中性", "sense_fingerprint": "做法、行为、战争等不文明、凶狠粗暴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba864ba-6cc7-447b-a4fb-522b2fbca27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "野蛮", "is_correct": true, "explanation": "正确答案：“野蛮”指凶狠粗暴，符合战争残酷的描述。"}, {"text": "文明", "is_correct": false, "explanation": "语义：“文明”指有礼貌、讲道理，与“战争”的残酷相矛盾。"}, {"text": "温和", "is_correct": false, "explanation": "语义：“温和”与战争的残酷不相符。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：“精致”形容做工或物品，不用来形容战争。"}], "explanations": {"野蛮": "正确答案：“野蛮”指凶狠粗暴，符合战争残酷的描述。", "文明": "语义：“文明”指有礼貌、讲道理，与“战争”的残酷相矛盾。", "温和": "语义：“温和”与战争的残酷不相符。", "精致": "搭配：“精致”形容做工或物品，不用来形容战争。"}, "sentence_index": 0, "correct_answer": "野蛮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯茶的味道很野蛮。", "explanation": "这里应该用〈醇厚〉。“野蛮”形容粗暴、凶狠的做法，不能用来形容茶的味道。"}, {"text": "这件衣服的做工很野蛮。", "explanation": "这里应该用〈粗糙〉。“野蛮”形容行为凶狠、不文明，不能用来形容做工。"}, {"text": "老师野蛮地夸奖了每个学生。", "explanation": "这里应该用〈温和〉。“野蛮”形容凶狠、不文明的行为，不能修饰“夸奖”这种礼貌的举动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "野蛮", "is_correct": true, "explanation": "正确答案：“野蛮”指凶狠粗暴、不文明，符合“烧毁了整个村子”。"}, {"text": "友好", "is_correct": false, "explanation": "语义：“友好”与“烧毁了整个村子”矛盾。"}, {"text": "文雅", "is_correct": false, "explanation": "语义：“文雅”与烧毁村子的暴行矛盾。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不用来形容士兵。"}], "explanations": {"野蛮": "正确答案：“野蛮”指凶狠粗暴、不文明，符合“烧毁了整个村子”。", "友好": "语义：“友好”与“烧毁了整个村子”矛盾。", "文雅": "语义：“文雅”与烧毁村子的暴行矛盾。", "清脆": "搭配：“清脆”形容声音，不用来形容士兵。"}, "sentence_index": 6, "correct_answer": "野蛮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很野蛮地向老人让座。", "explanation": "这里应该用〈礼貌〉。“野蛮”形容凶狠、不文明的行为，不能用来形容让座这种礼貌的举动。"}, {"text": "妈妈野蛮地给我盖好被子。", "explanation": "这里应该用〈温柔〉。“野蛮”形容粗暴、凶狠的言行，与盖被子时的体贴动作不相容。"}, {"text": "他野蛮地向老师请教问题。", "explanation": "这里应该用〈虚心〉。“野蛮”形容凶狠、不文明的行为，不能用来形容向老师请教的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那伙人野蛮的抢走了村民的粮食。", "corrected_sentence": "那伙人野蛮地抢走了村民的粮食。", "error_description": "“的”与“地”用错：“野蛮”修饰动词“抢走”，作状语要用“地”，应说“野蛮地抢走”，不能说“野蛮的抢走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵们打很野蛮，村子都被毁了。", "corrected_sentence": "士兵们打得很野蛮，村子都被毁了。", "error_description": "补语标记缺失：“打得很野蛮”中要用“得”引出补语，不能直接说“打很野蛮”，应加上“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
