INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95631, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "张开嘴说话。", "primary_collocate": null, "pronunciation": "kāi kǒu", "ipa": "kʰaɪ˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他想说话，可是一开口就哭了。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子第一次开口叫妈妈，妈妈很高兴。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师还没开口，大家就安静了。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一开口，大家都笑了。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很害羞，不敢开口。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚要开口，他就走了。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人太累了，连开口都很难。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着我，却一直不开口。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别急，等他开口再说。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开口说了一句英语。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了口", "label": "体标（了）"}, {"form": "开过口", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "张开嘴说话（开口：说出话来）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03215d03-95c8-4cd4-8139-5091553db1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95631, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闭嘴", "is_correct": false, "explanation": "语义：“闭嘴”与“想说话”的意思相反，前后矛盾。"}, {"text": "开口", "is_correct": true, "explanation": "开口：张嘴说话，与“想说话”前后呼应，表示一张口就哭了。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”必须带宾语，单独用在“一……就哭了”里不成句。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“想说话”的语境不合，句子要说的是说话引起哭泣。"}], "explanations": {"闭嘴": "语义：“闭嘴”与“想说话”的意思相反，前后矛盾。", "开口": "开口：张嘴说话，与“想说话”前后呼应，表示一张口就哭了。", "送": "配价：“送”必须带宾语，单独用在“一……就哭了”里不成句。", "唱歌": "语义：“唱歌”与“想说话”的语境不合，句子要说的是说话引起哭泣。"}, "sentence_index": 0, "correct_answer": "开口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他开口咬了一口苹果。", "explanation": "这里应该用〈张口〉。“开口”指说出话来，咬东西要用“张口”。"}, {"text": "他开口向我借钱了，我不好意思拒绝。", "explanation": "这里的“开口”指提出请求（借钱），不是“张嘴说话”。"}, {"text": "这个袋子的开口太小，东西放不进去。", "explanation": "这里的“开口”是名词，指袋子的口儿，不是“张嘴说话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95631, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结婚", "is_correct": false, "explanation": "语义：病人太累时说“连结婚都很难”语境不合，句子要表达连基本动作都难。"}, {"text": "开口", "is_correct": true, "explanation": "开口：张嘴说话，与“病人太累”后“连……都很难”的语境相合。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是病的状态，不是可以去做的动作，“连……都很难”不通。"}, {"text": "长高", "is_correct": false, "explanation": "语义：“长高”与“太累”的语境不合，句意不通。"}], "explanations": {"结婚": "语义：病人太累时说“连结婚都很难”语境不合，句子要表达连基本动作都难。", "开口": "开口：张嘴说话，与“病人太累”后“连……都很难”的语境相合。", "发烧": "语义：“发烧”是病的状态，不是可以去做的动作，“连……都很难”不通。", "长高": "语义：“长高”与“太累”的语境不合，句意不通。"}, "sentence_index": 6, "correct_answer": "开口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子一开口笑，全家人都跟着笑了起来。", "explanation": "这里的“开口笑”指“笑起来”，是另一个意思，不是“张开嘴说话”。"}, {"text": "“啊”是开口音，发音时嘴张得比较大。", "explanation": "这里的“开口”是语音学术语，指发音时口腔张开度较大，不是“张嘴说话”。"}, {"text": "木板上的开口太小，装不进锁。", "explanation": "这里的“开口”是名词，指洞口、缺口，不是“张嘴说话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很久没开了口了。", "corrected_sentence": "他很久没开口了。", "error_description": "错误：“没”否定时，动词后不能再带动态助词“了”，所以“没开了口了”不通；正确：“没开口了”（只保留句末的“了”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一开口过，我就明白了他的意思。", "corrected_sentence": "他一开口，我就明白了他的意思。", "error_description": "错误：“一……就……”句表示紧接着发生的动作，“开口”后加“过”（经历体）不合此语境；应说“他一开口，我就明白了他的意思。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
