INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95632, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始说话；也指向人提出请求。", "primary_collocate": null, "pronunciation": "kāi kǒu", "ipa": "kʰaɪ˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我不好意思开口向他借钱。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题就开口问老师。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不开口求人。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你需要帮忙就开口，我一定来。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她开口要了一个很高的价钱。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上，经理先开口说了几句。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道怎么开口跟她说这件事。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱面子，有困难也不开口。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子刚上学，不敢开口回答问题。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开口就要我帮他写作业。", "target_word": "开口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开了口", "label": "体标（了）"}, {"form": "开过口", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "开始说话或向人提出请求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03215d03-95c8-4cd4-8139-5091553db1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.vali