INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“借钱”的请求意思相反，句子不通。"}, {"text": "开口", "is_correct": true, "explanation": "开口：开口提出请求，与“向他借钱”的语境相合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”不能作为借钱前的动作，句意不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要宾语，“不好意思送向他借钱”不成句。"}], "explanations": {"拒绝": "语义：“拒绝”与“借钱”的请求意思相反，句子不通。", "开口": "开口：开口提出请求，与“向他借钱”的语境相合。", "感谢": "语义：“感谢”不能作为借钱前的动作，句意不通。", "送": "配价：“送”需要宾语，“不好意思送向他借钱”不成句。"}, "sentence_index": 0, "correct_answer": "开口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子一开口笑，大家都跟着笑了。", "explanation": "这里的“开口笑”指“笑起来”，与“开口提出请求”无关。"}, {"text": "这件衣服的领子开口太大了。", "explanation": "这里的“开口”是名词，指衣服上的口子，与“开始说话或提出请求”无关。"}, {"text": "“啊”是开口音，发音时嘴张得比较大。", "explanation": "这里的“开口”是语音学术语，指发音时口腔张开度较大，与“张嘴说话”和“提出请求”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闭嘴", "is_correct": false, "explanation": "语义：“闭嘴”与“跟她说这件事”的意思矛盾，句子不通。"}, {"text": "拿", "is_correct": false, "explanation": "配价：“拿”要带宾语，“怎么拿跟她说”不成句。"}, {"text": "开口", "is_correct": true, "explanation": "开口：开口说话，与“跟她说这件事”相合。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”与“跟她说这件事”的语境不合，句子要说的是怎样讲出这件事。"}], "explanations": {"闭嘴": "语义：“闭嘴”与“跟她说这件事”的意思矛盾，句子不通。", "拿": "配价：“拿”要带宾语，“怎么拿跟她说”不成句。", "开口": "开口：开口说话，与“跟她说这件事”相合。", "笑": "语义：“笑”与“跟她说这件事”的语境不合，句子要说的是怎样讲出这件事。"}, "sentence_index": 6, "correct_answer": "开口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开口吃了一大口面条。", "explanation": "这里应该用〈张口〉。“开口”表示说话或提出请求，吃东西要用“张口”。"}, {"text": "这只碗的开口很宽，适合盛汤。", "explanation": "这里的“开口”指碗口，是名词，与“开口说话或提出请求”无关。"}, {"text": "铁皮上的开口太小，装不进管道。", "explanation": "这里的“开口”是名词，指孔洞、缺口，与“开始说话或提出请求”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很要面子，从不开了口求人。", "corrected_sentence": "他很要面子，从不开口求人。", "error_description": "错误：“从不”后的“开口”之间多了“了”；正确：“从不开口求人”。“从不”表示习惯性否定，不能与完成体“了”搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一开口过，我就答应了他。", "corrected_sentence": "他一开口，我就答应了他。", "error_description": "错误：“一……就……”句表示紧接着发生的动作，“开口”后加“过”（经历体）不合此语境；应说“他一开口，我就答应了他。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
