INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95633, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "穿在脚上走路的东西。", "primary_collocate": null, "pronunciation": "xié", "ipa": "ɕje˧˥", "syllable_count": 1, "sentences": [{"text": "我的鞋太小了，脚很疼。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进门请先换鞋。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着一双红色的鞋。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我的鞋都湿了。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋走路很舒服。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鞋放在门口了。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了一双新鞋。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩的鞋掉在路上了。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一双走路穿的鞋。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脚上的鞋脏了，要洗一洗。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "双", "label": "量词"}, {"form": "鞋子", "label": "复合"}, {"form": "皮鞋", "label": "复合"}], "register": "通用", "sense_fingerprint": "穿在脚上、用来走路的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95633, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鞋", "is_correct": true, "explanation": "xié 即“鞋”，指穿在脚上用来走路的东西。"}, {"text": "些", "is_correct": false, "explanation": "xiē（第一声）与 xié（第二声）声调不同，意思是些（表示少量）。"}, {"text": "写", "is_correct": false, "explanation": "xiě（第三声）与 xié（第二声）声调不同，意思是写（书写）。"}, {"text": "谢", "is_correct": false, "explanation": "xiè（第四声）与 xié（第二声）声调不同，意思是谢（感谢）。"}, {"text": "节", "is_correct": false, "explanation": "jié 与 xié 声母不同（j/x），意思是节（段落或节日）。"}], "explanations": {"鞋": "xié 即“鞋”，指穿在脚上用来走路的东西。", "些": "xiē（第一声）与 xié（第二声）声调不同，意思是些（表示少量）。", "写": "xiě（第三声）与 xié（第二声）声调不同，意思是写（书写）。", "谢": "xiè（第四声）与 xié（第二声）声调不同，意思是谢（感谢）。", "节": "jié 与 xié 声母不同（j/x），意思是节（段落或节日）。"}, "sentence_index": null, "correct_answer": "鞋"}, "level_3": {"options": [{"text": "鞋", "is_correct": true, "explanation": "与“太小了，脚很疼”搭配，指穿在脚上的东西。"}, {"text": "房间", "is_correct": false, "explanation": "语义：脚疼是因为鞋不合脚，房间的大小与脚疼无关。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包是背的，不能和“太小了，脚很疼”搭配。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机太小不会让脚疼，句意说不通。"}], "explanations": {"鞋": "与“太小了，脚很疼”搭配，指穿在脚上的东西。", "房间": "语义：脚疼是因为鞋不合脚，房间的大小与脚疼无关。", "书包": "搭配：书包是背的，不能和“太小了，脚很疼”搭配。", "手机": "语义：手机太小不会让脚疼，句意说不通。"}, "sentence_index": 0, "correct_answer": "鞋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在商店买了一条鞋。", "explanation": "这里应该用〈双〉。鞋成对，量词用“双”，“条”一般用于裤子、鱼等。"}, {"text": "她冬天戴着一双鞋出门。", "explanation": "鞋穿在脚上，不能说“戴”；戴的是〈帽子〉，量词用“顶”，不用“双”。"}, {"text": "下雨时她撑着一双鞋。", "explanation": "鞋不能用“撑”；撑的是〈雨伞〉，量词用“把”，不用“双”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95633, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鞋", "is_correct": true, "explanation": "“一双”是鞋的量词，与“新鞋”搭配。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：衣服的量词用“件”，不用“双”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：书的量词用“本”，不说“一双书”。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子是一顶，不是成对的东西，“一双帽子”说不通。"}], "explanations": {"鞋": "“一双”是鞋的量词，与“新鞋”搭配。", "衣服": "搭配：衣服的量词用“件”，不用“双”。", "书": "搭配：书的量词用“本”，不说“一双书”。", "帽子": "语义：帽子是一顶，不是成对的东西，“一双帽子”说不通。"}, "sentence_index": 6, "correct_answer": "鞋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天买了一件鞋。", "explanation": "这里应该用〈双〉。鞋成对，量词用“双”，“件”一般用于衣服。"}, {"text": "他戴着一双鞋走进教室。", "explanation": "鞋要说“穿”，不能说“戴”；戴的是〈眼镜〉，量词用“副”，不用“双”。"}, {"text": "天冷了，她围着一双鞋。", "explanation": "鞋不能用“围”；围的是〈围巾〉，量词用“条”，不用“双”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他穿了一条新鞋去上班。", "corrected_sentence": "他穿了一双新鞋去上班。", "error_description": "鞋成对，量词应用“双”，说“一双新鞋”；“条”一般用于裤子、鱼等，不能用来数鞋。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天买了一本布鞋。", "corrected_sentence": "妈妈昨天买了一双布鞋。", "error_description": "鞋成对，量词用“双”，说“一双布鞋”；“本”用于书，不能说“一本布鞋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
