INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95634, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "穿在脚上、保护脚的用品。", "primary_collocate": null, "pronunciation": "xié", "ipa": "ɕje˧˥", "syllable_count": 1, "sentences": [{"text": "这双鞋很结实，穿了三年。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天要穿厚鞋，脚才不冷。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在工地上必须穿保护脚的鞋。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天都擦鞋，把鞋擦得很亮。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋很软，走远路也不累。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的鞋有很多种。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我穿过这个牌子的鞋，质量不错。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪天最好穿防水的鞋。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的鞋坏了，要拿去修一修。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心路上的石头，别让鞋破了。", "target_word": "鞋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "双", "label": "量词"}, {"form": "鞋子", "label": "复合"}, {"form": "皮鞋", "label": "复合"}], "register": "通用", "sense_fingerprint": "穿在脚上、保护脚的用品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95634, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鞋", "is_correct": true, "explanation": "xié 即“鞋”，指穿在脚上、保护脚的用品。"}, {"text": "些", "is_correct": false, "explanation": "xiē（第一声）与 xié（第二声）声调不同，意思是些（表示少量）。"}, {"text": "写", "is_correct": false, "explanation": "xiě（第三声）与 xié（第二声）声调不同，意思是写（书写）。"}, {"text": "谢", "is_correct": false, "explanation": "xiè（第四声）与 xié（第二声）声调不同，意思是谢（感谢）。"}, {"text": "节", "is_correct": false, "explanation": "jié 与 xié 声母不同（j/x），意思是节（段落或节日）。"}], "explanations": {"鞋": "xié 即“鞋”，指穿在脚上、保护脚的用品。", "些": "xiē（第一声）与 xié（第二声）声调不同，意思是些（表示少量）。", "写": "xiě（第三声）与 xié（第二声）声调不同，意思是写（书写）。", "谢": "xiè（第四声）与 xié（第二声）声调不同，意思是谢（感谢）。", "节": "jié 与 xié 声母不同（j/x），意思是节（段落或节日）。"}, "sentence_index": null, "correct_answer": "鞋"}, "level_3": {"options": [{"text": "鞋", "is_correct": true, "explanation": "与“这双”和“穿了三年”搭配，指穿在脚上的用品。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“穿”要求鞋帽衣物做宾语，房子不能穿；“这双”也不用于房子。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包的量词用“个”，不用“双”，也不说“穿”。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是机器，不能“穿”，句子说的是鞋。"}], "explanations": {"鞋": "与“这双”和“穿了三年”搭配，指穿在脚上的用品。", "房子": "配价：“穿”要求鞋帽衣物做宾语，房子不能穿；“这双”也不用于房子。", "书包": "搭配：书包的量词用“个”，不用“双”，也不说“穿”。", "电视": "语义：电视是机器，不能“穿”，句子说的是鞋。"}, "sentence_index": 0, "correct_answer": "鞋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在商店买了一条鞋。", "explanation": "这里应该用〈双〉。鞋成对，量词用“双”，“条”多用于裤子、鱼等。"}, {"text": "工人在工地上必须戴鞋。", "explanation": "这里应该用〈安全帽〉。鞋穿在脚上，不能用“戴”，戴的是安全帽。"}, {"text": "冬天她围着一双鞋出门。", "explanation": "鞋不能用“围”；围的是〈围巾〉，量词用“条”，不用“双”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鞋", "is_correct": true, "explanation": "“穿过”的宾语是鞋，“质量不错”指鞋子的质量。"}, {"text": "电脑", "is_correct": false, "explanation": "配价：“穿”的宾语应是衣物鞋帽，电脑不能穿。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能穿，句意与“穿过”不符。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“穿过这个牌子的书”说不通，书不说穿。"}], "explanations": {"鞋": "“穿过”的宾语是鞋，“质量不错”指鞋子的质量。", "电脑": "配价：“穿”的宾语应是衣物鞋帽，电脑不能穿。", "冰箱": "语义：冰箱不能穿，句意与“穿过”不符。", "书": "搭配：“穿过这个牌子的书”说不通，书不说穿。"}, "sentence_index": 6, "correct_answer": "鞋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天买了一件鞋。", "explanation": "这里应该用〈双〉。鞋成对，量词用“双”，“件”一般用于衣服。"}, {"text": "下雨时她撑着一双鞋。", "explanation": "鞋不能用“撑”；撑的是〈雨伞〉，量词用“把”，不用“双”。"}, {"text": "他戴着一双鞋走进教室。", "explanation": "鞋要说“穿”，不能说“戴”；戴的是〈眼镜〉，量词用“副”，不用“双”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一个防滑的鞋。", "corrected_sentence": "我买了一双防滑的鞋。", "error_description": "鞋成对，量词应用“双”，说“一双防滑的鞋”；“一个鞋”是量词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的一个鞋不见了。", "corrected_sentence": "我的一只鞋不见了。", "error_description": "单只的鞋要用量词“只”，不能说“一个鞋”；这里是量词错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95635, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低于", "is_correct": true, "explanation": "正确。低于与高于意思相反，指比别的东西更低、更少。"}, {"text": "参加", "is_correct": false, "explanation": "与高于没有反义关系，参加指加入某项活动。"}, {"text": "保持", "is_correct": false, "explanation": "与高于没有反义关系，保持指维持原来的状态。"}, {"text": "喜欢", "is_correct": false, "explanation": "与高于没有反义关系，喜欢指对事物有好感。"}], "correct_answer": "低于", "explanations": {"低于": "正确。低于与高于意思相反，指比别的东西更低、更少。", "参加": "与高于没有反义关系，参加指加入某项活动。", "保持": "与高于没有反义关系，保持指维持原来的状态。", "喜欢": "与高于没有反义关系，喜欢指对事物有好感。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95635, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低于", "is_correct": true, "explanation": "正确。低于与高于意思相反，指比别的东西更低、更少。"}, {"text": "收到", "is_correct": false, "explanation": "与高于没有反义关系，收到指接到别人送来的东西。"}, {"text": "研究", "is_correct": false, "explanation": "与高于没有反义关系，研究指深入地探讨问题。"}, {"text": "离开", "is_correct": false, "explanation": "与高于没有反义关系，离开指从某个地方走开。"}], "correct_answer": "低于", "explanations": {"低于": "正确。低于与高于意思相反，指比别的东西更低、更少。", "收到": "与高于没有反义关系，收到指接到别人送来的东西。", "研究": "与高于没有反义关系，研究指深入地探讨问题。", "离开": "与高于没有反义关系，离开指从某个地方走开。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95635, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "比别的东西更高、更多。", "primary_collocate": null, "pronunciation": "gāo yú", "ipa": "kau˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "这座山高于周围所有的山。", "target_word": "高于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年的价格高于去年。", "target_word": "高于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这栋楼高于旁边的房子。", "target_word": "高于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的成绩高于全班平均分。", "target_word": "高于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的房价高于我们的预期。", "target_word": "高于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的高度高于云层。", "target_word": "高于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的价格高于别家，所以人不多。", "target_word": "高于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工资高于同事，大家都很羡慕。", "target_word": "高于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水已经高于桥面了。", "target_word": "高于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的温度高于北方的城市。", "target_word": "高于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "高於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "高度、价格、水平等比另一个东西更高或更多（后接比较对象）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7505f76d-2f05-4bdb-821e-935ffba3ab82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95635, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高于", "is_correct": true, "explanation": "正确。高于指比别的东西更高、更多。"}, {"text": "高炉", "is_correct": false, "explanation": "lú（第二声）与 yú（第二声）声母不同（l 与 y），高炉指炼铁的设备，意思不同。"}, {"text": "刀鱼", "is_correct": false, "explanation": "dāo 与 gāo 声母不同（d 与 g），刀鱼是一种鱼。"}, {"text": "干鱼", "is_correct": false, "explanation": "gān 与 gāo 韵母不同（-n 与 -o），干鱼指晒干的鱼。"}], "explanations": {"高于": "正确。高于指比别的东西更高、更多。", "高炉": "lú（第二声）与 yú（第二声）声母不同（l 与 y），高炉指炼铁的设备，意思不同。", "刀鱼": "dāo 与 gāo 声母不同（d 与 g），刀鱼是一种鱼。", "干鱼": "gān 与 gāo 韵母不同（-n 与 -o），干鱼指晒干的鱼。"}, "sentence_index": null, "correct_answer": "高于"}, "level_3": {"options": [{"text": "高于", "is_correct": true, "explanation": "正确。高于表示比周围所有的山更高。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”的主语须是有意识的人，“这座山”不能欢迎周围的山。"}, {"text": "同意", "is_correct": false, "explanation": "搭配：“同意”接的是意见或请求，不能接“山”这样的具体事物。"}, {"text": "属于", "is_correct": false, "explanation": "配价：“属于”的宾语是所属的整体，“这座山属于周围所有的山”颠倒了归属关系。"}], "explanations": {"高于": "正确。高于表示比周围所有的山更高。", "欢迎": "语义：“欢迎”的主语须是有意识的人，“这座山”不能欢迎周围的山。", "同意": "搭配：“同意”接的是意见或请求，不能接“山”这样的具体事物。", "属于": "配价：“属于”的宾语是所属的整体，“这座山属于周围所有的山”颠倒了归属关系。"}, "sentence_index": 0, "correct_answer": "高于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议高于三点结束。", "explanation": "这里应该用〈超过〉。高于比较的是数量或水平，比较时间点要说“会议超过三点才结束”。"}, {"text": "比赛中他高于对手，最后拿了冠军。", "explanation": "这里应该用〈超越〉。高于用于数量、水平的比较，比赛中赶过并胜过对手要说“超越对手”。"}, {"text": "他的脚步高于大家。", "explanation": "这里应该用〈快〉。高于比较的是数量或水平，说走路的快慢要用“快”或“走得比大家快”，不能用“高于”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95635, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高于", "is_correct": true, "explanation": "正确。高于指比别的东西更高、更多。"}, {"text": "高胡", "is_correct": false, "explanation": "hú 与 yú 声母不同（h 与 y），高胡是一种乐器。"}, {"text": "烧鱼", "is_correct": false, "explanation": "shāo 与 gāo 声母不同（sh 与 g），烧鱼是一道菜。"}, {"text": "捞鱼", "is_correct": false, "explanation": "lāo 与 gāo 声母不同（l 与 g），捞鱼指从水里把鱼捞出来。"}], "explanations": {"高于": "正确。高于指比别的东西更高、更多。", "高胡": "hú 与 yú 声母不同（h 与 y），高胡是一种乐器。", "烧鱼": "shāo 与 gāo 声母不同（sh 与 g），烧鱼是一道菜。", "捞鱼": "lāo 与 gāo 声母不同（l 与 g），捞鱼指从水里把鱼捞出来。"}, "sentence_index": null, "correct_answer": "高于"}, "level_3": {"options": [{"text": "高于", "is_correct": true, "explanation": "正确。高于表示价格比别家更高。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“认识”的主语须是人，“价格”不能认识“别家”。"}, {"text": "陪伴", "is_correct": false, "explanation": "搭配：“陪伴”的对象须是人或动物，“价格”不能陪伴“别家”。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”需要有意志的主语，价格不能拒绝别家。"}], "explanations": {"高于": "正确。高于表示价格比别家更高。", "认识": "语义：“认识”的主语须是人，“价格”不能认识“别家”。", "陪伴": "搭配：“陪伴”的对象须是人或动物，“价格”不能陪伴“别家”。", "拒绝": "语义：“拒绝”需要有意志的主语，价格不能拒绝别家。"}, "sentence_index": 6, "correct_answer": "高于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司高于北京。", "explanation": "这里应该用〈位于〉。高于表示高低、多少的比较，不能表示位置在某地，要说“这家公司位于北京”。"}, {"text": "他终于高于了前面的人。", "explanation": "这里应该用〈赶上〉。高于比较的是量或水平，追上前面的人要说“他终于赶上了前面的人”。"}, {"text": "哥哥高于我三岁。", "explanation": "这里应该用〈大〉。高于比较高度、数量或水平，说年龄差别要说“哥哥比我大三岁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95635, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的收入比高于去年，多了两万元。", "corrected_sentence": "今年的收入高于去年，多了两万元。", "error_description": "错误：“比”与“高于”重复表示比较，多加了“比”，“比高于去年，多了两万元”是错误形式。正确形式是去掉“比”，写作“高于去年，多了两万元”，因为“高于”本身已经表示比较。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95635, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的物价很高于北方的城市。", "corrected_sentence": "这个城市的物价远高于北方的城市。", "error_description": "错误：“很”是程度副词，不能修饰动词“高于”。应改用“远”，写作“远高于”，表示差距大。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
