INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95637, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95637, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人拜的、心很好很有智慧的神。", "primary_collocate": null, "pronunciation": "fó", "ipa": "fwo˧˥", "syllable_count": 1, "sentences": [{"text": "奶奶每个月都去庙里拜佛。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人相信佛会保佑他们。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天拜佛，对人特别好。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们说佛很有智慧，心也很好。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不信佛，也不拜神。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说佛会看着每个人，所以不做坏事。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都向佛求平安。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "佛说，做好事会有好结果。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈信佛，常常给穷人送吃的。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，很多人到庙里给佛上香。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一尊佛", "label": "量词"}], "register": "中性", "sense_fingerprint": "人们敬拜的、慈善而有智慧的神", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7505f76d-2f05-4bdb-821e-935ffba3ab82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95637, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：拜的对象须是神明或尊长，“汽车”不能被拜。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“拜”搭配神明、祖先、老师等，不能搭配食物。"}, {"text": "佛", "is_correct": true, "explanation": "佛是人们拜的神，庙里拜的正是佛，正合语境。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“拜”要求有具体形象的对象，“空气”没有形象，不能作宾语。"}], "explanations": {"汽车": "语义：拜的对象须是神明或尊长，“汽车”不能被拜。", "饼干": "搭配：“拜”搭配神明、祖先、老师等，不能搭配食物。", "佛": "佛是人们拜的神，庙里拜的正是佛，正合语境。", "空气": "配价：“拜”要求有具体形象的对象，“空气”没有形象，不能作宾语。"}, "sentence_index": 0, "correct_answer": "佛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人们说佛会半夜出来吓人。", "explanation": "这里应该用〈鬼〉。佛是慈善的神，不会半夜出来吓人，“吓人”是鬼的特征。"}, {"text": "人们说佛很残忍，专门害人。", "explanation": "这里应该用〈恶魔〉。佛慈悲为怀，不会残忍害人，“残忍害人”应说〈恶魔〉。"}, {"text": "清明节的时候，大家都去给佛扫墓。", "explanation": "这里应该用〈祖先〉。佛是很多人拜的神，不是家族的先人；清明扫墓祭拜的是〈祖先〉，不是佛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能接受祈求，“向饼干求平安”说不通。"}, {"text": "佛", "is_correct": true, "explanation": "佛是人们向其祈求平安的神，正合语境。"}, {"text": "冰山", "is_correct": false, "explanation": "语义：冰山是自然景物，不是人们祈求平安的对象。"}, {"text": "论文", "is_correct": false, "explanation": "语义：论文是文章，不能接受祈求，“向论文求平安”说不通。"}], "explanations": {"饼干": "语义：饼干是食品，不能接受祈求，“向饼干求平安”说不通。", "佛": "佛是人们向其祈求平安的神，正合语境。", "冰山": "语义：冰山是自然景物，不是人们祈求平安的对象。", "论文": "语义：论文是文章，不能接受祈求，“向论文求平安”说不通。"}, "sentence_index": 6, "correct_answer": "佛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孔子是佛，他的话大家都要听。", "explanation": "这里应该用〈圣人〉。佛是很多人拜的神，孔子是儒家的圣人，不能称为佛。"}, {"text": "基督徒每周都去教堂向佛祈祷。", "explanation": "这里应该用〈上帝〉。基督徒的祈祷对象是上帝，佛属于佛教，不在这种场合使用。"}, {"text": "村口的庙里有一尊佛很凶，专门惩罚坏人。", "explanation": "这里应该用〈凶神〉。佛慈悲为怀，不惩罚人，凶狠惩罚人的神要用〈凶神〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寺院里有一只佛，香火很旺。", "corrected_sentence": "寺院里有一尊佛，香火很旺。", "error_description": "量词错误：佛像用“尊”计量，应说“一尊佛”，不能说“一只佛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天早上都佛拜。", "corrected_sentence": "他每天早上都拜佛。", "error_description": "语序错误：应说“拜佛”，不能说“佛拜”，动宾结构的词序不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
