INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "佛教中指修行圆满、觉悟了的人，也指佛像。", "primary_collocate": null, "pronunciation": "fó", "ipa": "fwo˧˥", "syllable_count": 1, "sentences": [{"text": "庙里有一尊很高的佛。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说他修行多年，后来成了佛。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这尊佛是用木头做的。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的佛已经有一千年了。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上给佛擦灰。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们说，只要一心向善，人人都能成佛。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国游客都想和那尊佛合影。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在家里放了一尊小佛。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "佛坐在高高的台上，脸上带着笑。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老和尚说，真正觉悟的人才是佛。", "target_word": "佛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一尊佛", "label": "量词"}, {"form": "佛教", "label": "复合"}, {"form": "佛像", "label": "复合"}], "register": "中性", "sense_fingerprint": "佛教中觉悟了的人，也指佛像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7505f76d-2f05-4bdb-821e-935ffba3ab82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "柱子", "is_correct": false, "explanation": "搭配：“柱子”用“根”计量，不说“一尊”，与“尊”的搭配不成立。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：庙里不会供着一尊汽车，与“庙里”的语境不符。"}, {"text": "佛", "is_correct": true, "explanation": "这里指佛像，庙里供奉的高大佛像用“尊”计量，正合语境。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球不是庙里供奉的对象，这里的语境不容许它出现。"}], "explanations": {"柱子": "搭配：“柱子”用“根”计量，不说“一尊”，与“尊”的搭配不成立。", "汽车": "语义：庙里不会供着一尊汽车，与“庙里”的语境不符。", "佛": "这里指佛像，庙里供奉的高大佛像用“尊”计量，正合语境。", "篮球": "语义：篮球不是庙里供奉的对象，这里的语境不容许它出现。"}, "sentence_index": 0, "correct_answer": "佛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孔子是佛，他的思想影响了后世。", "explanation": "这里应该用〈圣人〉。佛指佛教中觉悟圆满的人，孔子是儒家圣人，不能称佛。"}, {"text": "这位佛还没有修行圆满，还要继续修行。", "explanation": "这里应该用〈菩萨〉。佛指修行圆满、觉悟了的人；修行尚未圆满的应称〈菩萨〉，不能说佛。"}, {"text": "这位佛明天要参加高考。", "explanation": "这里应该用〈考生〉。佛指修行圆满、觉悟了的人，不参加考试；参加高考的应说〈考生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不是可供合影的神像，“和那尊饼干合影”说不通。"}, {"text": "小草", "is_correct": false, "explanation": "语义：小草是植物，不是有形象的佛像，“和那尊小草合影”说不通。"}, {"text": "佛", "is_correct": true, "explanation": "那尊佛指庙里的佛像，游客与它合影，正合语境。"}, {"text": "时间", "is_correct": false, "explanation": "配价：“合影”需要具体可见的对象，“时间”不能作合影的对象。"}], "explanations": {"饼干": "语义：饼干是食品，不是可供合影的神像，“和那尊饼干合影”说不通。", "小草": "语义：小草是植物，不是有形象的佛像，“和那尊小草合影”说不通。", "佛": "那尊佛指庙里的佛像，游客与它合影，正合语境。", "时间": "配价：“合影”需要具体可见的对象，“时间”不能作合影的对象。"}, "sentence_index": 6, "correct_answer": "佛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教义说，佛创造了人类和世界。", "explanation": "这里应该用〈上帝〉。佛教没有创造世界的神，创世的应是〈上帝〉。"}, {"text": "这位佛是我们村的村长，负责收税。", "explanation": "这里应该用〈村长〉。佛指修行圆满、觉悟了的人，不担任村里的行政职务；管村务、收税的应说〈村长〉。"}, {"text": "这位佛每天下地干活，累得满头大汗。", "explanation": "这里应该用〈农民〉。佛指修行圆满、觉悟了的人，不下地干活；下地务农的应说〈农民〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在寺里见到了一只佛。", "corrected_sentence": "我在寺里见到了一尊佛。", "error_description": "量词错误：佛像用“尊”计量，应说“一尊佛”，不能说“一只佛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寺庙里放着一条佛。", "corrected_sentence": "寺庙里放着一尊佛。", "error_description": "量词错误：佛像用“尊”计量，应说“一尊佛”，不能说“一条佛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下期", "is_correct": true, "explanation": "正确：“下期”与“上期”是反义词，指这一期之后的一期。"}, {"text": "冠军", "is_correct": false, "explanation": "冠军是名次，与“上期”没有反义关系。"}, {"text": "节目", "is_correct": false, "explanation": "节目指表演的内容，与“上期”没有反义关系。"}, {"text": "书架", "is_correct": false, "explanation": "书架是家具，与“上期”没有反义关系。"}], "correct_answer": "下期", "explanations": {"下期": "正确：“下期”与“上期”是反义词，指这一期之后的一期。", "冠军": "冠军是名次，与“上期”没有反义关系。", "节目": "节目指表演的内容，与“上期”没有反义关系。", "书架": "书架是家具，与“上期”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下期", "is_correct": true, "explanation": "正确：“下期”与“上期”是反义词，指这一期之后的一期。"}, {"text": "课本", "is_correct": false, "explanation": "课本是教材，与“上期”没有反义关系。"}, {"text": "旅馆", "is_correct": false, "explanation": "旅馆是住宿场所，与“上期”没有反义关系。"}, {"text": "黑板", "is_correct": false, "explanation": "黑板是教学用具，与“上期”没有反义关系。"}], "correct_answer": "下期", "explanations": {"下期": "正确：“下期”与“上期”是反义词，指这一期之后的一期。", "课本": "课本是教材，与“上期”没有反义关系。", "旅馆": "旅馆是住宿场所，与“上期”没有反义关系。", "黑板": "黑板是教学用具，与“上期”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这一次的前面一次。", "primary_collocate": null, "pronunciation": "shàng qī", "ipa": "ʂɑŋ˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "上期的节目我没看，这期很好看。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本杂志比上期厚了很多。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上期杂志讲了第五课的语法，这期讲第六课。", "target_word": "上期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上期的杂志他还没看完，这期又出版了。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我还留着上期的画报。", "target_word": "上期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上期没卖完的杂志，这期打五折。", "target_word": "上期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看上期的故事，再看这期的结局。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把上期的杂志借给朋友了。", "target_word": "上期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上期的问题，这期老师来回答。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这期的封面和上期完全不一样。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "杂志、节目、课程等这一期之前的那一期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7709e2f0-004d-4e3f-a172-8cd680b047b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指杂志等这一期之前的一期。"}, {"text": "上机", "is_correct": false, "explanation": "j 与 q 声母不同（不送气与送气），上机意思是登机或上网操作。"}, {"text": "上衣", "is_correct": false, "explanation": "yī 与 qī 的声母不同（无声母与 q），上衣意思是穿在身上的衣服。"}, {"text": "上气", "is_correct": false, "explanation": "qì 与 qī 声调不同（第四声与第一声），上气意思是呼吸急促。"}], "explanations": {"上期": "正确：上期指杂志等这一期之前的一期。", "上机": "j 与 q 声母不同（不送气与送气），上机意思是登机或上网操作。", "上衣": "yī 与 qī 的声母不同（无声母与 q），上衣意思是穿在身上的衣服。", "上气": "qì 与 qī 声调不同（第四声与第一声），上气意思是呼吸急促。"}, "sentence_index": null, "correct_answer": "上期"}, "level_3": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指上一期节目，与后文的“这期”相对。"}, {"text": "本期", "is_correct": false, "explanation": "语义：“本期”与后文的“这期”指同一期，前后自相重复，句意矛盾。"}, {"text": "上册", "is_correct": false, "explanation": "语义：“上册”指书籍的前一册，不用于按期播出的节目，与“节目”不搭配。"}, {"text": "上篇", "is_correct": false, "explanation": "搭配：“篇”用于文章、书籍，不用于按期播出的节目。"}], "explanations": {"上期": "正确：上期指上一期节目，与后文的“这期”相对。", "本期": "语义：“本期”与后文的“这期”指同一期，前后自相重复，句意矛盾。", "上册": "语义：“上册”指书籍的前一册，不用于按期播出的节目，与“节目”不搭配。", "上篇": "搭配：“篇”用于文章、书籍，不用于按期播出的节目。"}, "sentence_index": 0, "correct_answer": "上期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们上期见面是在去年。", "explanation": "这里应该用〈上次〉。“上期”只用于杂志等按期出版的前一期，一次性的见面要说“上次”。"}, {"text": "上期的地震很严重。", "explanation": "这里应该用〈那次〉。“上期”用于杂志、节目等按期出版或播出的前一期，地震是一次性的自然灾害，应说“那次”。"}, {"text": "上期的婚礼很热闹。", "explanation": "这里应该用〈上回〉。婚礼是一次性的事，不属于按期出版的东西，不能说“上期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指前一期，与后文的“这期的结局”依次对应。"}, {"text": "末期", "is_correct": false, "explanation": "语义：末期指最后阶段，不是可以阅读的一期，与“再看这期的结局”的先后顺序矛盾。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是一次性的演出，没有按期连载的“这期”，与“再看这期的结局”的语境不符。"}, {"text": "年终", "is_correct": false, "explanation": "语义：“年终”是年末这一时间点，不是按期出版的一期，与“这期”的语境不符。"}], "explanations": {"上期": "正确：上期指前一期，与后文的“这期的结局”依次对应。", "末期": "语义：末期指最后阶段，不是可以阅读的一期，与“再看这期的结局”的先后顺序矛盾。", "演唱会": "语义：演唱会是一次性的演出，没有按期连载的“这期”，与“再看这期的结局”的语境不符。", "年终": "语义：“年终”是年末这一时间点，不是按期出版的一期，与“这期”的语境不符。"}, "sentence_index": 6, "correct_answer": "上期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上期搬家花了很多时间。", "explanation": "这里应该用〈前一次〉。“上期”只用于按期出版或计算的事物，搬家是一次性的事。"}, {"text": "上期我去过上海。", "explanation": "这里应该用〈以前〉。“上期”不用于个人经历中的过去，只指前一期。"}, {"text": "上期事故的原因还没查清。", "explanation": "这里应该用〈那次〉。“上期”只指按期的前一期，单次事故要说“那次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没看上期个杂志。", "corrected_sentence": "我还没看上期的杂志。", "error_description": "量词误用：“上期”作定语修饰“杂志”，中间应用结构助词“的”，不能用量词“个”。应说“上期的杂志”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我借了上期地杂志。", "corrected_sentence": "我借了上期的杂志。", "error_description": "结构助词错误：“上期”修饰“杂志”，应用“的”，不能用“地”。“地”用于修饰动词、形容词，不用于名词前的定语。应说“上期的杂志”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下期", "is_correct": true, "explanation": "正确：“下期”与“上期”是反义词，指后一个统计期。"}, {"text": "房东", "is_correct": false, "explanation": "房东是出租房屋的人，与“上期”没有反义关系。"}, {"text": "押金", "is_correct": false, "explanation": "押金是租房时交的款项，与“上期”没有反义关系。"}, {"text": "水电费", "is_correct": false, "explanation": "水电费是费用名称，与“上期”没有反义关系。"}], "correct_answer": "下期", "explanations": {"下期": "正确：“下期”与“上期”是反义词，指后一个统计期。", "房东": "房东是出租房屋的人，与“上期”没有反义关系。", "押金": "押金是租房时交的款项，与“上期”没有反义关系。", "水电费": "水电费是费用名称，与“上期”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下期", "is_correct": true, "explanation": "正确：“下期”与“上期”是反义词，指后一个统计期。"}, {"text": "合同", "is_correct": false, "explanation": "合同是双方约定的文书，与“上期”没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "天气指大气状况，与“上期”没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "花园是种植花草的地方，与“上期”没有反义关系。"}], "correct_answer": "下期", "explanations": {"下期": "正确：“下期”与“上期”是反义词，指后一个统计期。", "合同": "合同是双方约定的文书，与“上期”没有反义关系。", "天气": "天气指大气状况，与“上期”没有反义关系。", "花园": "花园是种植花草的地方，与“上期”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "上一期；前一个时期。", "primary_collocate": null, "pronunciation": "shàng qī", "ipa": "ʂɑŋ˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这个月的销售额比上期多了一成。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上期的成绩不好，这学期他很努力。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司上期赚了不少钱。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上期的利润是五十万，这期是八十万。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "与上期相比，今年的用水量少了。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上期的业绩还没统计完，这期的数字又出来了。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他上期的考试成绩比这次好。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先看一下上期的账目。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这期的支出比上期少得多。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上期的房租已经交了。", "target_word": "上期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "账目、成绩、业绩等按期计算时，前一个时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7709e2f0-004d-4e3f-a172-8cd680b047b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指账目、成绩等按期计算的前一个时期。"}, {"text": "上机", "is_correct": false, "explanation": "j 与 q 声母不同（不送气与送气），上机意思是登机或上网操作。"}, {"text": "上衣", "is_correct": false, "explanation": "yī 与 qī 的声母不同（无声母与 q），上衣意思是穿在身上的衣服。"}, {"text": "上司", "is_correct": false, "explanation": "s 与 q 声母不同，上司意思是上级、领导。"}, {"text": "上气", "is_correct": false, "explanation": "qì 与 qī 声调不同（第四声与第一声），上气意思是呼吸急促。"}], "explanations": {"上期": "正确：上期指账目、成绩等按期计算的前一个时期。", "上机": "j 与 q 声母不同（不送气与送气），上机意思是登机或上网操作。", "上衣": "yī 与 qī 的声母不同（无声母与 q），上衣意思是穿在身上的衣服。", "上司": "s 与 q 声母不同，上司意思是上级、领导。", "上气": "qì 与 qī 声调不同（第四声与第一声），上气意思是呼吸急促。"}, "sentence_index": null, "correct_answer": "上期"}, "level_3": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指上一个统计期，与“这个月”相对。"}, {"text": "本期", "is_correct": false, "explanation": "语义：“本期”就是“这个月”所在的时期，拿销售额与自身比较，不成立。"}, {"text": "下个月", "is_correct": false, "explanation": "语义：下个月尚未发生，不能与已经发生的销售额作比较。"}, {"text": "书店", "is_correct": false, "explanation": "配价：“比”的对象应是同类的时段或数量，书店不能与销售额相比。"}], "explanations": {"上期": "正确：上期指上一个统计期，与“这个月”相对。", "本期": "语义：“本期”就是“这个月”所在的时期，拿销售额与自身比较，不成立。", "下个月": "语义：下个月尚未发生，不能与已经发生的销售额作比较。", "书店": "配价：“比”的对象应是同类的时段或数量，书店不能与销售额相比。"}, "sentence_index": 0, "correct_answer": "上期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上期的车祸是他不小心造成的。", "explanation": "这里应该用〈上次〉。“上期”用于账目、业绩等按期计算的时期，车祸是一次性的事，应说“上次”。"}, {"text": "上期的毕业典礼很隆重。", "explanation": "这里应该用〈上一届〉。“上期”用于账目等按期计算的时期，毕业典礼是一次性的事，应说“上一届”。"}, {"text": "上期出差我去了三个城市。", "explanation": "这里应该用〈那次〉。“上期”用于按期计算的时期，一次出差要说“那次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上期", "is_correct": true, "explanation": "正确：上期指前一个考核时期，与“这次”相对。"}, {"text": "演唱会", "is_correct": false, "explanation": "搭配：“演唱会”不能作“考试成绩”的时段限定。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂不是考核时段，与“考试成绩”不相容。"}, {"text": "考场", "is_correct": false, "explanation": "搭配：考场是考试地点，不能用来限定“成绩”的时段。"}], "explanations": {"上期": "正确：上期指前一个考核时期，与“这次”相对。", "演唱会": "搭配：“演唱会”不能作“考试成绩”的时段限定。", "食堂": "语义：食堂不是考核时段，与“考试成绩”不相容。", "考场": "搭配：考场是考试地点，不能用来限定“成绩”的时段。"}, "sentence_index": 6, "correct_answer": "上期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上期买房的时候我还在上学。", "explanation": "这里应该用〈当时〉。“上期”用于账目等按期计算的时期，买房是一次性的事。"}, {"text": "上期手术很成功。", "explanation": "这里应该用〈前一次〉。手术是一次性的事，不能用“上期”。"}, {"text": "上期的洪水淹了很多房子。", "explanation": "这里应该用〈那次〉。“上期”用于按期计算或出版的时期，洪水是一次性的自然灾害，应说“那次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司还没结算上期地账目。", "corrected_sentence": "公司还没结算上期的账目。", "error_description": "结构助词错误：“上期”修饰“账目”，应用结构助词“的”，不能用“地”。应说“上期的账目”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个上期的收入比这期高。", "corrected_sentence": "上期的收入比这期高。", "error_description": "指示词错误：“上期”本身已指前一个统计期，不能再用“这个”限定，应去掉“这个”，说“上期的收入”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
