INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95643, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "不管是这样还是那样，都可以。", "primary_collocate": null, "pronunciation": "yě hǎo", "ipa": "jɛ˨˩ xɑʊ˨˩", "syllable_count": 2, "sentences": [{"text": "你去也好，不去也好，我都没意见。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车也好，走路也好，都能到学校。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝茶也好，喝咖啡也好，我都可以。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天也好，晚上也好，他都在家。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中文也好，英文也好，我都愿意学。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贵也好，便宜也好，我都要买。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨也好，不下雨也好，我们都去。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说也好，不说也好，事情都已经这样了。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色也好，蓝色也好，这件衣服都好看。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天也好，明天也好，我都有时间。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "A也好，B也好，都……：列举几种情况，结果都一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7505f76d-2f05-4bdb-821e-935ffba3ab82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95643, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "也好", "is_correct": true, "explanation": "正确。“也好”表示无论哪种情况都行，与后面的“不去也好”配合使用。"}, {"text": "还是", "is_correct": false, "explanation": "配价：“还是”要连接两个选项，“你去还是”后面没有选项，不能这样放。"}, {"text": "或者", "is_correct": false, "explanation": "配价：“或者”连接并列的选项，“你去或者”前后不成立。"}, {"text": "不管", "is_correct": false, "explanation": "语义：“不管”表示条件不论，后面要接“都”的小句，这里语义不通。"}], "explanations": {"也好": "正确。“也好”表示无论哪种情况都行，与后面的“不去也好”配合使用。", "还是": "配价：“还是”要连接两个选项，“你去还是”后面没有选项，不能这样放。", "或者": "配价：“或者”连接并列的选项，“你去或者”前后不成立。", "不管": "语义：“不管”表示条件不论，后面要接“都”的小句，这里语义不通。"}, "sentence_index": 0, "correct_answer": "也好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不来也好，我们早点开始。", "explanation": "这里的“也好”表示“这样也行、不妨”，是另一个义项，只有一种情况，不是列举几种情况都一样。"}, {"text": "你来也好，我们再一起吃饭。", "explanation": "这里的“也好”表示“还算可以”，是另一个义项。本句要表示几种情况都成立，不是说“你来”这件事本身好。"}, {"text": "这份礼物也好，我很喜欢。", "explanation": "这里的“也好”表示“还算可以”，是另一个义项。本句要表示几种情况都成立，不是评价礼物的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95643, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "也好", "is_correct": true, "explanation": "正确。“也好”表示无论下雨与否都行，与后面的“不下雨也好”配合。"}, {"text": "所以", "is_correct": false, "explanation": "配价：“所以”要引出结果，“下雨所以”后面没有结果，不能放在这里。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，“下雨因为”语义不通。"}, {"text": "虽然", "is_correct": false, "explanation": "配价：“虽然”要和“但是”“却”等配合，这里后面没有转折。"}], "explanations": {"也好": "正确。“也好”表示无论下雨与否都行，与后面的“不下雨也好”配合。", "所以": "配价：“所以”要引出结果，“下雨所以”后面没有结果，不能放在这里。", "因为": "语义：“因为”表示原因，“下雨因为”语义不通。", "虽然": "配价：“虽然”要和“但是”“却”等配合，这里后面没有转折。"}, "sentence_index": 6, "correct_answer": "也好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这样也好，省得麻烦。", "explanation": "这里的“也好”表示“这样也行”，是另一个义项，不是列举几种情况结果都一样。"}, {"text": "早点结束也好，大家都累了。", "explanation": "这里的“也好”表示“不妨、也行”，是另一个义项，只说一种情况。"}, {"text": "你去看看也好。", "explanation": "这里的“也好”表示建议“不妨”，是另一个义项，不是列举结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95643, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "走路也很，骑车也好，我都能到。", "corrected_sentence": "走路也好，骑车也好，我都能到。", "error_description": "错误：列举结构“A也好，B也好，都……”中两项都要用“也好”，“走路也很”不完整，不成立。正确形式是“走路也好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95643, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末去也好着，平时去也好，我都有空。", "corrected_sentence": "周末去也好，平时去也好，我都有空。", "error_description": "错误：“也好”后面不能加“着”，“着”不能附在这个形式上。正确形式是“周末去也好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
