INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95644, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示无论选哪一种都行，或表示还算可以。", "primary_collocate": null, "pronunciation": "yě hǎo", "ipa": "jɛ˨˩ xɑʊ˨˩", "syllable_count": 2, "sentences": [{"text": "喝茶还是喝咖啡？喝茶也好。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天去还是明天去？明天也好。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不来也好，我们正好说说话。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样也好，你可以多休息几天。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先休息一下也好，明天再做。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要红的还是蓝的？红的也好。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了也好，家里终于安静了。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下大了，不出门也好。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐地铁去还是打车去？坐地铁也好。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "慢一点也好，路上安全。", "target_word": "也好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "放在句末表示这样也行、这样也不错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7505f76d-2f05-4bdb-821e-935ffba3ab82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "也好", "is_correct": true, "explanation": "正确。句末的“也好”表示“这样也行”。"}, {"text": "但是", "is_correct": false, "explanation": "配价：“但是”要连接前后两个小句，句末单独用不成立。"}, {"text": "不过", "is_correct": false, "explanation": "配价：“不过”表示转折，需要前文，句末单独用不成立。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，句末单独用语义不通。"}], "explanations": {"也好": "正确。句末的“也好”表示“这样也行”。", "但是": "配价：“但是”要连接前后两个小句，句末单独用不成立。", "不过": "配价：“不过”表示转折，需要前文，句末单独用不成立。", "尽管": "语义：“尽管”表示让步，句末单独用语义不通。"}, "sentence_index": 0, "correct_answer": "也好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "也好你来，我们一起吃饭。", "explanation": "位置错误：“也好”要放在它评价的小句后面，应说〈你来也好〉。"}, {"text": "也好他说，我就不多问了。", "explanation": "位置错误：“也好”不能放在主语前面，应说〈他说也好〉。"}, {"text": "我先去也好来，他随后来。", "explanation": "位置错误：“也好”不能插在两个动词之间，应删去“也好”，说〈我先去，他随后来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "也好", "is_correct": true, "explanation": "正确。“也好”放在小句后面，表示这件事也还算可以、不算坏。"}, {"text": "不管", "is_correct": false, "explanation": "语义：“不管”表示条件不论，这里语义不通。"}, {"text": "或者", "is_correct": false, "explanation": "配价：“或者”连接并列选项，这里前后不成立。"}, {"text": "还是", "is_correct": false, "explanation": "配价：“还是”需要连接两个选项，“他走了还是”后面没有选项。"}], "explanations": {"也好": "正确。“也好”放在小句后面，表示这件事也还算可以、不算坏。", "不管": "语义：“不管”表示条件不论，这里语义不通。", "或者": "配价：“或者”连接并列选项，这里前后不成立。", "还是": "配价：“还是”需要连接两个选项，“他走了还是”后面没有选项。"}, "sentence_index": 6, "correct_answer": "也好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们也好去公园吧，天气不错。", "explanation": "“也好”放在句末表示“这样也行”，不能像“也”那样放在动词前，应说〈我们去公园也好〉。"}, {"text": "也好他笑，我们就不管了。", "explanation": "位置错误：“也好”不能放在主语前面，应说〈他笑也好〉。"}, {"text": "他来也好去，我们等他。", "explanation": "位置错误：“也好”不能插在两个动词之间，应说〈他来也好〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你早点休息也好着，明天再做。", "corrected_sentence": "你早点休息也好，明天再做。", "error_description": "错误：“也好”后面不能加“着”，“着”不能附在这个表示“这样也行”的形式上。正确形式是“你早点休息也好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "坐地铁去也好过，省点钱。", "corrected_sentence": "坐地铁去也好，省点钱。", "error_description": "错误：表示“这样也行”的“也好”后面不能加体标“过”。正确形式是“坐地铁去也好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15c5bb3c-632a-4a5f-87ec-283975a5fd61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
