INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95645, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个人受很多人喜欢、欢迎的程度。", "primary_collocate": null, "pronunciation": "rén qì", "ipa": "ɻən˧˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "他很有人气，朋友特别多。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在学生中很有人气。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌好听，在学校里很有人气。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他性格好，所以在公司里人气很高。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小男孩在班里一直很有人气。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个歌手的人气越来越高了。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前没有人气，现在大家都喜欢他。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李爱帮助别人，在同事中人气很旺。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个演员靠这部电视剧有了人气。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那位医生很有人气，很多人都想找他看病。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "某个人受很多人喜欢、欢迎的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95645, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人气", "is_correct": true, "explanation": "rén qì 即“人气”，指某个人受大家喜欢、欢迎的程度。"}, {"text": "神气", "is_correct": false, "explanation": "shén 与 rén 声母不同（sh/r），意思是神气（威风、得意的样子）。"}, {"text": "忍气", "is_correct": false, "explanation": "rěn（第三声）与 rén（第二声）声调不同，意思是忍气（忍受委屈）。"}, {"text": "人际", "is_correct": false, "explanation": "jì 与 qì 声母不同（j/q），意思是人际（人与人之间的关系）。"}, {"text": "人次", "is_correct": false, "explanation": "cì 与 qì 声母不同（c/q），意思是人次（人数的统计单位）。"}, {"text": "燃气", "is_correct": false, "explanation": "rán 与 rén 韵母不同（an/en），意思是燃气（燃料气体）。"}], "explanations": {"人气": "rén qì 即“人气”，指某个人受大家喜欢、欢迎的程度。", "神气": "shén 与 rén 声母不同（sh/r），意思是神气（威风、得意的样子）。", "忍气": "rěn（第三声）与 rén（第二声）声调不同，意思是忍气（忍受委屈）。", "人际": "jì 与 qì 声母不同（j/q），意思是人际（人与人之间的关系）。", "人次": "cì 与 qì 声母不同（c/q），意思是人次（人数的统计单位）。", "燃气": "rán 与 rén 韵母不同（an/en），意思是燃气（燃料气体）。"}, "sentence_index": null, "correct_answer": "人气"}, "level_3": {"options": [{"text": "人气", "is_correct": true, "explanation": "与“有”搭配，指他受大家喜欢的程度。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“有面积”不能用来说人，句子要说的是人气。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指人的数量，不是受欢迎的程度。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“有体重”说人不通，朋友多与体重无关。"}], "explanations": {"人气": "与“有”搭配，指他受大家喜欢的程度。", "面积": "搭配：“有面积”不能用来说人，句子要说的是人气。", "人口": "语义：“人口”指人的数量，不是受欢迎的程度。", "体重": "搭配：“有体重”说人不通，朋友多与体重无关。"}, "sentence_index": 0, "correct_answer": "人气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的人气不够，要请几个同学来帮忙。", "explanation": "这里应该用〈人手〉。人手指能干活的人，人气说的是受欢迎的程度，不能用来说班里人不够、要请人帮忙。"}, {"text": "他的人气很大，一遇到小事就发火。", "explanation": "这里应该用〈脾气〉。脾气指性情和急躁的程度；“一遇到小事就发火”说的是脾气，人气说的是受欢迎的程度，不能这样用。"}, {"text": "他的人气增加了三公斤。", "explanation": "这里应该用〈体重〉。人气是抽象的受欢迎程度，不能用“公斤”计量，只有体重才会增加三公斤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95645, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人气", "is_correct": true, "explanation": "与“没有”搭配，指他以前不受大家欢迎。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，与人是否受欢迎无关。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“没有价格”说不通，人受欢迎的程度不说价格。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“没有体温”指没有温度，与是否受欢迎无关。"}], "explanations": {"人气": "与“没有”搭配，指他以前不受大家欢迎。", "颜色": "语义：“颜色”指色彩，与人是否受欢迎无关。", "价格": "搭配：“没有价格”说不通，人受欢迎的程度不说价格。", "体温": "语义：“没有体温”指没有温度，与是否受欢迎无关。"}, "sentence_index": 6, "correct_answer": "人气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的人气提高了五厘米。", "explanation": "这里应该用〈身高〉。人气不能用“厘米”计量，只有身高才会提高五厘米。"}, {"text": "他的人气增加了一岁。", "explanation": "这里应该用〈年龄〉。人气没有年岁，只有年龄才会增加一岁。"}, {"text": "他的人气升高了一度。", "explanation": "这里应该用〈体温〉。人气不能说“升高一度”，这种说法只用于体温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95645, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在班里很人气，大家都愿意和他玩。", "corrected_sentence": "他在班里很有人气，大家都愿意和他玩。", "error_description": "“人气”是名词，不能直接用“很”修饰；应说“很有人气”，漏掉“有”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95645, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一个人气，大家都喜欢她。", "corrected_sentence": "她很有人气，大家都喜欢她。", "error_description": "“人气”是抽象名词，不能用量词“个”来数；应说“很有人气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
