INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "受人欢迎、受人关注的程度。", "primary_collocate": null, "pronunciation": "rén qì", "ipa": "ɻən˧˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "这家小店的人气很高。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目最近人气越来越高。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影在年轻人中很有人气。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新开的饭馆人气不太好，客人很少。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的人气比去年高多了。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上投票能看出哪个节目人气最高。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气不好，这个景点的人气下降了。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书出版后，人气一直很旺。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的人气让唱片公司很高兴。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动画片人气太高了，孩子们都喜欢看。", "target_word": "人气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "事物、节目、店铺等受欢迎、受关注的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95646, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人气", "is_correct": true, "explanation": "rén qì 即“人气”，指事物受欢迎、受关注的程度。"}, {"text": "神气", "is_correct": false, "explanation": "shén 与 rén 声母不同（sh/r），意思是神气（威风、得意的样子）。"}, {"text": "忍气", "is_correct": false, "explanation": "rěn（第三声）与 rén（第二声）声调不同，意思是忍气（忍受委屈）。"}, {"text": "人际", "is_correct": false, "explanation": "jì 与 qì 声母不同（j/q），意思是人际（人与人之间的关系）。"}, {"text": "人次", "is_correct": false, "explanation": "cì 与 qì 声母不同（c/q），意思是人次（人数的统计单位）。"}, {"text": "燃气", "is_correct": false, "explanation": "rán 与 rén 韵母不同（an/en），意思是燃气（燃料气体）。"}], "explanations": {"人气": "rén qì 即“人气”，指事物受欢迎、受关注的程度。", "神气": "shén 与 rén 声母不同（sh/r），意思是神气（威风、得意的样子）。", "忍气": "rěn（第三声）与 rén（第二声）声调不同，意思是忍气（忍受委屈）。", "人际": "jì 与 qì 声母不同（j/q），意思是人际（人与人之间的关系）。", "人次": "cì 与 qì 声母不同（c/q），意思是人次（人数的统计单位）。", "燃气": "rán 与 rén 韵母不同（an/en），意思是燃气（燃料气体）。"}, "sentence_index": null, "correct_answer": "人气"}, "level_3": {"options": [{"text": "人气", "is_correct": true, "explanation": "与“很高”搭配，指小店受欢迎的程度。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”不说“很高”，这句说的是小店受欢迎的程度。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”一般说好、浓、淡，不用“很高”来形容。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指人的数量，不是受欢迎的程度。"}], "explanations": {"人气": "与“很高”搭配，指小店受欢迎的程度。", "面积": "搭配：“面积”不说“很高”，这句说的是小店受欢迎的程度。", "味道": "搭配：“味道”一般说好、浓、淡，不用“很高”来形容。", "人口": "语义：“人口”指人的数量，不是受欢迎的程度。"}, "sentence_index": 0, "correct_answer": "人气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的人气很大，动不动就发火，同事都不敢跟他说话。", "explanation": "这里应该用〈脾气〉。脾气指性情和急躁的程度，人气说的是受欢迎的程度；“动不动就发火”说的是脾气，不能用人气。"}, {"text": "这碗汤还有很多人气，快趁热喝。", "explanation": "这里应该用〈热气〉。热气指汤冒出的热气流，人气是受欢迎的程度；两者读音相近，但意思完全不同，不能混用。"}, {"text": "这家工厂的人气太少，订单做不完，得多招几个工人。", "explanation": "这里应该用〈人手〉。人手指能干活的人，人气是受欢迎的程度，不能用来说工人不够。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人气", "is_correct": true, "explanation": "与“下降”搭配，指景点受欢迎的程度降低。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不说“下降”，本句说的是景点受欢迎程度降低。"}, {"text": "体温", "is_correct": false, "explanation": "语义：景点没有体温，“体温下降”说的是人，不符合“景点”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：景点没有体重，“体重下降”只能说人或动物。"}], "explanations": {"人气": "与“下降”搭配，指景点受欢迎的程度降低。", "颜色": "搭配：“颜色”不说“下降”，本句说的是景点受欢迎程度降低。", "体温": "语义：景点没有体温，“体温下降”说的是人，不符合“景点”。", "体重": "语义：景点没有体重，“体重下降”只能说人或动物。"}, "sentence_index": 6, "correct_answer": "人气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的人气提高了五十元。", "explanation": "这里应该用〈价格〉。人气是受欢迎的程度，不能用“元”来计算提高的数额，涨价应说价格提高。"}, {"text": "这个箱子的人气增加了三公斤。", "explanation": "这里应该用〈重量〉。人气不能用“公斤”计量，只有重量才会增加几公斤。"}, {"text": "这套房子的人气增加了十平方米。", "explanation": "这里应该用〈面积〉。人气不能用平方米计算，只有面积才会增加几平方米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅的人气变轻了。", "corrected_sentence": "这家餐厅的人气变旺了。", "error_description": "“人气”可以“变旺”“变高”，不能“变轻”；“轻”指重量减少，不用于人气。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家网店的一个人气很旺。", "corrected_sentence": "这家网店的人气很旺。", "error_description": "“人气”是抽象名词，不能用量词“个”来数；直接说“人气很旺”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95647, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
