INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95647, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人做事时一直有的样子。", "primary_collocate": null, "pronunciation": "zuò fēng", "ipa": "tswɔ˥˩ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他做事一向认真，这是他的作风。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王的作风很踏实，从不说空话。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的作风很干脆，有事马上办。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个经理作风很严，大家都怕他。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直保持着认真的作风。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸做事慢，这是他多年的作风。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢他大方的作风。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的作风是今天的事今天做完。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的作风一直没变，还是那么谨慎。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她办事作风利落，从不拖到明天。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种作风", "label": "量词"}, {"form": "工作作风", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人做事一贯的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4747408d-1a98-454a-a674-44dda78aa04a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气指气候状况，不能用来说明一个人做事的一贯样子。"}, {"text": "作风", "is_correct": true, "explanation": "正确。作风指一个人做事时一直有的样子，与“做事一向认真”相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外形特征，与“做事一向认真”的描述无关。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是居住的建筑，与“做事认真”的评价不搭，句子说不通。"}], "explanations": {"天气": "语义：天气指气候状况，不能用来说明一个人做事的一贯样子。", "作风": "正确。作风指一个人做事时一直有的样子，与“做事一向认真”相符。", "身高": "体貌：身高是外形特征，与“做事一向认真”的描述无关。", "房子": "语义：房子是居住的建筑，与“做事认真”的评价不搭，句子说不通。"}, "sentence_index": 0, "correct_answer": "作风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的作风很独特，穿起来很有个性。", "explanation": "这里应该用〈风格〉。作风指人做事的一贯方式，衣服的样式要用风格，不能说作风。"}, {"text": "这把椅子的作风很结实，坐上去很稳。", "explanation": "这里应该用〈质量〉。作风指人做事的一贯方式，家具的牢固程度不能说作风。"}, {"text": "这种药的作风很快，吃下去十分钟就见效。", "explanation": "这里应该用〈药效〉。作风指人做事的一贯方式，药物的效果要用药效，不能说作风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "门票", "is_correct": false, "explanation": "搭配：“大方”修饰人的态度或行为，不修饰门票，“大方的门票”不通。"}, {"text": "作风", "is_correct": true, "explanation": "正确。作风指一个人一贯的做事或待人方式，与“大方”相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，不是一个人的一贯样子，“大方的考试”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描写体型，“大方”不修饰身材，“大方的身材”不通。"}], "explanations": {"门票": "搭配：“大方”修饰人的态度或行为，不修饰门票，“大方的门票”不通。", "作风": "正确。作风指一个人一贯的做事或待人方式，与“大方”相符。", "考试": "语义：考试是测验，不是一个人的一贯样子，“大方的考试”说不通。", "身材": "体貌：身材描写体型，“大方”不修饰身材，“大方的身材”不通。"}, "sentence_index": 6, "correct_answer": "作风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他提出的作风很可行，大家都同意了。", "explanation": "这里应该用〈方案〉。作风指人做事的一贯态度和方式，具体的计划要用方案，不能说作风。"}, {"text": "这座桥的作风很长，走了很久才到对岸。", "explanation": "这里应该用〈长度〉。作风指人做事的一贯方式，桥的长短不能说作风。"}, {"text": "今年冬天的作风很冷，很多人都感冒了。", "explanation": "这里应该用〈天气〉。作风指人做事的一贯方式，气候的冷暖不能说作风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老张待人客气，这是他的一只作风。", "corrected_sentence": "老张待人客气，这是他的一种作风。", "error_description": "量词错误：“作风”要用量词“种”，“一只”用于单个的动物或物件，不能修饰作风。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的作风很利落，做事也很作风。", "corrected_sentence": "她的作风很利落，做事也很认真。", "error_description": "词性错误：“作风”是名词，不能像形容词那样受“很”修饰，“做事很作风”不通，应换成形容词如“认真”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
