INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们在思想、工作和生活上表现出来的态度和风格。", "primary_collocate": null, "pronunciation": "zuò fēng", "ipa": "tswɔ˥˩ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "公司要求员工改进工作作风。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的教学作风很民主。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保持艰苦朴素的生活作风。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校提倡良好的学习作风。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导带头改变了官僚作风。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作作风让同事们很佩服。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队有着优良的作风。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂里的作风好，大家都愿意努力工作。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的作风很务实，不搞形式。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求同学们培养认真的学习作风。", "target_word": "作风", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种作风", "label": "量词"}, {"form": "工作作风", "label": "复合"}], "register": "中性", "sense_fingerprint": "思想、工作、生活上表现的态度和风格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4747408d-1a98-454a-a674-44dda78aa04a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，员工无法“改进”天气，“工作天气”也不成词。"}, {"text": "作风", "is_correct": true, "explanation": "正确。作风指做事的一贯态度和方式，与“改进”搭配自然。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址是住处或单位的位置，“改进工作地址”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是自然增长的岁数，不能“改进”，“工作年龄”在此也说不通。"}], "explanations": {"天气": "语义：天气是自然现象，员工无法“改进”天气，“工作天气”也不成词。", "作风": "正确。作风指做事的一贯态度和方式，与“改进”搭配自然。", "地址": "语义：地址是住处或单位的位置，“改进工作地址”说不通。", "年龄": "语义：年龄是自然增长的岁数，不能“改进”，“工作年龄”在此也说不通。"}, "sentence_index": 0, "correct_answer": "作风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的作风很快，打开文件很方便。", "explanation": "这里应该用〈速度〉。作风指人的做事态度和习惯，机器的运行快慢要用速度。"}, {"text": "这家店的作风很便宜，大家都愿意来买。", "explanation": "这里应该用〈价格〉。作风指人的态度和风格，商品的价钱要用价格，不能说作风。"}, {"text": "这个问题的作风很复杂，我们花了一周才搞清楚。", "explanation": "这里应该用〈情况〉。作风指人的态度和风格，事情的状况要用情况，不能说作风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发型", "is_correct": false, "explanation": "语义：发型是外形，不能说“有着优良的发型”，句中指的是部队的作风。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“优良”修饰品质、作风，不与“体重”搭配，说不通。"}, {"text": "作风", "is_correct": true, "explanation": "正确。作风指一个群体或个人的一贯态度和风格，与“优良”搭配自然。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的体格，不能用“优良”来形容，句子说不通。"}], "explanations": {"发型": "语义：发型是外形，不能说“有着优良的发型”，句中指的是部队的作风。", "体重": "搭配：“优良”修饰品质、作风，不与“体重”搭配，说不通。", "作风": "正确。作风指一个群体或个人的一贯态度和风格，与“优良”搭配自然。", "身高": "语义：身高是人的体格，不能用“优良”来形容，句子说不通。"}, "sentence_index": 6, "correct_answer": "作风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的作风很清澈，鱼很多。", "explanation": "这里应该用〈水质〉。作风指人的态度和风格，河水的清浊要用水质，不能说作风。"}, {"text": "这个班的作风比去年多了十个人，教室都坐满了。", "explanation": "这里应该用〈人数〉。作风指人的态度和风格，班级的人数不能说作风。"}, {"text": "这块布料的作风很柔软，穿起来很舒服。", "explanation": "这里应该用〈质地〉。作风指人的态度和风格，布料的软硬要用质地，不能说作风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校有一条良好的学习作风。", "corrected_sentence": "这所学校有一种良好的学习作风。", "error_description": "量词错误：“作风”要用量词“种”，“条”用于细长的东西，不能修饰作风。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的作风们很干练，大家都信任她。", "corrected_sentence": "她的作风很干练，大家都信任她。", "error_description": "复数错误：“作风”是抽象名词，不能加“们”表示复数，应去掉“们”，改为“她的作风很干练”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
