INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95649, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用旧的东西再做一次新的。", "primary_collocate": null, "pronunciation": "zài zhì", "ipa": "tsaɪ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "工厂把旧纸再制成新纸。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧衣服可以再制成包。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旧瓶子再制成了一盏灯。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧轮胎再制后，可以做成小椅子。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店专门再制旧家具。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧报纸再制以后，变成了漂亮的盒子。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校用旧木头再制了几张桌子。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧塑料再制成新的玩具，又环保又便宜。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把没用的旧牛仔裤再制成了帽子。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧东西再制过一次，就像新的一样。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再制了", "label": "体标"}, {"form": "再制过", "label": "体标"}], "register": "通用", "sense_fingerprint": "把旧物品改做成新的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95649, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再制", "is_correct": true, "explanation": "正确。再制指用旧东西再做成新的，与听到的读音一致。"}, {"text": "再次", "is_correct": false, "explanation": "cì（第四声）与 zhì 声母不同（c 与 zh），意思是“再一次”，与“把旧物做成新的”无关。"}, {"text": "再试", "is_correct": false, "explanation": "shì（第四声）与 zhì 声母不同（sh 与 zh），意思是“再尝试一次”。"}, {"text": "在职", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是“担任职务”。"}, {"text": "在世", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是“活在世上”。"}], "explanations": {"再制": "正确。再制指用旧东西再做成新的，与听到的读音一致。", "再次": "cì（第四声）与 zhì 声母不同（c 与 zh），意思是“再一次”，与“把旧物做成新的”无关。", "再试": "shì（第四声）与 zhì 声母不同（sh 与 zh），意思是“再尝试一次”。", "在职": "zhí（第二声）与 zhì（第四声）声调不同，意思是“担任职务”。", "在世": "shì 与 zhì 声母不同（sh 与 zh），意思是“活在世上”。"}, "sentence_index": null, "correct_answer": "再制"}, "level_3": {"options": [{"text": "再制", "is_correct": true, "explanation": "正确。“把旧纸再制成新纸”表示把旧纸加工成新纸，与句意相合。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”是烧坏、毁掉，与“变成新纸”的意思相反。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”的对象是书本、文件，不能说装订成新纸。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”是把内容印在纸上，不能说打印成新纸。"}], "explanations": {"再制": "正确。“把旧纸再制成新纸”表示把旧纸加工成新纸，与句意相合。", "烧毁": "语义：“烧毁”是烧坏、毁掉，与“变成新纸”的意思相反。", "装订": "搭配：“装订”的对象是书本、文件，不能说装订成新纸。", "打印": "搭配：“打印”是把内容印在纸上，不能说打印成新纸。"}, "sentence_index": 0, "correct_answer": "再制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "壁虎断了尾巴以后会再制出一条新的。", "explanation": "这里应该用〈再生〉。断尾后长出新的是生物自身的再生；再制指人把旧物加工成新的物品。"}, {"text": "这条马路破得厉害，要再制一遍。", "explanation": "这里应该用〈重修〉。再制用于把旧物料加工成新成品，道路、建筑等要用重修。"}, {"text": "这篇作文写得不好，我想再制一遍。", "explanation": "这里应该用〈改写〉。再制针对物料或物品的加工，文章的修改要用改写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95649, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "再制", "is_correct": true, "explanation": "正确。再制是用旧东西再做成新的，与听到的读音一致。"}, {"text": "赛制", "is_correct": false, "explanation": "sài 与 zài 声母不同（s 与 z），意思是比赛的制度。"}, {"text": "栽植", "is_correct": false, "explanation": "zāi（第一声）与 zài 声调不同，zhí（第二声）与 zhì 声调不同，意思是种植树木。"}, {"text": "在职", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，其余音节相同，意思是“担任职务”。"}, {"text": "在世", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是“活在世上”。"}], "explanations": {"再制": "正确。再制是用旧东西再做成新的，与听到的读音一致。", "赛制": "sài 与 zài 声母不同（s 与 z），意思是比赛的制度。", "栽植": "zāi（第一声）与 zài 声调不同，zhí（第二声）与 zhì 声调不同，意思是种植树木。", "在职": "zhí（第二声）与 zhì（第四声）声调不同，其余音节相同，意思是“担任职务”。", "在世": "shì 与 zhì 声母不同（sh 与 zh），意思是“活在世上”。"}, "sentence_index": null, "correct_answer": "再制"}, "level_3": {"options": [{"text": "再制", "is_correct": true, "explanation": "正确。“用旧木头再制了几张桌子”表示用旧木头加工成新的桌子，与句意相合。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物或作物，不能说种植桌子。"}, {"text": "生长", "is_correct": false, "explanation": "配价：“生长”是不及物动词，不能带“几张桌子”作宾语。"}, {"text": "拆卸", "is_correct": false, "explanation": "语义：“拆卸”是把东西拆开，与“用旧木头做成桌子”的意思相反。"}], "explanations": {"再制": "正确。“用旧木头再制了几张桌子”表示用旧木头加工成新的桌子，与句意相合。", "种植": "搭配：“种植”的对象是植物或作物，不能说种植桌子。", "生长": "配价：“生长”是不及物动词，不能带“几张桌子”作宾语。", "拆卸": "语义：“拆卸”是把东西拆开，与“用旧木头做成桌子”的意思相反。"}, "sentence_index": 6, "correct_answer": "再制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的手机屏幕碎了，拿去再制了。", "explanation": "这里应该用〈修理〉。坏了的手机修好要用修理；再制是把旧物加工成新的东西。"}, {"text": "这篇小说要再制成英文版，好给外国读者看。", "explanation": "这里应该用〈翻译〉。语言文字的转换要用翻译；再制是把物料加工成成品。"}, {"text": "这份合同条款要再制一次。", "explanation": "这里应该用〈修订〉。合同条款的改动要用修订；再制用于把旧物料加工成新品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把旧报纸再制到了一个文件夹。", "corrected_sentence": "他把旧报纸再制成了一个文件夹。", "error_description": "“制”的结果补语应用“成”，说“再制成了”，不说“再制到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把旧木头再制了成一张小桌子。", "corrected_sentence": "工人把旧木头再制成了一张小桌子。", "error_description": "“了”的位置错误。结果补语“成”在前，动态助词“了”在后，应说“再制成了”，不说“再制了成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
