INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95650, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "重新制作；再次加工制成。", "primary_collocate": null, "pronunciation": "zài zhì", "ipa": "tsaɪ˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "工厂把原料再制成更细的粉。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批茶叶要送到工厂再制。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做好的糖还要再制一次，才能卖。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶再制后，可以做成奶酪。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些药材需要再制，才能当药用。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批零件有缺陷，工厂要把它们再制一遍。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁块在工厂里再制成了各种零件。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货不合格，公司决定再制。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种盐再制以后，味道更好。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些纸浆杂质太多，要先再制一次才能用。", "target_word": "再制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再制了", "label": "体标"}, {"form": "再制过", "label": "体标"}], "register": "通用", "sense_fingerprint": "重新制作，或对已有的东西再次加工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再制", "is_correct": true, "explanation": "正确。再制指重新加工制作，与听到的读音一致。"}, {"text": "再次", "is_correct": false, "explanation": "cì（第四声）与 zhì 声母不同（c 与 zh），意思是“再一次”，不指加工制作。"}, {"text": "在职", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是“担任职务”。"}, {"text": "栽植", "is_correct": false, "explanation": "zāi（第一声）与 zài 声调不同，zhí（第二声）与 zhì 声调不同，意思是种植树木。"}, {"text": "在世", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是“活在世上”。"}], "explanations": {"再制": "正确。再制指重新加工制作，与听到的读音一致。", "再次": "cì（第四声）与 zhì 声母不同（c 与 zh），意思是“再一次”，不指加工制作。", "在职": "zhí（第二声）与 zhì（第四声）声调不同，意思是“担任职务”。", "栽植": "zāi（第一声）与 zài 声调不同，zhí（第二声）与 zhì 声调不同，意思是种植树木。", "在世": "shì 与 zhì 声母不同（sh 与 zh），意思是“活在世上”。"}, "sentence_index": null, "correct_answer": "再制"}, "level_3": {"options": [{"text": "再制", "is_correct": true, "explanation": "正确。“工厂把原料再制成更细的粉”表示把原料再加工成更细的粉，与句意相合。"}, {"text": "保存", "is_correct": false, "explanation": "语义：“保存”是保留原样，与“加工成更细的粉”的意思相反。"}, {"text": "培育", "is_correct": false, "explanation": "搭配：“培育”用于生物或人才，不能说培育成粉。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”多用于枝叶、头发等，不能用来说原料加工成粉。"}], "explanations": {"再制": "正确。“工厂把原料再制成更细的粉”表示把原料再加工成更细的粉，与句意相合。", "保存": "语义：“保存”是保留原样，与“加工成更细的粉”的意思相反。", "培育": "搭配：“培育”用于生物或人才，不能说培育成粉。", "修剪": "搭配：“修剪”多用于枝叶、头发等，不能用来说原料加工成粉。"}, "sentence_index": 0, "correct_answer": "再制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "植物被剪断后会再制出新的枝条。", "explanation": "这里应该用〈再生〉。植物断枝后长出新枝是自然的再生；再制指人工把物料加工成新品。"}, {"text": "我的自行车坏了，拿去再制了。", "explanation": "这里应该用〈修理〉。坏了的自行车修好要用修理，再制是重新加工制作。"}, {"text": "这次考试没考好，我要再制一次。", "explanation": "这里应该用〈重做〉。考试、作业是做一遍的事，不是加工物料，应说重做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95650, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "再制", "is_correct": true, "explanation": "正确。再制指重新加工制作，与听到的读音一致。"}, {"text": "再试", "is_correct": false, "explanation": "shì（第四声）与 zhì 声母不同（sh 与 zh），意思是“再尝试一次”。"}, {"text": "在世", "is_correct": false, "explanation": "shì 与 zhì 声母不同，意思是“活在世上”。"}, {"text": "在职", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，其余音节相同，意思是“担任职务”。"}, {"text": "赛制", "is_correct": false, "explanation": "sài 与 zài 声母不同（s 与 z），意思是比赛的制度。"}], "explanations": {"再制": "正确。再制指重新加工制作，与听到的读音一致。", "再试": "shì（第四声）与 zhì 声母不同（sh 与 zh），意思是“再尝试一次”。", "在世": "shì 与 zhì 声母不同，意思是“活在世上”。", "在职": "zhí（第二声）与 zhì（第四声）声调不同，其余音节相同，意思是“担任职务”。", "赛制": "sài 与 zài 声母不同（s 与 z），意思是比赛的制度。"}, "sentence_index": null, "correct_answer": "再制"}, "level_3": {"options": [{"text": "再制", "is_correct": true, "explanation": "正确。“铁块在工厂里再制成了各种零件”表示把铁块加工成零件，与句意相合。"}, {"text": "孵化", "is_correct": false, "explanation": "搭配：“孵化”用于卵或雏形，不能说孵化成零件。"}, {"text": "繁殖", "is_correct": false, "explanation": "搭配：“繁殖”用于生物增加数量，不能说繁殖成零件。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”是变成固体或停止流动，与“加工成各种零件”不符。"}], "explanations": {"再制": "正确。“铁块在工厂里再制成了各种零件”表示把铁块加工成零件，与句意相合。", "孵化": "搭配：“孵化”用于卵或雏形，不能说孵化成零件。", "繁殖": "搭配：“繁殖”用于生物增加数量，不能说繁殖成零件。", "冻结": "语义：“冻结”是变成固体或停止流动，与“加工成各种零件”不符。"}, "sentence_index": 6, "correct_answer": "再制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性格被再制得更好了。", "explanation": "这里应该用〈改造〉。再制用于物品或物料的加工，人的性格、思想要用改造。"}, {"text": "这首诗被再制成了法文，发表在杂志上。", "explanation": "这里应该用〈翻译〉。语言文字的转换要用翻译，再制是把物料加工成成品。"}, {"text": "这份计划要再制一遍。", "explanation": "这里应该用〈修订〉。计划的修改要用修订，再制用于把旧物料加工成新品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂把废铁再制到了钢丝。", "corrected_sentence": "工厂把废铁再制成了钢丝。", "error_description": "“制”的结果补语应用“成”，说“再制成了”，不说“再制到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把这批钢材再制了成细丝。", "corrected_sentence": "工人把这批钢材再制成了细丝。", "error_description": "“了”的位置错误。应说“再制成了细丝”，“了”放在结果补语“成”之后，不说“再制了成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
