INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95651, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了好处，把别人的秘密告诉坏人，让别人吃亏。", "primary_collocate": null, "pronunciation": "chū mài", "ipa": "tʂʰu˥ maɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他为了钱出卖了朋友。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么能出卖我的秘密？", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人出卖了公司的消息。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会出卖任何一个朋友。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把我们的计划出卖给了对手。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出卖国家的秘密，最后进了监狱。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李出卖过同学，大家都不相信他。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了得到好处，他出卖了老板。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得你出卖了她，很难过。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁出卖了我们的地址？", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出卖了", "label": "体标：了"}, {"form": "出卖过", "label": "体标：过"}], "register": "通用", "sense_fingerprint": "为私利背叛他人，泄露秘密使人受损", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资助", "is_correct": false, "explanation": "语义：“资助”是拿出钱财帮助别人，与“为了钱”的目的相矛盾。"}, {"text": "出卖", "is_correct": true, "explanation": "正确：“出卖”指为私利背叛朋友，与“为了钱”的语境相符。"}, {"text": "捐赠", "is_correct": false, "explanation": "配价：“捐赠”的受事是钱物，不能以“朋友”作宾语。"}, {"text": "出售", "is_correct": false, "explanation": "搭配：“出售”的对象是商品，不能说“出售朋友”。"}], "explanations": {"资助": "语义：“资助”是拿出钱财帮助别人，与“为了钱”的目的相矛盾。", "出卖": "正确：“出卖”指为私利背叛朋友，与“为了钱”的语境相符。", "捐赠": "配价：“捐赠”的受事是钱物，不能以“朋友”作宾语。", "出售": "搭配：“出售”的对象是商品，不能说“出售朋友”。"}, "sentence_index": 0, "correct_answer": "出卖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把考试的好成绩出卖给了妈妈，她很高兴。", "explanation": "这里应该用〈告诉〉。“出卖”表示为私利损害他人，把好消息告诉家人不含这种意思。"}, {"text": "他为了帮朋友，把自己的秘密出卖给了对手。", "explanation": "这里应该用〈透露〉。“出卖”的动机是为私利损害他人，为朋友着想的做法不能用“出卖”。"}, {"text": "他把自己的积蓄出卖给了灾区。", "explanation": "这里应该用〈捐赠〉。“出卖”表示为私利损害他人，把积蓄无偿交给灾区不能用“出卖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "救", "is_correct": false, "explanation": "语义：“救过同学”是帮助同学，与“大家都不相信他”的语境矛盾。"}, {"text": "出卖", "is_correct": true, "explanation": "正确：“出卖过”表示曾为私利背叛同学，与后半句的语境一致。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”的对象是书刊作品，不能说“出版过同学”。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：“帮助过同学”是善意的行为，与“大家都不相信他”的语境矛盾。"}], "explanations": {"救": "语义：“救过同学”是帮助同学，与“大家都不相信他”的语境矛盾。", "出卖": "正确：“出卖过”表示曾为私利背叛同学，与后半句的语境一致。", "出版": "搭配：“出版”的对象是书刊作品，不能说“出版过同学”。", "帮助": "语义：“帮助过同学”是善意的行为，与“大家都不相信他”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "出卖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不小心把公司的秘密出卖给了记者。", "explanation": "这里应该用〈泄露〉。“出卖”是有意为私利而做的行为，不能和“不小心”搭配。"}, {"text": "我真诚地出卖你的帮助。", "explanation": "这里应该用〈感谢〉。“出卖”的对象是秘密或利益，不能用来指“帮助”。"}, {"text": "这个画家出卖了天空的颜色。", "explanation": "这里应该用〈画出〉。“出卖”的对象是秘密或利益，天空的颜色不能被出卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把朋友出卖了敌人。", "corrected_sentence": "他把朋友出卖给了敌人。", "error_description": "错误：“出卖”带接受者时，后面要用“给”引出对象，应说“出卖给……”。正确：“他把朋友出卖给了敌人。”缺少“给”，句子变成“出卖了敌人”，意思不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从不出卖过朋友。", "corrected_sentence": "我从没出卖过朋友。", "error_description": "错误：“从不”表示一贯不做，不能和表示经历的“过”搭配。表示没有发生过的经历应该用“没”，应说“我从没出卖过朋友。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
