INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95652, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了私利而损害他人，背弃原则或利益。", "primary_collocate": null, "pronunciation": "chū mài", "ipa": "tʂʰu˥ maɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他出卖良心，帮坏人做事。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人为了钱出卖自己的原则。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了钱，他出卖了尊严。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在关键时刻出卖了曾经信任他的战友。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了自保，他出卖了手下的兄弟。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了讨好上司，出卖了朋友的隐私。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了升官，他出卖了同事的利益。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我绝不会出卖自己的良心。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个记者为了名利，出卖了采访对象的信任。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人出卖公司利益，换来了很多钱。", "target_word": "出卖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出卖了", "label": "体标：了"}, {"form": "出卖过", "label": "体标：过"}], "register": "通用", "sense_fingerprint": "为私利背弃原则、良心或利益，损害他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b283c72b-36cb-4649-9609-b1e6be703ed2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护", "is_correct": false, "explanation": "语义：“保护良心”与后面“帮坏人做事”的语境相冲突。"}, {"text": "出卖", "is_correct": true, "explanation": "正确：“出卖良心”指为私利放弃原则，与“帮坏人做事”相符。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”的对象是书刊作品，不能说“出版良心”。"}, {"text": "捐献", "is_correct": false, "explanation": "搭配：“捐献”的对象是钱物，不能用于“良心”。"}], "explanations": {"保护": "语义：“保护良心”与后面“帮坏人做事”的语境相冲突。", "出卖": "正确：“出卖良心”指为私利放弃原则，与“帮坏人做事”相符。", "出版": "搭配：“出版”的对象是书刊作品，不能说“出版良心”。", "捐献": "搭配：“捐献”的对象是钱物，不能用于“良心”。"}, "sentence_index": 0, "correct_answer": "出卖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了救孩子，他出卖了自己的生命。", "explanation": "这里应该用〈牺牲〉。“出卖”表示为私利放弃原则或财物，与“为了救孩子”的无私意思相反。"}, {"text": "他把一生出卖给了教育事业。", "explanation": "这里应该用〈奉献〉。“出卖”表示为私利放弃原则或财物，把一生交给事业是无私的，不能用“出卖”。"}, {"text": "我们应该出卖交通规则。", "explanation": "这里应该用〈遵守〉。“出卖”的对象是原则、利益或财物，交通规则不能被出卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”是无意的，与“为了升官”的有意目的相矛盾。"}, {"text": "出卖", "is_correct": true, "explanation": "正确：“出卖”指为私利损害他人，与“为了升官”的语境相符。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是人，不能以“利益”作宾语。"}, {"text": "辞去", "is_correct": false, "explanation": "搭配：“辞去”的对象是职务，不能说“辞去同事的利益”。"}], "explanations": {"忘记": "语义：“忘记”是无意的，与“为了升官”的有意目的相矛盾。", "出卖": "正确：“出卖”指为私利损害他人，与“为了升官”的语境相符。", "感谢": "搭配：“感谢”的对象是人，不能以“利益”作宾语。", "辞去": "搭配：“辞去”的对象是职务，不能说“辞去同事的利益”。"}, "sentence_index": 6, "correct_answer": "出卖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把全部积蓄出卖到了股市。", "explanation": "这里应该用〈投资〉。“出卖”指为私利背弃原则或利益、损害他人，不能表示把钱投入某处。"}, {"text": "他用文字出卖了对老师的感谢。", "explanation": "这里应该用〈表达〉。“出卖”的对象是原则、良心或利益，不能用于表达谢意。"}, {"text": "他愿意和朋友出卖快乐。", "explanation": "这里应该用〈分享〉。“出卖”含有为私利损害他人的意思，不能用于与朋友共享快乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾经把同伴出卖了别人。", "corrected_sentence": "他曾经把同伴出卖给了别人。", "error_description": "错误：“出卖”带接受者时，后面要用“给”引出对象，应说“出卖给了别人”。正确：“他曾经把同伴出卖给了别人。”缺少“给”，句子变成“出卖了别人”，意思不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来不出卖过良心。", "corrected_sentence": "他从来没出卖过良心。", "error_description": "错误：“不”用错了。表示没有发生过的经历应该用“没”，应说“从来没出卖过良心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04590a8f-801b-4c4a-a088-7fc155ca210b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
