INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95653, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让它变得更大、更多。", "primary_collocate": null, "pronunciation": "jiā dà", "ipa": "tɕja˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "政府决定加大对学校的投入。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年加大了宣传力度。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要加大锻炼的力度。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师加大了作业量。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了赢比赛，球队加大了训练量。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想加大对学生的帮助。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把每天的运动量加大了。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里加大了对环境的保护力度。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店加大了广告的数量。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们加大过对这个项目的投资。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加大了", "label": "完成体"}, {"form": "加大过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "有意增加力度、投入、数量，让它更多更强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a21a23-df6a-4cf9-ac6b-c8fd9560ff2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95653, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加大", "is_correct": true, "explanation": "正确：“政府决定加大对学校的投入”，表示有意增加投入，与句意相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”无法作用于“投入”，句子不成立。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“投入”不能被“唱”，两者不搭配。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“投入”不能被“煮”，两者不搭配。"}], "explanations": {"加大": "正确：“政府决定加大对学校的投入”，表示有意增加投入，与句意相符。", "散步": "语义：“散步”无法作用于“投入”，句子不成立。", "唱": "搭配：“投入”不能被“唱”，两者不搭配。", "煮": "搭配：“投入”不能被“煮”，两者不搭配。"}, "sentence_index": 0, "correct_answer": "加大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重加大了三公斤。", "explanation": "这里应该用〈增加〉。“加大”多用于力度、投入、数量的有意提高，体重的自然增长要说“增加”。"}, {"text": "他的心跳加大了。", "explanation": "这里应该用〈加快〉。心跳的变化说“加快”，“加大”指尺寸、力度、数量的扩大，不用于心跳。"}, {"text": "会议加大了一个小时。", "explanation": "这里应该用〈延长〉。“加大”指力度、数量的增加，时间的拉长要说“延长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95653, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加大", "is_correct": true, "explanation": "正确：“把每天的运动量加大了”，表示运动量增加，与句意相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“运动量”不能被“洗”，两者不搭配。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“运动量”不能被“剪”，两者不搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“运动量”是抽象数量，不能被“吃”。"}], "explanations": {"加大": "正确：“把每天的运动量加大了”，表示运动量增加，与句意相符。", "洗": "搭配：“运动量”不能被“洗”，两者不搭配。", "剪": "搭配：“运动量”不能被“剪”，两者不搭配。", "吃": "语义：“运动量”是抽象数量，不能被“吃”。"}, "sentence_index": 6, "correct_answer": "加大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水位加大了。", "explanation": "这里应该用〈上涨〉。水位的升高说“上涨”，“加大”用于力度、投入、数量的增加，不用于水位。"}, {"text": "这座城市的温度加大了。", "explanation": "这里应该用〈升高〉。温度的上升说“升高”，“加大”不用于温度。"}, {"text": "他的免疫力加大了。", "explanation": "这里应该用〈增强〉。抵抗力、能力的提升用“增强”，“加大”指力度、投入、数量的增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明年政府将加大了对基础研究的投入。", "corrected_sentence": "明年政府将加大对基础研究的投入。", "error_description": "错误形式：“将加大了”；正确形式：“将加大”。“将”表示将来，动作尚未发生，不能与表示完成的“了”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司今年加大了过对研发的投入。", "corrected_sentence": "公司今年加大了对研发的投入。", "error_description": "错误形式：“加大了过”；正确形式：“加大了”。“了”与“过”都是动态助词，不能同时附在同一动词之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减小", "is_correct": true, "explanation": "正确：“减小”与“增大”互为反义，表示变小，与“难度加大”相对。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”表示维持原样，与“增大”不构成反义关系。"}, {"text": "移动", "is_correct": false, "explanation": "“移动”指位置变化，与表示程度变大的“增大”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指看和察看，与“增大”无反义关系。"}], "correct_answer": "减小", "explanations": {"减小": "正确：“减小”与“增大”互为反义，表示变小，与“难度加大”相对。", "保持": "“保持”表示维持原样，与“增大”不构成反义关系。", "移动": "“移动”指位置变化，与表示程度变大的“增大”没有反义关系。", "观察": "“观察”指看和察看，与“增大”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减小", "is_correct": true, "explanation": "正确：“减小”与“增大”互为反义，表示变小，与“压力加大”相对。"}, {"text": "擦", "is_correct": false, "explanation": "“擦”指摩擦、清除，与“增大”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指发出声音演唱，与“增大”没有反义关系。"}, {"text": "咬", "is_correct": false, "explanation": "“咬”指用牙齿嚼，与“增大”没有反义关系。"}], "correct_answer": "减小", "explanations": {"减小": "正确：“减小”与“增大”互为反义，表示变小，与“压力加大”相对。", "擦": "“擦”指摩擦、清除，与“增大”没有反义关系。", "唱": "“唱”指发出声音演唱，与“增大”没有反义关系。", "咬": "“咬”指用牙齿嚼，与“增大”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "增大；扩大。", "primary_collocate": null, "pronunciation": "jiā dà", "ipa": "tɕja˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "请把电视的声音加大一点。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太小，要加大一号。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，路上的危险加大了。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的难度今年加大了。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "穷人和富人的差距在加大。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想把店面加大一些。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风加大了，我们回家吧。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机加大油门，车开得更快了。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的面积加大了一倍。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作压力加大了，他睡得不好。", "target_word": "加大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加大了", "label": "完成体"}, {"form": "加大过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "尺寸、程度、声音、难度等变大或被扩大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a21a23-df6a-4cf9-ac6b-c8fd9560ff2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加大", "is_correct": true, "explanation": "正确：“请把电视的声音加大一点”，表示声音变大，与句意相符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“声音”不能被“擦”，两者不搭配。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“声音”不能被“穿”，两者不搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“声音”不能被“吃”，句子语义不通。"}], "explanations": {"加大": "正确：“请把电视的声音加大一点”，表示声音变大，与句意相符。", "擦": "搭配：“声音”不能被“擦”，两者不搭配。", "穿": "搭配：“声音”不能被“穿”，两者不搭配。", "吃": "语义：“声音”不能被“吃”，句子语义不通。"}, "sentence_index": 0, "correct_answer": "加大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的英语水平加大了。", "explanation": "这里应该用〈提升〉。能力、水平的提高要说“提升”，“加大”表示尺寸、程度的变大，不说水平加大。"}, {"text": "房间里的温度加大了。", "explanation": "这里应该用〈升高〉。温度变高要说“升高”，“加大”用于尺寸、程度、声音等的扩大，不说温度加大。"}, {"text": "这株树加大了。", "explanation": "这里应该用〈长高〉。树木的生长要说“长高”或“长大”，“加大”不用于树木长高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加大", "is_correct": true, "explanation": "正确：“风加大了，我们回家吧”，表示风力变大，与句意相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“风”不能“写”，句子语义不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“风”不能被“洗”，两者不搭配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“风”不能“咬”，句子语义不通。"}], "explanations": {"加大": "正确：“风加大了，我们回家吧”，表示风力变大，与句意相符。", "写": "语义：“风”不能“写”，句子语义不通。", "洗": "搭配：“风”不能被“洗”，两者不搭配。", "咬": "语义：“风”不能“咬”，句子语义不通。"}, "sentence_index": 6, "correct_answer": "加大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的体质加大了。", "explanation": "这里应该用〈增强〉。体质、抵抗力的提升用“增强”，“加大”表示尺寸、程度的变大，不说体质加大。"}, {"text": "这件衣服洗过以后，颜色加大了。", "explanation": "这里应该用〈加深〉。颜色变深要说“加深”，“加大”用于尺寸、程度、声音、难度等的扩大，不用于颜色。"}, {"text": "他的成绩加大了。", "explanation": "这里应该用〈提高〉。成绩的提升要说“提高”，“加大”不用于成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明年这条路的宽度将加大了一倍。", "corrected_sentence": "明年这条路的宽度将加大一倍。", "error_description": "错误形式：“将加大了一倍”；正确形式：“将加大一倍”。“将”表示将来，动作尚未发生，不能与表示完成的“了”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午风势加大很厉害。", "corrected_sentence": "下午风势加大得很厉害。", "error_description": "错误形式：“加大很厉害”；正确形式：“加大得很厉害”。表示程度的补语要用“得”接在动词之后，漏掉“得”则句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48d401d5-0fd2-43a5-8297-a17638e858c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
