INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95655, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠出力气做工挣钱的人。", "primary_collocate": null, "pronunciation": "láo gōng", "ipa": "lau˧˥ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这些劳工每天在工地上搬砖。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲年轻时是一名劳工，靠力气养家。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳工们从早忙到晚，只为多挣一点钱。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板给每个劳工发了工钱。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "码头上有很多劳工在卸货。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老劳工的手上全是茧。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家工厂又招了二十名劳工。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，当年他是靠力气吃饭的劳工。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳工们干完活，坐在路边休息。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为缺钱，他去城里当了劳工。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "外籍劳工", "label": "复合"}, {"form": "勞工", "label": "繁体"}], "register": "中性", "sense_fingerprint": "靠出力气做工挣钱的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae03713-7b77-404a-928c-a57fedb969c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95655, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "劳工", "is_correct": true, "explanation": "正确：“劳工”指靠出力气做工挣钱的人，符合“在工地上搬砖”的语境。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生不在工地上搬砖，与句中的劳动内容矛盾。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手的职业与工地搬砖无关，句意不通。"}, {"text": "学者", "is_correct": false, "explanation": "语义：学者是从事学术研究的人，不在工地上搬砖，句意不通。"}], "explanations": {"劳工": "正确：“劳工”指靠出力气做工挣钱的人，符合“在工地上搬砖”的语境。", "医生": "语义：医生不在工地上搬砖，与句中的劳动内容矛盾。", "歌手": "语义：歌手的职业与工地搬砖无关，句意不通。", "学者": "语义：学者是从事学术研究的人，不在工地上搬砖，句意不通。"}, "sentence_index": 0, "correct_answer": "劳工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "办公室里的劳工都在电脑前处理文件。", "explanation": "这里应该用〈员工〉。劳工指靠体力劳动挣钱的人，在办公室做文职工作的人要用员工。"}, {"text": "图书馆的劳工都很有礼貌。", "explanation": "这里应该用〈职员〉。劳工指靠体力劳动挣钱的人，图书馆的工作人员要用职员。"}, {"text": "那家商店的劳工在柜台后面给顾客开发票。", "explanation": "这里应该用〈收银员〉。劳工指靠体力劳动挣钱的人，在柜台开票收款的人要用收银员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "劳工", "is_correct": true, "explanation": "正确：“招……名劳工”指招收做工的人员，符合工厂招人的语境。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是乘车的人，工厂不会招乘客。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是外出旅行的人，与工厂招人的语境不符。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“招”指招聘、招收人员，不能说“招病人”。"}], "explanations": {"劳工": "正确：“招……名劳工”指招收做工的人员，符合工厂招人的语境。", "乘客": "语义：乘客是乘车的人，工厂不会招乘客。", "游客": "语义：游客是外出旅行的人，与工厂招人的语境不符。", "病人": "搭配：“招”指招聘、招收人员，不能说“招病人”。"}, "sentence_index": 6, "correct_answer": "劳工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名大学里的劳工，专门给学生讲课。", "explanation": "这里应该用〈教师〉。劳工指靠体力劳动挣钱的人，在大学里给学生讲课的人要用教师。"}, {"text": "这位劳工正在医院里给病人治病。", "explanation": "这里应该用〈医生〉。劳工指靠体力劳动挣钱的人，给病人治病的人要用医生。"}, {"text": "这位劳工在舞台上唱了一首歌。", "explanation": "这里应该用〈歌手〉。劳工指靠体力劳动挣钱的人，在舞台上唱歌的人要用歌手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他手下有一名劳工们。", "corrected_sentence": "他手下有一名劳工。", "error_description": "错误：“一名”是单数量词，“劳工”后不能加“们”表示复数，应说“一名劳工”。“们”不能与“一名”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工地上来了一点劳工。", "corrected_sentence": "工地上来了一些劳工。", "error_description": "错误：“一点”只用于修饰不可数或笼统的量，“劳工”是可数的人，应说“一些劳工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
