INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "靠体力劳动换取报酬的工人。", "primary_collocate": null, "pronunciation": "láo gōng", "ipa": "lau˧˥ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这家公司雇了很多外地劳工。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳工的工资按天算。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在建筑队做劳工，一个月挣四千块。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些劳工住在工地旁边的房子里。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修路的劳工们都戴着黄帽子。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王是个勤快的劳工。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要保护劳工的权利。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太热，劳工中午要休息两小时。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的丈夫是矿山上的劳工。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳工们盼着月底发工资。", "target_word": "劳工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "外籍劳工", "label": "复合"}, {"form": "勞工", "label": "繁体"}], "register": "中性", "sense_fingerprint": "靠体力劳动换取报酬的工人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae03713-7b77-404a-928c-a57fedb969c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "劳工", "is_correct": true, "explanation": "正确：“雇”的对象是为公司做体力活的工人，“劳工”符合语境。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客不会被公司雇用，句意矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“雇”用于雇用人员，不能说“雇病人”。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”指偷东西的人，不是被雇来做工的对象，句意不通。"}], "explanations": {"劳工": "正确：“雇”的对象是为公司做体力活的工人，“劳工”符合语境。", "乘客": "语义：乘客不会被公司雇用，句意矛盾。", "病人": "搭配：“雇”用于雇用人员，不能说“雇病人”。", "小偷": "语义：“小偷”指偷东西的人，不是被雇来做工的对象，句意不通。"}, "sentence_index": 0, "correct_answer": "劳工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在银行当了十年劳工，每天穿着西装。", "explanation": "这里应该用〈职员〉。劳工指靠体力劳动挣钱的人，银行里从事办公的人员要用职员。"}, {"text": "我们公司的劳工都在办公室里用电脑工作。", "explanation": "这里应该用〈员工〉。劳工指靠体力劳动挣钱的人，在办公室用电脑工作的公司人员要用员工。"}, {"text": "这家餐厅的劳工在大厅里给客人点菜。", "explanation": "这里应该用〈服务员〉。劳工指靠体力劳动挣钱的人，在大厅给客人点菜的人要用服务员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "劳工", "is_correct": true, "explanation": "正确：“劳工”指靠体力劳动换取报酬的工人，其权利可以受到保护。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是外出旅行的人，“保护游客的权利”与劳动、报酬的语境无关，此处讲的是做工者的权利。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是权利的主体，句意荒谬。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是权利的主体，不能说保护它的权利。"}], "explanations": {"劳工": "正确：“劳工”指靠体力劳动换取报酬的工人，其权利可以受到保护。", "游客": "语义：游客是外出旅行的人，“保护游客的权利”与劳动、报酬的语境无关，此处讲的是做工者的权利。", "电脑": "语义：电脑不是权利的主体，句意荒谬。", "桌子": "语义：桌子不是权利的主体，不能说保护它的权利。"}, "sentence_index": 6, "correct_answer": "劳工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名优秀的劳工，经常在法庭上为客户辩护。", "explanation": "这里应该用〈律师〉。劳工指靠体力劳动挣钱的人，在法庭上为客户辩护的人要用律师。"}, {"text": "这位劳工正在实验室里研究新药。", "explanation": "这里应该用〈科学家〉。劳工指靠体力劳动挣钱的人，在实验室研究新药的人要用科学家。"}, {"text": "这位劳工正在话剧里扮演主角。", "explanation": "这里应该用〈演员〉。劳工指靠体力劳动挣钱的人，在话剧里扮演角色的人要用演员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里来了一名外出的劳工们。", "corrected_sentence": "村里来了一名外出的劳工。", "error_description": "错误：“一名”是单数量词，“劳工”后不能加“们”表示复数，应说“一名外出的劳工”。“们”不能与“一名”同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车间里有一点劳工在加班。", "corrected_sentence": "车间里有一些劳工在加班。", "error_description": "错误：“一点”只用于不可数或笼统的量，“劳工”是可数的人，应说“一些劳工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
