INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不让社会向前走，往后拖的。", "primary_collocate": null, "pronunciation": "fǎn dòng", "ipa": "fan˨˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种做法很反动，会让社会变得落后。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个反动的政府不让人民过好日子。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的政策太反动，只想把国家往后拖。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，反动的人总是挡着社会前进。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些反动的规定让大家没法往前走。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反动的力量阻挡不了时代前进。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的文章很反动，想让社会回到过去。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些反动的人不愿看到社会进步。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那个时代，反动的统治者拖住了国家的发展。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划让社会倒退，真是太反动了。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反动派", "label": "复合"}, {"form": "反动分子", "label": "复合"}, {"form": "反動", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "阻碍社会前进、把社会往后拖的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bf5a98-c423-433d-921e-c8cc89de37cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反动", "is_correct": true, "explanation": "正确。“很反动”形容做法阻碍社会进步，与后半句“让社会变得落后”一致。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容态度主动亲切，与“让社会变得落后”的后果相矛盾，句意不通。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”指好看，不能说明做法“让社会变得落后”，句意不通。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来修饰“做法”。"}], "explanations": {"反动": "正确。“很反动”形容做法阻碍社会进步，与后半句“让社会变得落后”一致。", "热情": "语义：“热情”形容态度主动亲切，与“让社会变得落后”的后果相矛盾，句意不通。", "美丽": "语义：“美丽”指好看，不能说明做法“让社会变得落后”，句意不通。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来修饰“做法”。"}, "sentence_index": 0, "correct_answer": "反动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做事很反动，从来不冒险。", "explanation": "这里应该用〈保守〉。反动指阻碍社会前进的，只是做事谨慎，应该说〈保守〉。"}, {"text": "这个地区的交通很反动，需要修路。", "explanation": "这里应该用〈落后〉。反动说的是阻碍社会前进的人或事，交通条件差应说〈落后〉。"}, {"text": "这盏灯很反动，夜里特别亮。", "explanation": "这里应该用〈明亮〉。反动指阻碍社会进步的人或事，灯亮应说〈明亮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反动", "is_correct": true, "explanation": "正确。“想让社会回到过去”说明文章是阻碍社会进步的，只有“反动”符合。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型或形象，不能用来形容“文章”，句意荒谬。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：“冰凉”形容温度低，不能用来形容“文章”，句意荒谬。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能用来形容“文章”，句意荒谬。"}], "explanations": {"反动": "正确。“想让社会回到过去”说明文章是阻碍社会进步的，只有“反动”符合。", "高大": "搭配：“高大”形容体型或形象，不能用来形容“文章”，句意荒谬。", "冰凉": "语义：“冰凉”形容温度低，不能用来形容“文章”，句意荒谬。", "咸": "语义：“咸”形容味道，不能用来形容“文章”，句意荒谬。"}, "sentence_index": 6, "correct_answer": "反动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的秩序很反动，需要整顿。", "explanation": "这里应该用〈混乱〉。反动说的是阻碍社会进步的人或事，秩序乱应说〈混乱〉。"}, {"text": "这些设备很反动，该换新的了。", "explanation": "这里应该用〈陈旧〉。反动指阻碍社会前进的，设备旧应说〈陈旧〉。"}, {"text": "这个孩子很反动，喜欢捣乱。", "explanation": "这里应该用〈顽皮〉。反动用于阻碍社会进步的人或事，孩子爱玩闹应说〈顽皮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个政府是反动，阻碍了国家的发展。", "corrected_sentence": "那个政府是反动的，阻碍了国家的发展。", "error_description": "错误：“是反动”。正确：“是反动的”。“反动”是形容词，作谓语时后面要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个做法真是太反动着。", "corrected_sentence": "这个做法真是太反动了。", "error_description": "错误：“太反动着”。正确：“太反动了”。“着”表示持续的状态，这里说的是已经形成的判断，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
