INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "思想、行为上维护落后、反对进步的。", "primary_collocate": null, "pronunciation": "fǎn dòng", "ipa": "fan˨˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的思想很反动，反对一切新东西。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反动的观点只想维护落后的旧习惯。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人的行为很反动，总是反对改革。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的想法太反动，不让工人学新技术。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话很反动，大家都不同意。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他反对女孩上学，这种思想非常反动。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在会上，他提出了一个反动的看法。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反对新办法，只想守着旧规矩，这很反动。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的做法很反动，总是压着新想法。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容反动，因为它反对一切进步。", "target_word": "反动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反动派", "label": "复合"}, {"form": "反动分子", "label": "复合"}, {"form": "反動", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "思想行为上守旧落后、反对进步的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6bf5a98-c423-433d-921e-c8cc89de37cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反动", "is_correct": true, "explanation": "正确。“思想很反动”指思想守旧、反对进步，与“反对一切新东西”一致。"}, {"text": "先进", "is_correct": false, "explanation": "语义：“先进”指思想超前，与“反对一切新东西”的意思矛盾。"}, {"text": "灵活", "is_correct": false, "explanation": "语义：“灵活”指善于变通，与“反对一切新东西”的意思矛盾。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”形容好看，与“反对一切新东西”的守旧态度矛盾。"}], "explanations": {"反动": "正确。“思想很反动”指思想守旧、反对进步，与“反对一切新东西”一致。", "先进": "语义：“先进”指思想超前，与“反对一切新东西”的意思矛盾。", "灵活": "语义：“灵活”指善于变通，与“反对一切新东西”的意思矛盾。", "美丽": "语义：“美丽”形容好看，与“反对一切新东西”的守旧态度矛盾。"}, "sentence_index": 0, "correct_answer": "反动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很反动，每天都按时上班。", "explanation": "这里应该用〈认真〉。反动指思想行为维护落后、反对进步，按时上班应说〈认真〉。"}, {"text": "他对同事很反动，从不关心别人。", "explanation": "这里应该用〈冷漠〉。反动指维护落后、反对进步，对同事漠不关心应说〈冷漠〉。"}, {"text": "他作风很反动，喜欢独断。", "explanation": "这里应该用〈专横〉。反动是对进步事物的态度，作风霸道应说〈专横〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反动", "is_correct": true, "explanation": "正确。“反动的看法”指守旧、反对进步的观点，符合句意。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气或物体含水多，不能用来修饰“看法”，句意荒谬。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型或形象，不能用来修饰“看法”。"}, {"text": "善良", "is_correct": false, "explanation": "语义：“善良”形容人的品性，与“看法”的内容无关，句意不通。"}], "explanations": {"反动": "正确。“反动的看法”指守旧、反对进步的观点，符合句意。", "潮湿": "搭配：“潮湿”形容空气或物体含水多，不能用来修饰“看法”，句意荒谬。", "高大": "搭配：“高大”形容体型或形象，不能用来修饰“看法”。", "善良": "语义：“善良”形容人的品性，与“看法”的内容无关，句意不通。"}, "sentence_index": 6, "correct_answer": "反动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他性格很反动，从不认输。", "explanation": "这里应该用〈倔强〉。反动说的是思想上反对进步，性格硬、不服输应说〈倔强〉。"}, {"text": "他说话的语气很反动，动不动就发火。", "explanation": "这里应该用〈暴躁〉。反动说的是思想、行为维护落后，说话语气急躁应说〈暴躁〉。"}, {"text": "这种款式已经反动了，没人穿了。", "explanation": "这里应该用〈过时〉。反动指阻碍进步的思想或行为，款式旧了应说〈过时〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的想法变很反动，总是拒绝新事物。", "corrected_sentence": "他的想法变得很反动，总是拒绝新事物。", "error_description": "错误：“变很反动”。正确：“变得很反动”。“变”后面接形容词作补语时，中间要加“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的思想越来越反动着，真可惜。", "corrected_sentence": "他的思想越来越反动了，真可惜。", "error_description": "错误：“越来越反动着”。正确：“越来越反动了”。“着”表示持续的状态，这里说的是已经发生的变化，要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fea0e27d-91ca-48a0-ae27-68f2b4c19901') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
