INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95661, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个东西里面某样东西占了多少。", "primary_collocate": null, "pronunciation": "hán liàng", "ipa": "xan˧˥ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种牛奶的蛋白质含量很高。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果里的糖含量不一样。", "target_word": "含量", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这包薯片的盐含量太高了。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "标签上标明了脂肪含量。", "target_word": "含量", "complexity_tier": "T3", "furigana": "biāo qiān shàng biāo míng le zhī fáng hán liàng.", "sentence_source": "generated"}, {"text": "菠菜的铁含量比白菜高。", "target_word": "含量", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈买饮料时，先看糖的含量。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种面包的水分含量很少，放很久也不会坏。", "target_word": "含量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上别喝咖啡因含量高的茶。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "橙汁的维生素含量比苹果汁高。", "target_word": "含量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想知道这块蛋糕的脂肪含量是多少。", "target_word": "含量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "食物或日常物品里某种成分占多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82cc745d-1222-4f0a-989c-21513a148a9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "含量", "is_correct": true, "explanation": "正确：“含量”指物质中某种成分的多少，与“蛋白质”搭配自然。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能用“很高”来形容，“蛋白质味道很高”说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：蛋白质没有年龄，“蛋白质年龄很高”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不说“很高”，应说“很深”或“很浅”。"}], "explanations": {"含量": "正确：“含量”指物质中某种成分的多少，与“蛋白质”搭配自然。", "味道": "搭配：“味道”不能用“很高”来形容，“蛋白质味道很高”说不通。", "年龄": "语义：蛋白质没有年龄，“蛋白质年龄很高”说不通。", "颜色": "搭配：“颜色”不说“很高”，应说“很深”或“很浅”。"}, "sentence_index": 0, "correct_answer": "含量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班女生的含量很高。", "explanation": "这里应该用〈比例〉。含量指物质里某种成分的多少，人群在整体中的占比要用“比例”。"}, {"text": "我们学校的学生含量很多。", "explanation": "这里应该用〈数量〉。含量只用于物质中的成分，学生的多少要说“数量”。"}, {"text": "这杯橙汁的含量很浓，别再加水了。", "explanation": "这里应该用〈浓度〉。含量指某种成分的多少，溶液的浓淡要说“浓度”，不能用“含量很浓”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350f2f16-9181-4dea-b588-0b385c893b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "含量", "is_correct": true, "explanation": "正确：“水分含量”是常用搭配，“很少”描述的是含量。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能用“很少”来形容，“水分温度很少”说不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：面包的水分没有性格，“水分性格很少”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：水分没有名字，“水分名字”不成立，句子说不通。"}], "explanations": {"含量": "正确：“水分含量”是常用搭配，“很少”描述的是含量。", "温度": "搭配：“温度”不能用“很少”来形容，“水分温度很少”说不通。", "性格": "语义：面包的水分没有性格，“水分性格很少”说不通。", "名字": "语义：水分没有名字，“水分名字”不成立，句子说不通。"}, "sentence_index": 6, "correct_answer": "含量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的含量很足，够我们四个人吃。", "explanation": "这里应该用〈分量〉。含量指成分的多少，蛋糕够几个人吃的份量要说“分量”。"}, {"text": "这个气球的含量很大。", "explanation": "这里应该用〈体积〉。含量指成分的量，气球占空间的大小要说“体积”。"}, {"text": "这款手机的含量很好，全国都有人买。", "explanation": "这里应该用〈销量〉。含量指成分的多少，商品卖出的数量要说“销量”，不能用“含量很好”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350f2f16-9181-4dea-b588-0b385c893b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种饮料的糖含量很比较低。", "corrected_sentence": "这种饮料的糖含量比较低。", "error_description": "程度副词叠用：“比较”与“很”不能同时修饰“低”，应去掉“很”，说“糖含量比较低”。错误出在“比较低”前多加的“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350f2f16-9181-4dea-b588-0b385c893b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种饼干的水分含量比较很低。", "corrected_sentence": "这种饼干的水分含量很低。", "error_description": "程度副词叠用：“比较”和“很”不能同时修饰“低”，应只用“很”，说“水分含量很低”。错误出在“很低”前多加的“比较”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350f2f16-9181-4dea-b588-0b385c893b2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
