INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95663, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "口语，问方式或办法，相当于“怎么”。", "primary_collocate": null, "pronunciation": "zǎ", "ipa": "tsa˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个字咋写？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜咋做？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去火车站咋走？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机坏了，咋办？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器咋用？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词咋读？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说，这件事咋弄才好？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是找不到他，咱们咋办？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题咋解？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的票咋买？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "咋样", "label": "复合"}, {"form": "咋办", "label": "复合"}], "register": "口语", "sense_fingerprint": "口语里问方式、办法，相当于“怎么”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95663, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "咋", "is_correct": true, "explanation": "正确。咋 zǎ 表示“怎么”，与听到的读音一致。"}, {"text": "早", "is_correct": false, "explanation": "zǎo 与 zǎ 韵母不同（多了 o），意思是“早晨”。"}, {"text": "杂", "is_correct": false, "explanation": "zá（第二声）与 zǎ（第三声）声调不同，意思是“杂乱、杂物”。"}, {"text": "攒", "is_correct": false, "explanation": "zǎn 与 zǎ 仅多一个韵尾 n，声调相同，意思是“积攒、聚集”。"}, {"text": "崽", "is_correct": false, "explanation": "zǎi 与 zǎ 仅韵母多一个 i，声调相同，意思是“幼小的动物或孩子”。"}], "explanations": {"咋": "正确。咋 zǎ 表示“怎么”，与听到的读音一致。", "早": "zǎo 与 zǎ 韵母不同（多了 o），意思是“早晨”。", "杂": "zá（第二声）与 zǎ（第三声）声调不同，意思是“杂乱、杂物”。", "攒": "zǎn 与 zǎ 仅多一个韵尾 n，声调相同，意思是“积攒、聚集”。", "崽": "zǎi 与 zǎ 仅韵母多一个 i，声调相同，意思是“幼小的动物或孩子”。"}, "sentence_index": null, "correct_answer": "咋"}, "level_3": {"options": [{"text": "咋", "is_correct": true, "explanation": "正确。“这个字咋写”问写字的方法，与句意相合。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，句子问的是写法，不问在哪里写。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”问选哪一个，与问写字的方法不合。"}, {"text": "几时", "is_correct": false, "explanation": "语义：“几时”问时间，句子问的是写法，不合。"}], "explanations": {"咋": "正确。“这个字咋写”问写字的方法，与句意相合。", "哪儿": "语义：“哪儿”问地点，句子问的是写法，不问在哪里写。", "哪个": "语义：“哪个”问选哪一个，与问写字的方法不合。", "几时": "语义：“几时”问时间，句子问的是写法，不合。"}, "sentence_index": 0, "correct_answer": "咋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画咋一看，像是普通的照片。", "explanation": "这里应该用〈乍〉。“乍一看”指初次见到的一瞬间，应写作“乍”，不能用“咋”表示此义。"}, {"text": "他咋突然辞职了？", "explanation": "这里的“咋”表示“为什么”，问原因，不是问办法，与本义项不符。"}, {"text": "这么热的天，他咋穿着外套？", "explanation": "这里的“咋”表示“为什么”，问原因，不是问办法，与本义项不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95663, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "咋", "is_correct": true, "explanation": "正确。咋 zǎ 表示“怎么”，与听到的读音一致。"}, {"text": "咂", "is_correct": false, "explanation": "zā 与 zǎ 仅声调不同（第一声），意思是“吮吸、品味”。"}, {"text": "砸", "is_correct": false, "explanation": "zá（第二声）与 zǎ 声调不同，意思是“用力打击”。"}, {"text": "匝", "is_correct": false, "explanation": "zā 与 zǎ 仅声调不同（第一声），意思是“周、圈”。"}], "explanations": {"咋": "正确。咋 zǎ 表示“怎么”，与听到的读音一致。", "咂": "zā 与 zǎ 仅声调不同（第一声），意思是“吮吸、品味”。", "砸": "zá（第二声）与 zǎ 声调不同，意思是“用力打击”。", "匝": "zā 与 zǎ 仅声调不同（第一声），意思是“周、圈”。"}, "sentence_index": null, "correct_answer": "咋"}, "level_3": {"options": [{"text": "咋", "is_correct": true, "explanation": "正确。“这件事咋弄才好”问办法，与句意相合。"}, {"text": "为什么", "is_correct": false, "explanation": "语义：“为什么”问原因，句子问的是办法，“弄才好”与之不合。"}, {"text": "几时", "is_correct": false, "explanation": "语义：“几时”问时间，“弄才好”问办法，句意不合。"}, {"text": "为何", "is_correct": false, "explanation": "语义：“为何”问原因，与“弄才好”的办法义不合。"}], "explanations": {"咋": "正确。“这件事咋弄才好”问办法，与句意相合。", "为什么": "语义：“为什么”问原因，句子问的是办法，“弄才好”与之不合。", "几时": "语义：“几时”问时间，“弄才好”问办法，句意不合。", "为何": "语义：“为何”问原因，与“弄才好”的办法义不合。"}, "sentence_index": 6, "correct_answer": "咋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他咋一直不说话？", "explanation": "这里的“咋”表示“为什么”，问原因，不是问办法。"}, {"text": "他咋这么早就走了？", "explanation": "这里的“咋”表示“为什么”，问原因，不是问办法，与本义项不符。"}, {"text": "这孩子咋不吃早饭？", "explanation": "这里的“咋”表示“为什么”，问原因，不是问办法，与本义项不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道菜做咋才好吃？", "corrected_sentence": "这道菜咋做才好吃？", "error_description": "“咋”修饰动词时要放在动词前，应说“咋做”，不说“做咋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张演出票咋的买？", "corrected_sentence": "这张演出票咋买？", "error_description": "“咋”后直接接动词“买”，不加“的”。“咋的”是另一用法（表示“怎么回事”），这里应说“咋买”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
