INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95664, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "方言，怎么；为什么。", "primary_collocate": null, "pronunciation": "zǎ", "ipa": "tsa˨˩˦", "syllable_count": 1, "sentences": [{"text": "你咋不吃饭？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他咋还没来？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你咋哭了？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天都黑了，你咋才回来？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你咋知道这件事？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，你咋还不睡？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他咋又迟到了？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你咋不早说？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天你咋没去上班？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你咋这么高兴？", "target_word": "咋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "咋样", "label": "复合"}], "register": "口语", "sense_fingerprint": "方言里问原因，相当于“为什么、怎么会”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "咋", "is_correct": true, "explanation": "正确。咋 zǎ 表示“为什么”，与听到的读音一致。"}, {"text": "早", "is_correct": false, "explanation": "zǎo 与 zǎ 韵母不同（多了 o），意思是“早晨”。"}, {"text": "攒", "is_correct": false, "explanation": "zǎn 与 zǎ 仅多一个韵尾 n，声调相同，意思是“积攒、聚集”。"}, {"text": "砸", "is_correct": false, "explanation": "zá（第二声）与 zǎ 声调不同，意思是“用力打”。"}, {"text": "崽", "is_correct": false, "explanation": "zǎi 与 zǎ 仅韵母多一个 i，声调相同，意思是“幼小的动物或孩子”。"}], "explanations": {"咋": "正确。咋 zǎ 表示“为什么”，与听到的读音一致。", "早": "zǎo 与 zǎ 韵母不同（多了 o），意思是“早晨”。", "攒": "zǎn 与 zǎ 仅多一个韵尾 n，声调相同，意思是“积攒、聚集”。", "砸": "zá（第二声）与 zǎ 声调不同，意思是“用力打”。", "崽": "zǎi 与 zǎ 仅韵母多一个 i，声调相同，意思是“幼小的动物或孩子”。"}, "sentence_index": null, "correct_answer": "咋"}, "level_3": {"options": [{"text": "咋", "is_correct": true, "explanation": "正确。“你咋不吃饭”问原因，与句意相合。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，句子问的是原因，不合。"}, {"text": "谁", "is_correct": false, "explanation": "搭配：“谁”不能修饰“不吃饭”作状语，“你谁不吃饭”不成立。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样”问方式，句子问的是原因，句意不合。"}], "explanations": {"咋": "正确。“你咋不吃饭”问原因，与句意相合。", "哪儿": "语义：“哪儿”问地点，句子问的是原因，不合。", "谁": "搭配：“谁”不能修饰“不吃饭”作状语，“你谁不吃饭”不成立。", "怎样": "语义：“怎样”问方式，句子问的是原因，句意不合。"}, "sentence_index": 0, "correct_answer": "咋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人咋一看，挺年轻的。", "explanation": "这里应该用〈乍〉。“乍一看”指初次见到的一瞬间，应写作“乍”，不能用“咋”表示此义。"}, {"text": "他咋未到场？", "explanation": "这里应该用〈为什么〉。“咋”是口语词，不宜与“未”这类书面词搭配，应说“为什么没到场”。"}, {"text": "这份文件咋撰写？", "explanation": "这句的“咋”问办法，与“为什么”义不同；而且口语词“咋”与书面的“撰写”风格不协调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95664, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "咋", "is_correct": true, "explanation": "正确。咋 zǎ 表示“为什么”，与听到的读音一致。"}, {"text": "咂", "is_correct": false, "explanation": "zā 与 zǎ 仅声调不同（第一声），意思是“吮吸、品味”。"}, {"text": "匝", "is_correct": false, "explanation": "zā 与 zǎ 仅声调不同（第一声），意思是“周、圈”。"}, {"text": "杂", "is_correct": false, "explanation": "zá（第二声）与 zǎ（第三声）声调不同，意思是“杂乱”。"}], "explanations": {"咋": "正确。咋 zǎ 表示“为什么”，与听到的读音一致。", "咂": "zā 与 zǎ 仅声调不同（第一声），意思是“吮吸、品味”。", "匝": "zā 与 zǎ 仅声调不同（第一声），意思是“周、圈”。", "杂": "zá（第二声）与 zǎ（第三声）声调不同，意思是“杂乱”。"}, "sentence_index": null, "correct_answer": "咋"}, "level_3": {"options": [{"text": "咋", "is_correct": true, "explanation": "正确。“他咋又迟到了”问原因，与句意相合。"}, {"text": "如此", "is_correct": false, "explanation": "语法：“如此”表示程度或方式，不是疑问词，不能问原因，“他如此又迟到了？”不成立。"}, {"text": "这么", "is_correct": false, "explanation": "语义：“这么”表示程度或状态，不表示原因，句意不合。"}, {"text": "那样", "is_correct": false, "explanation": "语义：“那样”指方式，不指原因，“他那样又迟到了”句意不通。"}], "explanations": {"咋": "正确。“他咋又迟到了”问原因，与句意相合。", "如此": "语法：“如此”表示程度或方式，不是疑问词，不能问原因，“他如此又迟到了？”不成立。", "这么": "语义：“这么”表示程度或状态，不表示原因，句意不合。", "那样": "语义：“那样”指方式，不指原因，“他那样又迟到了”句意不通。"}, "sentence_index": 6, "correct_answer": "咋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件咋下载？", "explanation": "这句的“咋”问办法，不问原因，与本词条“为什么”的义项不符。"}, {"text": "这批货咋未能运到？", "explanation": "这里应该用〈为什么〉。“咋”是口语词，与“未能”这类书面语混用不当。"}, {"text": "您咋不前来参加会议？", "explanation": "这里应该用〈为什么〉。“咋”与“前来”的书面风格不一致，应说“为什么不前来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95664, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你还咋没写完作业？", "corrected_sentence": "你咋还没写完作业？", "error_description": "“咋”作状语时应放在副词“还”之前，说“咋还没”，不说“还咋没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95664, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你咋没不接电话？", "corrected_sentence": "你咋不接电话？", "error_description": "“没”与“不”同时否定，形成重复否定，应只用“不”，说“你咋不接电话”，不说“你咋没不接电话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
