INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95665, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市里房子多、人多的那一块。", "primary_collocate": null, "pronunciation": "chéng qū", "ipa": "ʈʂʰɤŋ˧˥ tɕʰy˥˥", "syllable_count": 2, "sentences": [{"text": "我住在城区，不住在乡下。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区的公园里有很多人。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县的城区不大。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区里的房子一个挨着一个。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区的学校比村里多。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去城区买东西。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区晚上很亮，到处都是灯。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区的店开到很晚。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天坐车到城区上班。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区的楼越盖越高。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老城区", "label": "复合"}, {"form": "新城区", "label": "复合"}], "register": "通用", "sense_fingerprint": "城市里房子多、人多的那一块地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95665, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海底", "is_correct": false, "explanation": "语义：海底无人居住，“住在海底”与“不住在乡下”的对比说不通。"}, {"text": "城区", "is_correct": true, "explanation": "正确：“住在城区”与“不住在乡下”相对，城区是房子多、人多的地方，符合句意。"}, {"text": "朋友", "is_correct": false, "explanation": "配价：“住在”后要接处所，“朋友”不是处所，不能作“住”的地点。"}, {"text": "太空", "is_correct": false, "explanation": "语义：太空不是人能长期居住的地方，与“不住在乡下”的对比不成立。"}], "explanations": {"海底": "语义：海底无人居住，“住在海底”与“不住在乡下”的对比说不通。", "城区": "正确：“住在城区”与“不住在乡下”相对，城区是房子多、人多的地方，符合句意。", "朋友": "配价：“住在”后要接处所，“朋友”不是处所，不能作“住”的地点。", "太空": "语义：太空不是人能长期居住的地方，与“不住在乡下”的对比不成立。"}, "sentence_index": 0, "correct_answer": "城区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们村子在城区，房子之间离得很远，院子很大。", "explanation": "这里应该用〈乡下〉。城区的房子挨得很近，房子之间离得远、院子大的是乡下。"}, {"text": "我们城区只有几户人家，四周全是稻田。", "explanation": "这里应该用〈乡村〉。城区是城市里房子多、人多的地方，只有几户人家、四周全是稻田的是乡村。"}, {"text": "我家的城区种满了玉米，秋天就收获了。", "explanation": "这里应该用〈农田〉。城区指城市里人口和建筑集中的区域，种满玉米、秋天收获的地方是农田。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "森林", "is_correct": false, "explanation": "语义：森林里通常不会到处都是灯，晚上也不会很亮。"}, {"text": "城区", "is_correct": true, "explanation": "正确：城区人口和建筑集中，晚上灯多，所以很亮，到处都是灯，符合句意。"}, {"text": "学生", "is_correct": false, "explanation": "配价：“很亮”说的是场所的状态，“学生”是人，不能作主语。"}, {"text": "深山", "is_correct": false, "explanation": "语义：深山人烟稀少，晚上到处都是灯说不通。"}], "explanations": {"森林": "语义：森林里通常不会到处都是灯，晚上也不会很亮。", "城区": "正确：城区人口和建筑集中，晚上灯多，所以很亮，到处都是灯，符合句意。", "学生": "配价：“很亮”说的是场所的状态，“学生”是人，不能作主语。", "深山": "语义：深山人烟稀少，晚上到处都是灯说不通。"}, "sentence_index": 6, "correct_answer": "城区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城区里养着几百头羊，每天要去放牧。", "explanation": "这里应该用〈牧场〉。城区是城市里人口和建筑集中的区域，养着几百头羊、需要放牧的地方是牧场。"}, {"text": "这个城区是一片山林，游客沿着步道上山，风景很美。", "explanation": "这里应该用〈景区〉。城区指城市里人口和建筑集中的区域，供游客沿步道游览的地方是景区。"}, {"text": "城区的人家很少，晚上一片漆黑。", "explanation": "这里应该用〈山村〉。城区人家密集，晚上不会一片漆黑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹城区读书。", "corrected_sentence": "我妹妹在城区读书。", "error_description": "错误形式：“城区读书”，地点“城区”前缺少介词“在”；正确形式：“在城区读书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我住在一条城区，离市中心很近。", "corrected_sentence": "我住在一个城区，离市中心很近。", "error_description": "错误形式：“一条城区”，“条”用于细长的东西，城区是一片地方，应用“个”；正确形式：“一个城区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
