INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市中人口和建筑集中的区域。", "primary_collocate": null, "pronunciation": "chéng qū", "ipa": "ʈʂʰɤŋ˧˥ tɕʰy˥˥", "syllable_count": 2, "sentences": [{"text": "城区的人口比郊区多。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的城区很大。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区里高楼很多。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区的房子比农村贵很多。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家住在城区，上班很方便。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区的路上车很多。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从城区到机场要一个小时。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区里人多，所以很热闹。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在城区开了一家小店。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城区的空气没有山里好。", "target_word": "城区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老城区", "label": "复合"}, {"form": "新城区", "label": "复合"}], "register": "通用", "sense_fingerprint": "城市里人口和建筑集中的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋上没有成片的居民，“人口比郊区多”说不通。"}, {"text": "城区", "is_correct": true, "explanation": "正确：“城区”指城市中人口和建筑集中的区域，与“郊区”相比人口更多，符合句意。"}, {"text": "山林", "is_correct": false, "explanation": "语义：山林人烟稀少，“人口比郊区多”说不通。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠人烟稀少，不可能人口比郊区多。"}], "explanations": {"海洋": "语义：海洋上没有成片的居民，“人口比郊区多”说不通。", "城区": "正确：“城区”指城市中人口和建筑集中的区域，与“郊区”相比人口更多，符合句意。", "山林": "语义：山林人烟稀少，“人口比郊区多”说不通。", "沙漠": "语义：沙漠人烟稀少，不可能人口比郊区多。"}, "sentence_index": 0, "correct_answer": "城区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我奶奶一辈子住在城区，每天种地养鸡。", "explanation": "这里应该用〈农村〉。城区指城市中人口和建筑集中的区域，种地养鸡的生活要在农村。"}, {"text": "我们学校的城区很大，有五个操场。", "explanation": "这里应该用〈校区〉。城区指城市里人口和建筑集中的区域，学校的范围要用校区，学校里不说城区。"}, {"text": "这座山的城区很高，山顶有雪。", "explanation": "这里应该用〈山区〉。城区指城市里人口和建筑集中的区域，山里一带的地方要用山区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢笔", "is_correct": false, "explanation": "语义：“从…到机场”的起点须是地点，“钢笔”不是地点，说不通。"}, {"text": "城区", "is_correct": true, "explanation": "正确：“从城区到机场”指从市区出发去机场，要一个小时，符合句意。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”不是地点，不能作“从…到机场”的起点。"}, {"text": "学生", "is_correct": false, "explanation": "配价：“学生”是人，不是地点，不能作“从…到机场”的起点。"}], "explanations": {"钢笔": "语义：“从…到机场”的起点须是地点，“钢笔”不是地点，说不通。", "城区": "正确：“从城区到机场”指从市区出发去机场，要一个小时，符合句意。", "雨伞": "语义：“雨伞”不是地点，不能作“从…到机场”的起点。", "学生": "配价：“学生”是人，不是地点，不能作“从…到机场”的起点。"}, "sentence_index": 6, "correct_answer": "城区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的城区很大，每天骑马放羊，草场一望无际。", "explanation": "这里应该用〈草原〉。城区指城市里人口和建筑集中的区域，骑马放羊、草场一望无际的地方是草原。"}, {"text": "这个城区全是沙子，一眼望去没有一棵树。", "explanation": "这里应该用〈沙漠〉。城区指城市里人口和建筑集中的区域，全是沙子、没有树的地方是沙漠。"}, {"text": "这个城区是一大片湖水，湖上有很多小船。", "explanation": "这里应该用〈湖区〉。城区指城市里人口和建筑集中的区域，一大片湖水、湖上有小船的地方是湖区。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈城区开了一家理发店。", "corrected_sentence": "我妈妈在城区开了一家理发店。", "error_description": "错误形式：“城区开了一家理发店”，地点“城区”前缺少介词“在”；正确形式：“在城区开了一家理发店”。表示动作发生的地点要用“在＋地点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在城区到郊区要半个小时。", "corrected_sentence": "从城区到郊区要半个小时。", "error_description": "错误形式：“在城区到郊区”，表示起点时介词应用“从”而不是“在”；正确形式：“从城区到郊区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
