INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95667, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "按照别人定好的事去做的那个人。", "primary_collocate": null, "pronunciation": "zhí xíng rén", "ipa": "ʈʂʅ˧˥ ɕiŋ˧˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他只是执行人，不能改计划。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计划是经理定的，我是执行人。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "执行人要按要求做事。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的执行人不会随便改办法。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的执行人是小王。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要一个执行人来做这件事。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个办法的执行人，不是想办法的人。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "执行人必须认真，不能马虎。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板定好了方法，执行人照着做就行。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做执行人很多年了，从不出错。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "照别人定好的计划、办法去做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95667, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总经理", "is_correct": false, "explanation": "语义：总经理有权决定计划，“只是总经理，不能改计划”与身份矛盾。"}, {"text": "执行人", "is_correct": true, "explanation": "正确：“只是执行人”说明他只负责做事，所以“不能改计划”，符合句意。"}, {"text": "决策者", "is_correct": false, "explanation": "语义：决策者有权决定计划，与“不能改计划”矛盾。"}, {"text": "首脑", "is_correct": false, "explanation": "语域：“首脑”是正式书面用语，口语中“只是首脑”很别扭，而且首脑通常有权改计划。"}], "explanations": {"总经理": "语义：总经理有权决定计划，“只是总经理，不能改计划”与身份矛盾。", "执行人": "正确：“只是执行人”说明他只负责做事，所以“不能改计划”，符合句意。", "决策者": "语义：决策者有权决定计划，与“不能改计划”矛盾。", "首脑": "语域：“首脑”是正式书面用语，口语中“只是首脑”很别扭，而且首脑通常有权改计划。"}, "sentence_index": 0, "correct_answer": "执行人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个活动的执行人是小李，他负责想出所有的好主意。", "explanation": "这里应该用〈策划人〉。执行人只按既定方案做事，不负责想主意。"}, {"text": "公司的执行人决定了这个计划，大家照着做。", "explanation": "这里应该用〈决策者〉。执行人只负责落实计划，不能决定计划。"}, {"text": "这起交通事故的执行人都受了伤。", "explanation": "这里应该用〈当事人〉。执行人是按别人定好的事去做的人，事故中的双方是当事人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95667, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发明者", "is_correct": false, "explanation": "语义：发明者就是想出办法的人，与“不是想办法的人”矛盾。"}, {"text": "设计者", "is_correct": false, "explanation": "语义：设计者负责构想办法，与“不是想办法的人”矛盾。"}, {"text": "执行人", "is_correct": true, "explanation": "正确：他负责实施这个办法，不是想出办法的人，符合句意。"}, {"text": "缔造者", "is_correct": false, "explanation": "语域：“缔造者”是书面语，口语里不这样说，而且与“不是想办法的人”语义矛盾。"}], "explanations": {"发明者": "语义：发明者就是想出办法的人，与“不是想办法的人”矛盾。", "设计者": "语义：设计者负责构想办法，与“不是想办法的人”矛盾。", "执行人": "正确：他负责实施这个办法，不是想出办法的人，符合句意。", "缔造者": "语域：“缔造者”是书面语，口语里不这样说，而且与“不是想办法的人”语义矛盾。"}, "sentence_index": 6, "correct_answer": "执行人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的执行人很多，场边坐满了人。", "explanation": "这里应该用〈观众〉。执行人指负责实施任务的人，场边坐着看比赛的是观众。"}, {"text": "医院的执行人很多，大家都在排队等候看病。", "explanation": "这里应该用〈病人〉。执行人指负责实施任务的人，排队等候看病的是病人。"}, {"text": "公交车上的执行人很多，大家都挤在一起。", "explanation": "这里应该用〈乘客〉。执行人指负责实施任务的人，坐在公交车上的是乘客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动请了几个执行人们。", "corrected_sentence": "这次活动请了几个执行人。", "error_description": "错误形式：“几个执行人们”，数量词“几个”已表示多数，后面不应再加“们”；正确形式：“几个执行人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只新来的执行人负责这个项目。", "corrected_sentence": "一位新来的执行人负责这个项目。", "error_description": "错误形式：“一只新来的执行人”，量词“只”用于动物等，不能用于人；正确形式：“一位新来的执行人”，指人的名词应用量词“位”（或“个”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
