INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95668, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责实施某项决定或任务的人。", "primary_collocate": null, "pronunciation": "zhí xíng rén", "ipa": "ʈʂʅ˧˥ ɕiŋ˧˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "这个项目的执行人是李经理。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上选出了新的执行人。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "执行人要对结果负责。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定让他当执行人。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这个任务的执行人是谁。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的执行人已经定了。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "执行人每周都要写工作报告。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校做了决定，执行人是王老师。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "执行人要把会上的决定做好。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个计划的执行人，大家都听他的。", "target_word": "执行人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "负责把某项决定或任务落实的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c700c0d7-db17-4b7b-9253-55dd4846dada') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资金", "is_correct": false, "explanation": "语义：资金不是人，不能说“这个项目的资金是李经理”。"}, {"text": "执行人", "is_correct": true, "explanation": "正确：“这个项目的执行人”是负责落实项目的人，由李经理担任，符合句意。"}, {"text": "目标", "is_correct": false, "explanation": "语义：目标是要达到的结果，不是人，不能说“是李经理”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是人的高度，不是人，不能说“这个项目的身高是李经理”。"}], "explanations": {"资金": "语义：资金不是人，不能说“这个项目的资金是李经理”。", "执行人": "正确：“这个项目的执行人”是负责落实项目的人，由李经理担任，符合句意。", "目标": "语义：目标是要达到的结果，不是人，不能说“是李经理”。", "身高": "语义：“身高”是人的高度，不是人，不能说“这个项目的身高是李经理”。"}, "sentence_index": 0, "correct_answer": "执行人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法庭上，执行人作证说他那天一直在家。", "explanation": "这里应该用〈证人〉。执行人指负责实施决定或任务的人，在法庭上作证的是证人。"}, {"text": "饭馆门口排着长队，执行人都在等着进去吃饭。", "explanation": "这里应该用〈顾客〉。执行人指负责实施决定或任务的人，排队等着吃饭的是顾客。"}, {"text": "孩子上学的时候，执行人都来送，场面很热闹。", "explanation": "这里应该用〈家长〉。执行人指负责实施决定或任务的人，来送孩子上学的是家长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会议", "is_correct": false, "explanation": "语义：会议本身不写报告，“会议每周都要写工作报告”说不通。"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件是被写的东西，不会自己写工作报告。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“写工作报告”要求能写字的人作主语，“桌子”不能作施事。"}, {"text": "执行人", "is_correct": true, "explanation": "正确：执行人是负责做事的人，需要每周写工作报告，符合句意。"}], "explanations": {"会议": "语义：会议本身不写报告，“会议每周都要写工作报告”说不通。", "文件": "语义：文件是被写的东西，不会自己写工作报告。", "桌子": "配价：“写工作报告”要求能写字的人作主语，“桌子”不能作施事。", "执行人": "正确：执行人是负责做事的人，需要每周写工作报告，符合句意。"}, "sentence_index": 6, "correct_answer": "执行人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的执行人都很努力，最后拿了冠军。", "explanation": "这里应该用〈运动员〉。执行人指负责实施决定或任务的人，比赛中拿冠军的是运动员。"}, {"text": "执行人在公园里玩耍，笑声不断。", "explanation": "这里应该用〈小孩〉。执行人指负责实施决定或任务的人，在公园里玩耍、笑声不断的是小孩。"}, {"text": "执行人在长城上拍照，玩得很开心。", "explanation": "这里应该用〈游客〉。执行人指负责实施决定或任务的人，在长城上拍照游览的是游客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗执行人每天都来工地。", "corrected_sentence": "这位执行人每天都来工地。", "error_description": "错误形式：“这颗执行人”，“颗”用于小而圆的东西，不能修饰人；正确形式：“这位执行人”，“位”是指人的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "领导让他是这次活动的执行人。", "corrected_sentence": "领导让他当这次活动的执行人。", "error_description": "错误形式：“让他是这次活动的执行人”，动词“是”不能用于“让……当……”的结构；正确形式：“让他当这次活动的执行人”，动词应用“当”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '088878fe-e5b8-44e9-b148-4243b697f39b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
