INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95670, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用捐赠的资金从事公益事业的社会组织。", "primary_collocate": null, "pronunciation": "jī jīn huì", "ipa": "tɕi˥ tɕin˥ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "这家基金会专门支持教育事业。", "target_word": "基金会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基金会用捐赠的资金做公益。", "target_word": "基金会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在基金会负责管理资金。", "target_word": "基金会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个基金会每年资助十个学生。", "target_word": "基金会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基金会的钱都来自社会捐赠。", "target_word": "基金会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一家环保基金会正在招人。", "target_word": "基金会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基金会定期公开自己的资金用途。", "target_word": "基金会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个基金会在山区建了三所学校。", "target_word": "基金会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给一家儿童基金会捐过款。", "target_word": "基金会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基金会的工作人员去了灾区。", "target_word": "基金会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}, {"form": "慈善基金会", "label": "复合"}], "register": "中性", "sense_fingerprint": "用捐赠资金从事公益的社会组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '246cb159-8ced-40af-9dd4-ae34aecf1ef8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基金会", "is_correct": true, "explanation": "基金会：是以公益为目的的组织，与“专门支持教育事业”相符。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院以诊疗为主要业务，不以支持教育事业为职能。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店以餐饮为业，与“支持教育事业”不相关。"}, {"text": "铺子", "is_correct": false, "explanation": "语义：小铺子是做买卖的小店，不以支持教育事业为专门职能。"}], "explanations": {"基金会": "基金会：是以公益为目的的组织，与“专门支持教育事业”相符。", "医院": "语义：医院以诊疗为主要业务，不以支持教育事业为职能。", "饭店": "语义：饭店以餐饮为业，与“支持教育事业”不相关。", "铺子": "语义：小铺子是做买卖的小店，不以支持教育事业为专门职能。"}, "sentence_index": 0, "correct_answer": "基金会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本基金会帮助了很多老人。", "explanation": "这里应该用〈家〉。“本”用于书本，基金会是组织，不能这样计量。"}, {"text": "这条基金会帮助了很多农民。", "explanation": "这里应该用〈家〉。“条”用于细长的东西，基金会不能这样计量。"}, {"text": "我在一座基金会实习。", "explanation": "这里应该用〈家〉。“座”用于山、桥、楼等大型固定物，基金会不能这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基金会", "is_correct": true, "explanation": "基金会：有义务定期公开资金用途，与语境相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能公开资金用途。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是能够公开财务信息的主体。"}, {"text": "早晨", "is_correct": false, "explanation": "配价：“公开”的施事须是组织或人，时间词“早晨”不能充当。"}], "explanations": {"基金会": "基金会：有义务定期公开资金用途，与语境相符。", "小猫": "语义：小猫不能公开资金用途。", "厨房": "语义：厨房不是能够公开财务信息的主体。", "早晨": "配价：“公开”的施事须是组织或人，时间词“早晨”不能充当。"}, "sentence_index": 6, "correct_answer": "基金会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只基金会每年都在灾区做公益。", "explanation": "这里应该用〈家〉。“只”多用于动物或成对的物品，基金会不能这样计量。"}, {"text": "我哥哥在一把基金会上班。", "explanation": "这里应该用〈家〉。“把”用于有柄的器具，基金会不能这样计量。"}, {"text": "这张基金会去年招了两百人。", "explanation": "这里应该用〈家〉。“张”用于纸张、桌子等平面物，基金会不能这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条基金会在山区建了两所学校。", "corrected_sentence": "那家基金会在山区建了两所学校。", "error_description": "“那条基金会”错误：“条”用于细长的东西，组织应用量词“家”，应为“那家基金会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他基金会上班。", "corrected_sentence": "他在基金会上班。", "error_description": "“基金会上班”错误：表示地点的“在”缺失。“在基金会”表示工作的地点，应放在动词前，写作“在基金会上班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95671, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冬季", "is_correct": true, "explanation": "冬季与夏季是反义词，指一年中最冷的几个月。"}, {"text": "书桌", "is_correct": false, "explanation": "书桌与夏季没有反义关系，二者意义无关。"}, {"text": "草原", "is_correct": false, "explanation": "草原与夏季没有反义关系，二者不是对立的概念。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞与夏季没有反义关系，二者不属于同一对立关系。"}], "correct_answer": "冬季", "explanations": {"冬季": "冬季与夏季是反义词，指一年中最冷的几个月。", "书桌": "书桌与夏季没有反义关系，二者意义无关。", "草原": "草原与夏季没有反义关系，二者不是对立的概念。", "雨伞": "雨伞与夏季没有反义关系，二者不属于同一对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
