INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95671, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年里最热的那几个月。", "primary_collocate": null, "pronunciation": "xià jì", "ipa": "ɕjɑ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "夏季的三个月里，天气总是很热。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "整个夏季，他都住在乡下的奶奶家。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏季那几个月，空调一直开着。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年夏季，这里都有很多游客。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到夏季，蚊子就多起来了。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏季特别热，大家都不愿出门。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏季过去了，天气慢慢凉了。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在夏季学会游泳。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏季的电费比别的月份高很多。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在这个夏季认识了很多新朋友。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个夏季", "label": "量词（个）"}, {"form": "夏季风", "label": "复合词"}, {"form": "夏季赛", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "一年里最热的那段时间，几个月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95671, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "夏季", "is_correct": true, "explanation": "夏季（xià jì）指一年里最热的那几个月，是正确答案。"}, {"text": "下集", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，下集指电视剧等的下一集。"}, {"text": "下机", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，下机指离开飞机或机器停止运行。"}, {"text": "夏至", "is_correct": false, "explanation": "zhì 与 jì 声母不同（zh 与 j），夏至是二十四节气之一，不指月份。"}, {"text": "下地", "is_correct": false, "explanation": "dì 与 jì 声母不同（d 与 j），下地指下田干活。"}], "explanations": {"夏季": "夏季（xià jì）指一年里最热的那几个月，是正确答案。", "下集": "jí（第二声）与 jì（第四声）声调不同，下集指电视剧等的下一集。", "下机": "jī（第一声）与 jì（第四声）声调不同，下机指离开飞机或机器停止运行。", "夏至": "zhì 与 jì 声母不同（zh 与 j），夏至是二十四节气之一，不指月份。", "下地": "dì 与 jì 声母不同（d 与 j），下地指下田干活。"}, "sentence_index": null, "correct_answer": "夏季"}, "level_3": {"options": [{"text": "夏季", "is_correct": true, "explanation": "夏季在此指一年中最热的几个月，符合“三个月里天气很热”的句意。"}, {"text": "冬季", "is_correct": false, "explanation": "语义：冬季是最冷的时段，与“天气总是很热”矛盾。"}, {"text": "寒假", "is_correct": false, "explanation": "语义：寒假在冬季，一般只有几周，且天气不会总是很热，与句意矛盾。"}, {"text": "四季", "is_correct": false, "explanation": "搭配：“四季”是全年的总称，不能说“四季的三个月”。"}], "explanations": {"夏季": "夏季在此指一年中最热的几个月，符合“三个月里天气很热”的句意。", "冬季": "语义：冬季是最冷的时段，与“天气总是很热”矛盾。", "寒假": "语义：寒假在冬季，一般只有几周，且天气不会总是很热，与句意矛盾。", "四季": "搭配：“四季”是全年的总称，不能说“四季的三个月”。"}, "sentence_index": 0, "correct_answer": "夏季"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们吃了一顿夏季。", "explanation": "这里应该用〈晚饭〉。“吃”的对象是食物，夏季指一段时间，不能作为吃的东西。"}, {"text": "我们在海边度过了一阵夏季。", "explanation": "这里量词应用“个”（一个夏季）。“阵”指较短的一段时间，夏季有数月，不能用“阵”计量。"}, {"text": "他在乡下住了一条夏季。", "explanation": "这里量词应用“个”（一个夏季）。“条”用于细长的事物，如河、路、裤子，不能计量夏季。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夏季", "is_correct": true, "explanation": "夏季指炎热的几个月，过去后天气转凉，符合句意。"}, {"text": "春季", "is_correct": false, "explanation": "语义：春季过后通常转暖，不会出现“天气慢慢凉了”。"}, {"text": "冬季", "is_correct": false, "explanation": "语义：冬季过后天气会转暖，不会出现“天气慢慢凉了”，与句意矛盾。"}, {"text": "春节", "is_correct": false, "explanation": "语义：春节在冬末春初，之后天气转暖，与“慢慢凉了”冲突。"}], "explanations": {"夏季": "夏季指炎热的几个月，过去后天气转凉，符合句意。", "春季": "语义：春季过后通常转暖，不会出现“天气慢慢凉了”。", "冬季": "语义：冬季过后天气会转暖，不会出现“天气慢慢凉了”，与句意矛盾。", "春节": "语义：春节在冬末春初，之后天气转暖，与“慢慢凉了”冲突。"}, "sentence_index": 6, "correct_answer": "夏季"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们都盼着放夏季。", "explanation": "这里应该用〈暑假〉。“放”的对象是假期，夏季指一段时间，不能说“放夏季”。"}, {"text": "学校每年都举办夏季。", "explanation": "这里应该用〈运动会〉。“举办”的对象是活动或比赛，夏季不能被举办。"}, {"text": "我想去参加夏季。", "explanation": "这里应该用〈夏令营〉。“参加”的对象是活动，夏季指时段，不能作为参加的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年在国外待了一次夏季。", "corrected_sentence": "她去年在国外待了一个夏季。", "error_description": "错误：量词用“次”；正确：用“个”。“次”表示次数，不能用来计量一段较长的夏季，应说“一个夏季”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个夏季地天气特别干燥。", "corrected_sentence": "这个夏季的天气特别干燥。", "error_description": "错误：“夏季地天气”；正确：“夏季的天气”。“地”多用于修饰动词、形容词，名词前的修饰语要用“的”，应说“夏季的天气”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95672, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冬季", "is_correct": true, "explanation": "冬季与夏季是反义词，指一年中最冷的季节。"}, {"text": "河流", "is_correct": false, "explanation": "河流与夏季没有反义关系，二者不是对立的概念。"}, {"text": "教室", "is_correct": false, "explanation": "教室与夏季没有反义关系，二者不属于同一对立关系。"}, {"text": "牛奶", "is_correct": false, "explanation": "牛奶与夏季没有反义关系，二者意义无关。"}], "correct_answer": "冬季", "explanations": {"冬季": "冬季与夏季是反义词，指一年中最冷的季节。", "河流": "河流与夏季没有反义关系，二者不是对立的概念。", "教室": "教室与夏季没有反义关系，二者不属于同一对立关系。", "牛奶": "牛奶与夏季没有反义关系，二者意义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
