INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年中最炎热的季节。", "primary_collocate": null, "pronunciation": "xià jì", "ipa": "ɕjɑ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "夏季是一年中最热的季节。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的夏季又长又热。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏季的白天比冬季长。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏季常常下大雨，天气很闷热。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年夏季我们去海边玩了。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏季吃西瓜可以消暑。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的夏季不太潮湿。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏季的夜晚，大家喜欢在外面乘凉。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店夏季的衣服正在打折。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏季到了，孩子们都想去游泳。", "target_word": "夏季", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个夏季", "label": "量词（个）"}, {"form": "夏季风", "label": "复合词"}, {"form": "夏季赛", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "一年四季中最热的那个季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95672, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "夏季", "is_correct": true, "explanation": "夏季（xià jì）指一年中最热的季节，是正确答案。"}, {"text": "下级", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，下级指等级较低的一方。"}, {"text": "下机", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，下机指离开飞机或机器停止运行。"}, {"text": "夏至", "is_correct": false, "explanation": "zhì 与 jì 声母不同（zh 与 j），夏至是二十四节气之一，不指季节。"}, {"text": "下地", "is_correct": false, "explanation": "dì 与 jì 声母不同（d 与 j），下地指下田干活。"}], "explanations": {"夏季": "夏季（xià jì）指一年中最热的季节，是正确答案。", "下级": "jí（第二声）与 jì（第四声）声调不同，下级指等级较低的一方。", "下机": "jī（第一声）与 jì（第四声）声调不同，下机指离开飞机或机器停止运行。", "夏至": "zhì 与 jì 声母不同（zh 与 j），夏至是二十四节气之一，不指季节。", "下地": "dì 与 jì 声母不同（d 与 j），下地指下田干活。"}, "sentence_index": null, "correct_answer": "夏季"}, "level_3": {"options": [{"text": "夏季", "is_correct": true, "explanation": "夏季指一年中最热的季节，符合句中“最热的季节”的说法。"}, {"text": "冬季", "is_correct": false, "explanation": "语义：冬季是一年中最冷的季节，与后面的“最热”矛盾。"}, {"text": "春季", "is_correct": false, "explanation": "语义：春季是一年中较为温和的季节，并非最热，句子说不通。"}, {"text": "四季", "is_correct": false, "explanation": "搭配：“四季”是春夏秋冬的总称，不能与单数的“最热的季节”搭配。"}], "explanations": {"夏季": "夏季指一年中最热的季节，符合句中“最热的季节”的说法。", "冬季": "语义：冬季是一年中最冷的季节，与后面的“最热”矛盾。", "春季": "语义：春季是一年中较为温和的季节，并非最热，句子说不通。", "四季": "搭配：“四季”是春夏秋冬的总称，不能与单数的“最热的季节”搭配。"}, "sentence_index": 0, "correct_answer": "夏季"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们暑假去参加夏季。", "explanation": "这里应该用〈夏令营〉。“参加”的对象是活动，夏季指季节，不能作为参加的对象。"}, {"text": "我们在海边度过了一场夏季。", "explanation": "这里量词应用“个”（一个夏季）。夏季不能用“场”计量，“场”多用于比赛、演出、雨等。"}, {"text": "我今年买了很多夏季。", "explanation": "这里应该用〈夏装〉。“买”的对象是具体的物品，夏季指季节，不能作为买的东西，应说“买很多夏装”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夏季", "is_correct": true, "explanation": "夏季指一年中最热的季节，能与“北方的”搭配，符合句意。"}, {"text": "梅雨季", "is_correct": false, "explanation": "语义：梅雨季以多雨潮湿著称，与“不太潮湿”矛盾。"}, {"text": "回南天", "is_correct": false, "explanation": "搭配：回南天是中国南方春季特有的天气现象，不说“北方的回南天”。"}, {"text": "黄梅天", "is_correct": false, "explanation": "语义：黄梅天指梅雨时节，天气闷湿，与“不太潮湿”冲突。"}], "explanations": {"夏季": "夏季指一年中最热的季节，能与“北方的”搭配，符合句意。", "梅雨季": "语义：梅雨季以多雨潮湿著称，与“不太潮湿”矛盾。", "回南天": "搭配：回南天是中国南方春季特有的天气现象，不说“北方的回南天”。", "黄梅天": "语义：黄梅天指梅雨时节，天气闷湿，与“不太潮湿”冲突。"}, "sentence_index": 6, "correct_answer": "夏季"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们都盼着放夏季。", "explanation": "这里应该用〈暑假〉。“放”的对象是假期，夏季指季节，不能说“放夏季”。"}, {"text": "他在乡下过了一条夏季。", "explanation": "这里量词应用“个”（一个夏季）。“条”用于细长的事物，如河、路、裤子，不能计量夏季。"}, {"text": "学校每年都举办夏季。", "explanation": "这里应该用〈运动会〉。“举办”的对象是活动或比赛，夏季是季节，不能被举办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他喜欢夏季地海风。", "corrected_sentence": "他喜欢夏季的海风。", "error_description": "错误：“夏季地海风”；正确：“夏季的海风”。“地”多用于修饰动词、形容词，名词前的修饰语要用“的”，应说“夏季的海风”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在小镇住了三只夏季。", "corrected_sentence": "我们在小镇住了三个夏季。", "error_description": "错误：量词用“只”；正确：用“个”。“只”多用于动物或成对物品中的一个，夏季应说“三个夏季”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
