INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95673, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "除了平常的工资以外，另外挣到的钱。", "primary_collocate": null, "pronunciation": "wài kuài", "ipa": "wai˥˩ kʰwai˥˩", "syllable_count": 2, "sentences": [{"text": "他下班后开网约车，赚点外快。", "target_word": "外快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师周末教课，能赚一些外快。", "target_word": "外快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔外快让我买了新手机。", "target_word": "外快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠写文章挣外快。", "target_word": "外快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做手工，每月有点外快。", "target_word": "外快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生常常打零工赚外快。", "target_word": "外快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用外快给孩子交了学费。", "target_word": "外快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资不高，所以他想找点外快。", "target_word": "外快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我多了一笔外快。", "target_word": "外快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把外快都存了起来。", "target_word": "外快", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "名词：工资以外另外挣到的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016a8d2a-68e4-4db2-b1cd-c081d7aad3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95673, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外快", "is_correct": true, "explanation": "正确。外快：工资以外另外挣到的钱，与“赚”搭配。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种病，不是钱，不能说“赚点感冒”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是钱，不能被赚到。"}, {"text": "税", "is_correct": false, "explanation": "搭配：税是要缴纳的，不能说“赚税”。"}], "explanations": {"外快": "正确。外快：工资以外另外挣到的钱，与“赚”搭配。", "感冒": "语义：感冒是一种病，不是钱，不能说“赚点感冒”。", "作业": "语义：作业是学习任务，不是钱，不能被赚到。", "税": "搭配：税是要缴纳的，不能说“赚税”。"}, "sentence_index": 0, "correct_answer": "外快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他要向国家交一笔外快。", "explanation": "这里应该用〈税款〉。外快是自己挣来的收入，不是要交给国家的钱。"}, {"text": "这个月我挣了一只外快。", "explanation": "这里应该用〈笔〉。外快用“笔”计量，“只”用于动物或成对的东西。"}, {"text": "政府发放了一笔外快。", "explanation": "这里应该用〈补贴〉。外快是自己挣来的钱，政府的发放不属于外快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外快", "is_correct": true, "explanation": "正确。外快：工资以外另外挣到的钱，可以用来交学费。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“交”接的是费用，时间不能用来交学费。"}, {"text": "烦恼", "is_correct": false, "explanation": "语义：烦恼是心情，不是钱，不能用来交学费。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情不能用来支付费用，“交学费”的说法不成立。"}], "explanations": {"外快": "正确。外快：工资以外另外挣到的钱，可以用来交学费。", "时间": "搭配：“交”接的是费用，时间不能用来交学费。", "烦恼": "语义：烦恼是心情，不是钱，不能用来交学费。", "感情": "语义：感情不能用来支付费用，“交学费”的说法不成立。"}, "sentence_index": 6, "correct_answer": "外快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的外快是每月固定的工资。", "explanation": "这里不能这样用：外快指正常收入之外额外挣来的钱，不能说成定期发放的固定薪水。"}, {"text": "他每天吃一顿外快。", "explanation": "这里应该用〈饭〉。外快是钱，不能吃。"}, {"text": "他按时还了外快。", "explanation": "这里应该用〈房贷〉。“还”的对象是欠款，外快是收入，不能被“还”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她晚上在网上卖手工艺品，挣了一只外快。", "corrected_sentence": "她晚上在网上卖手工艺品，挣了一笔外快。", "error_description": "量词错误：外快用“笔”计量，“只”用于动物或成对的东西，不能说“一只外快”，正确说法是“挣了一笔外快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐周末在超市兼职，挣了到一笔外快。", "corrected_sentence": "我姐姐周末在超市兼职，挣到了一笔外快。", "error_description": "补语错误：结果补语“到”应紧接在动词后，再接“了”。“挣了到”不成立，正确说法是“挣到了一笔外快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
