INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "规模巨大、需用计算机处理分析的数据集合。", "primary_collocate": null, "pronunciation": "dà shù jù", "ipa": "ta˥˩ ʂu˥˩ tɕy˥˩", "syllable_count": 3, "sentences": [{"text": "公司用大数据分析客户的习惯。", "target_word": "大数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院用大数据研究常见的病。", "target_word": "大数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大数据需要很强的计算机来处理。", "target_word": "大数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说大数据很重要，他认真记笔记。", "target_word": "大数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大数据能帮城市减少堵车。", "target_word": "大数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件会分析大数据。", "target_word": "大数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大数据的规模越来越大。", "target_word": "大数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行用大数据判断客户有没有风险。", "target_word": "大数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多商店靠大数据决定卖什么。", "target_word": "大数据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "处理大数据，普通电脑不够用。", "target_word": "大数据", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大数据时代", "label": "复合"}, {"form": "大数据分析", "label": "复合"}], "register": "中性", "sense_fingerprint": "需用计算机处理分析的巨量数据集合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '246cb159-8ced-40af-9dd4-ae34aecf1ef8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大数据", "is_correct": true, "explanation": "大数据：需用计算机处理分析的巨量数据，与“分析客户的习惯”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以用来分析的数据，句子不通。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能用来分析客户的习惯。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“分析”的对象应是数据或情况，不搭配“空气”。"}], "explanations": {"大数据": "大数据：需用计算机处理分析的巨量数据，与“分析客户的习惯”相符。", "石头": "语义：石头不是可以用来分析的数据，句子不通。", "面包": "语义：面包是食物，不能用来分析客户的习惯。", "空气": "搭配：“分析”的对象应是数据或情况，不搭配“空气”。"}, "sentence_index": 0, "correct_answer": "大数据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用大数据织了一件毛衣。", "explanation": "这里应该用〈毛线〉。大数据是信息的集合，织毛衣要用毛线。"}, {"text": "奶奶每晚都给我讲大数据。", "explanation": "这里应该用〈故事〉。大数据是数据的集合，不能讲给人听，讲的应是故事。"}, {"text": "他的大数据是一只红色的小鸟。", "explanation": "这里应该用〈玩具〉。大数据是信息的集合，不能是一只小鸟，这里应指玩具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大数据", "is_correct": true, "explanation": "大数据：规模不断扩大的巨量数据，与“规模越来越大”相符。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”没有“规模”可言，“心情的规模越来越大”不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不能说规模越来越大，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”不能说“规模越来越大”，句子不通。"}], "explanations": {"大数据": "大数据：规模不断扩大的巨量数据，与“规模越来越大”相符。", "心情": "搭配：“心情”没有“规模”可言，“心情的规模越来越大”不通。", "眼睛": "语义：眼睛不能说规模越来越大，句意不通。", "脚步": "语义：“脚步”不能说“规模越来越大”，句子不通。"}, "sentence_index": 6, "correct_answer": "大数据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座房子的大数据很大，我们都住不下。", "explanation": "这里应该用〈面积〉。大数据指信息规模，不能描述房子的大小。"}, {"text": "这碗汤的大数据很好喝。", "explanation": "这里应该用〈味道〉。大数据没有滋味，不能用来形容汤的口感。"}, {"text": "我们要用电脑喝大数据。", "explanation": "这里应该用〈饮料〉。大数据是信息，不能被喝，喝的对象应是饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究所用一台大数据预测天气变化。", "corrected_sentence": "研究所用大数据预测天气变化。", "error_description": "“一台大数据”错误：大数据是不可数的抽象集合，不用量词“台”（台用于机器）。应直接说“用大数据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司每天要分析很多大数据们。", "corrected_sentence": "公司每天要分析很多大数据。", "error_description": "错误：大数据是不可数的集合名词，不能加复数标记“们”。正确形式是“分析很多大数据”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0798c62e-3ba8-41b7-acbe-e475de342fb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
