INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95677, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年纪小的女生。", "primary_collocate": null, "pronunciation": "nǚ hái zi", "ipa": "ny˨˩˦ xaɪ˧˥ tsɹ̩", "syllable_count": 3, "sentences": [{"text": "那个女孩子在公园里画画。", "target_word": "女孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里有十个女孩子。", "target_word": "女孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩子今年七岁。", "target_word": "女孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个女孩子在门口等你。", "target_word": "女孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩子们都喜欢这个玩具。", "target_word": "女孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女孩子穿着红色的裙子。", "target_word": "女孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家隔壁有个爱笑的女孩子。", "target_word": "女孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩子跑得很快。", "target_word": "女孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的女孩子都在跳绳。", "target_word": "女孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给女孩子一朵花。", "target_word": "女孩子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "女孩子们", "label": "复数"}], "register": "口语", "sense_fingerprint": "年纪小的女生（指学生、小朋友）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03215d03-95c8-4cd4-8139-5091553db1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95677, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "狗", "is_correct": false, "explanation": "语义：“狗”不能在公园里画画，句意不通。"}, {"text": "女孩子", "is_correct": true, "explanation": "女孩子：年纪小的女生，能在公园里画画。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“雨”前不用“个”计量，而且雨不会画画，句子不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不会在公园里画画，句意不通。"}], "explanations": {"狗": "语义：“狗”不能在公园里画画，句意不通。", "女孩子": "女孩子：年纪小的女生，能在公园里画画。", "雨": "搭配：“雨”前不用“个”计量，而且雨不会画画，句子不成立。", "桌子": "语义：“桌子”不会在公园里画画，句意不通。"}, "sentence_index": 0, "correct_answer": "女孩子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只女孩子在门口等你。", "explanation": "这里应该用〈个〉。“只”多用于动物等，不用于指人的“女孩子”。"}, {"text": "那朵女孩子在门口等你。", "explanation": "这里应该用〈个〉。“朵”多用于花等，不用于指人的“女孩子”。"}, {"text": "那条女孩子在门口等你。", "explanation": "这里应该用〈个〉。“条”多用于细长的东西，不用于指人的“女孩子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：“石头”不会“爱笑”，句意不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”不会“爱笑”，句子说的是一个人。"}, {"text": "女孩子", "is_correct": true, "explanation": "女孩子：年纪小的女生，与“爱笑”的人物相合。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“椅子”前的量词应为“把”，与“个”不搭配，而且椅子不会“爱笑”。"}], "explanations": {"石头": "语义：“石头”不会“爱笑”，句意不通。", "书": "语义：“书”不会“爱笑”，句子说的是一个人。", "女孩子": "女孩子：年纪小的女生，与“爱笑”的人物相合。", "椅子": "搭配：“椅子”前的量词应为“把”，与“个”不搭配，而且椅子不会“爱笑”。"}, "sentence_index": 6, "correct_answer": "女孩子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张女孩子很可爱。", "explanation": "这里应该用〈个〉。“张”多用于平面的东西，不用于指人的“女孩子”。"}, {"text": "这头女孩子很可爱。", "explanation": "这里应该用〈个〉。“头”多用于牲畜，不用于指人的“女孩子”。"}, {"text": "这辆女孩子很可爱。", "explanation": "这里应该用〈个〉。“辆”多用于车，不用于指人的“女孩子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个女孩子们在门口等你。", "corrected_sentence": "两个女孩子在门口等你。", "error_description": "“们”不能跟在数词后面，有数量词时只说“两个女孩子”，不说“两个女孩子们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家楼下有一只爱唱歌的女孩子。", "corrected_sentence": "我家楼下有一个爱唱歌的女孩子。", "error_description": "错误：“女孩子”指人，量词不能用“只”（多用于动物）；正确：“一个女孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19d14c28-aa0c-42df-a1a2-48e51e22f68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
