INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95679, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电影下面出现的一行一行的字。", "primary_collocate": null, "pronunciation": "zì mù", "ipa": "tsɨ˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "电影下面有中文字幕。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影没有字幕，我听不懂。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢看有英文字幕的电影。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "字幕在屏幕下面，字很小。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能把字幕关掉吗？", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看电影时总是开着字幕。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字幕太快了，我看不完。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看过带字幕的法国电影。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们看着字幕学英语。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把电影的字幕打开。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "中文字幕", "label": "复合"}, {"form": "英文字幕", "label": "复合"}], "register": "中性", "sense_fingerprint": "电影画面下方一行行出现的文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95679, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "字幕", "is_correct": true, "explanation": "正确：电影画面下方一行行出现的文字。"}, {"text": "字母", "is_correct": false, "explanation": "mǔ（第三声）与 mù（第四声）声调不同，意思是字母。"}, {"text": "刺目", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是光线强烈、刺眼。"}, {"text": "字模", "is_correct": false, "explanation": "mú（第二声）与 mù（第四声）声调不同，意思是印刷用的铸字模型。"}, {"text": "子目", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是细分的小项目。"}], "explanations": {"字幕": "正确：电影画面下方一行行出现的文字。", "字母": "mǔ（第三声）与 mù（第四声）声调不同，意思是字母。", "刺目": "cì 与 zì 声母不同（c 与 z），意思是光线强烈、刺眼。", "字模": "mú（第二声）与 mù（第四声）声调不同，意思是印刷用的铸字模型。", "子目": "zǐ（第三声）与 zì（第四声）声调不同，意思是细分的小项目。"}, "sentence_index": null, "correct_answer": "字幕"}, "level_3": {"options": [{"text": "歌词", "is_correct": false, "explanation": "语义：歌词是歌曲的文字，不会一行行出现在电影画面下方。"}, {"text": "字幕", "is_correct": true, "explanation": "正确：电影画面下方配合显示的文字，正是“下面有中文”的对象。"}, {"text": "海报", "is_correct": false, "explanation": "语义：海报是张贴的宣传画，不是画面下方出现的文字。"}, {"text": "配音", "is_correct": false, "explanation": "搭配：“下面有”后接的应是文字，“中文配音”指声音，与画面位置不搭。"}], "explanations": {"歌词": "语义：歌词是歌曲的文字，不会一行行出现在电影画面下方。", "字幕": "正确：电影画面下方配合显示的文字，正是“下面有中文”的对象。", "海报": "语义：海报是张贴的宣传画，不是画面下方出现的文字。", "配音": "搭配：“下面有”后接的应是文字，“中文配音”指声音，与画面位置不搭。"}, "sentence_index": 0, "correct_answer": "字幕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "演员背熟了字幕。", "explanation": "这里应该用〈台词〉。演员要背的是台词，字幕是屏幕下方显示给观众看的文字。"}, {"text": "这篇文章的字幕很吸引人。", "explanation": "这里应该用〈标题〉。字幕只出现在影视画面中，文章的名字要用标题。"}, {"text": "他把字幕贴在墙上。", "explanation": "这里应该用〈海报〉。字幕是画面上显示的文字，贴在墙上的是海报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95679, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "搭配：“看”不能搭配“声音”，声音是用耳朵听的，不能“看不完”。"}, {"text": "字幕", "is_correct": true, "explanation": "正确：画面下方一行行出现的文字，可以“太快”，也可以“看不完”。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是用来听的，不是画面上要看的文字，不会“看不完”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是数字，不会“太快”，也谈不上“看不完”。"}], "explanations": {"声音": "搭配：“看”不能搭配“声音”，声音是用耳朵听的，不能“看不完”。", "字幕": "正确：画面下方一行行出现的文字，可以“太快”，也可以“看不完”。", "音乐": "语义：音乐是用来听的，不是画面上要看的文字，不会“看不完”。", "价格": "语义：价格是数字，不会“太快”，也谈不上“看不完”。"}, "sentence_index": 6, "correct_answer": "字幕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的字幕很漂亮。", "explanation": "这里应该用〈字体〉。字体指字的样式，字幕是画面下方的文字内容，书上的字样不叫字幕。"}, {"text": "演员唱的字幕很好听。", "explanation": "这里应该用〈歌词〉。唱的是歌词，字幕是屏幕上显示的文字，不能唱。"}, {"text": "商品的字幕很清楚。", "explanation": "这里应该用〈标签〉。商品上的文字叫标签，字幕是影视画面中配合显示的文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些字幕们出现得很快。", "corrected_sentence": "这些字幕出现得很快。", "error_description": "错误：“们”只用于指人的名词，“字幕”是事物，不能加“们”，应说“这些字幕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屏幕下面出现了一只字幕。", "corrected_sentence": "屏幕下面出现了一条字幕。", "error_description": "错误：量词用错。“字幕”用量词“条”，“只”用于动物等，不能说“一只字幕”，应说“一条字幕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
