INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "影视画面中配合显示的文字。", "primary_collocate": null, "pronunciation": "zì mù", "ipa": "tsɨ˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "这个电视剧的字幕很清楚。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频里的字幕错了一个字。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在家给短视频加字幕。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻节目的字幕说明了地点。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有字幕，我看不懂这个视频。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧的字幕是谁做的？", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个视频的字幕是红色的。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学会了做视频字幕。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段视频的字幕和台词对不上。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机给视频加过字幕。", "target_word": "字幕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "视频字幕", "label": "复合"}, {"form": "中文字幕", "label": "复合"}], "register": "中性", "sense_fingerprint": "电视剧、视频、新闻等画面中配合显示的文字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95680, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "字幕", "is_correct": true, "explanation": "正确：影视画面中配合显示的文字。"}, {"text": "字母", "is_correct": false, "explanation": "mǔ（第三声）与 mù（第四声）声调不同，意思是字母。"}, {"text": "刺目", "is_correct": false, "explanation": "cì 与 zì 声母不同（c 与 z），意思是光线强烈、刺眼。"}, {"text": "字模", "is_correct": false, "explanation": "mú（第二声）与 mù（第四声）声调不同，意思是印刷用的铸字模型。"}, {"text": "子目", "is_correct": false, "explanation": "zǐ（第三声）与 zì（第四声）声调不同，意思是细分的小项目。"}], "explanations": {"字幕": "正确：影视画面中配合显示的文字。", "字母": "mǔ（第三声）与 mù（第四声）声调不同，意思是字母。", "刺目": "cì 与 zì 声母不同（c 与 z），意思是光线强烈、刺眼。", "字模": "mú（第二声）与 mù（第四声）声调不同，意思是印刷用的铸字模型。", "子目": "zǐ（第三声）与 zì（第四声）声调不同，意思是细分的小项目。"}, "sentence_index": null, "correct_answer": "字幕"}, "level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：电视剧没有年龄，“年龄很清楚”说不通。"}, {"text": "字幕", "is_correct": true, "explanation": "正确：电视剧画面里配合显示的文字，可以“很清楚”。"}, {"text": "气味", "is_correct": false, "explanation": "语义：电视剧没有气味，“气味很清楚”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：电视剧没有体重，不能说“体重很清楚”。"}], "explanations": {"年龄": "语义：电视剧没有年龄，“年龄很清楚”说不通。", "字幕": "正确：电视剧画面里配合显示的文字，可以“很清楚”。", "气味": "语义：电视剧没有气味，“气味很清楚”说不通。", "体重": "语义：电视剧没有体重，不能说“体重很清楚”。"}, "sentence_index": 0, "correct_answer": "字幕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的字幕很漂亮。", "explanation": "这里应该用〈封面〉。封面是书的外皮，字幕是影视画面里的文字，书上没有字幕。"}, {"text": "他背熟了演员的字幕。", "explanation": "这里应该用〈台词〉。演员要背的是台词，字幕是屏幕上显示给观众看的文字。"}, {"text": "这首歌的字幕很好听。", "explanation": "这里应该用〈歌词〉。歌曲的文字叫歌词，字幕是画面上配合显示的文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体温", "is_correct": false, "explanation": "语义：体温是一个温度数值，不会有颜色，不能说“是红色的”。"}, {"text": "字幕", "is_correct": true, "explanation": "正确：视频画面里配合显示的文字，可以是红色的。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身体数据，没有颜色，不能用来描述“红色”。"}, {"text": "年份", "is_correct": false, "explanation": "语义：年份表示时间，不会是红色的。"}], "explanations": {"体温": "语义：体温是一个温度数值，不会有颜色，不能说“是红色的”。", "字幕": "正确：视频画面里配合显示的文字，可以是红色的。", "身高": "体貌：身高是人的身体数据，没有颜色，不能用来描述“红色”。", "年份": "语义：年份表示时间，不会是红色的。"}, "sentence_index": 6, "correct_answer": "字幕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店门口的字幕很大。", "explanation": "这里应该用〈招牌〉。店门口挂的大字牌是招牌，字幕属于影视画面。"}, {"text": "这个产品的字幕很详细。", "explanation": "这里应该用〈说明书〉。产品的详细说明写在说明书上，字幕不用于产品。"}, {"text": "这张海报的字幕很醒目。", "explanation": "这里应该用〈标语〉。海报上醒目的口号叫标语，字幕是影视画面上的文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
