INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "比较两件事，觉得这一件更好，宁可选它。", "primary_collocate": null, "pronunciation": "nìng yuàn", "ipa": "niŋ˥˩ yɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我宁愿走路，也不坐那么挤的车。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他宁愿在家看书，也不想出去玩。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈宁愿自己累一点，也不让孩子难过。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我宁愿喝白水，也不喝这种甜饮料。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟宁愿吃面条，也不吃米饭。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她宁愿一个人住，也不和别人一起住。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我宁愿早点起床，也不想迟到。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王宁愿坐火车，也不坐飞机。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我宁愿看电影，也不去逛商店。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明宁愿晚点睡，也不想把作业留到明天。", "target_word": "宁愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "宁愿：比较两件事后选择更好的一件，常用“宁愿A，也不B”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25ffb014-c98c-44e0-81a7-bd5a6b2f207a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宁愿", "is_correct": true, "explanation": "正确：“宁愿”表示经过比较后情愿选前者，与后面的“也不坐那么挤的车”相呼应。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示所幸避免了不利结果，句中并没有这样的前提，说不通。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示碰巧，与“也不坐那么挤的车”这种有意的选择相矛盾。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面承认用语，与口语化的叙述不搭，且后面通常要接转折。"}], "explanations": {"宁愿": "正确：“宁愿”表示经过比较后情愿选前者，与后面的“也不坐那么挤的车”相呼应。", "幸亏": "语义：“幸亏”表示所幸避免了不利结果，句中并没有这样的前提，说不通。", "恰好": "语义：“恰好”表示碰巧，与“也不坐那么挤的车”这种有意的选择相矛盾。", "诚然": "语域：“诚然”是书面承认用语，与口语化的叙述不搭，且后面通常要接转折。"}, "sentence_index": 0, "correct_answer": "宁愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他宁愿生病，今天还是来上班了。", "explanation": "这里应该用〈虽然〉。这句是让步关系（“还是来上班”），而〈宁愿〉表示比较两种做法后情愿选其一，与让步的意思不符。"}, {"text": "你宁愿快点走，不然赶不上车。", "explanation": "这里应该用〈最好〉。〈宁愿〉表示情愿选某种做法，不用于提醒或劝告别人。"}, {"text": "下雨了，我们宁愿在家吧。", "explanation": "这里应该用〈还是〉。“还是……吧”用来提出建议；〈宁愿〉表示比较后情愿选择其中一项，不能和“吧”构成建议句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，句中没有前面的预测，说不通。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于叮嘱或劝阻，如“千万别迟到”，不直接修饰“早点起床”这样的陈述。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预期相反，句中没有可以相对的预期，说不通。"}, {"text": "宁愿", "is_correct": true, "explanation": "正确：“宁愿”表示情愿选早起，与后面的“也不想迟到”相呼应。"}], "explanations": {"果然": "语义：“果然”表示与预料相符，句中没有前面的预测，说不通。", "千万": "搭配：“千万”多用于叮嘱或劝阻，如“千万别迟到”，不直接修饰“早点起床”这样的陈述。", "反而": "语义：“反而”表示与预期相反，句中没有可以相对的预期，说不通。", "宁愿": "正确：“宁愿”表示情愿选早起，与后面的“也不想迟到”相呼应。"}, "sentence_index": 6, "correct_answer": "宁愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "只要你同意，我宁愿去。", "explanation": "这里应该用〈就〉。“只要……就……”是条件关系；〈宁愿〉要比较两种选择，句中只有“去”，没有可比较的另一项，与条件句不搭。"}, {"text": "最后一班车走了，他宁愿走路回家。", "explanation": "这里应该用〈只好〉。没有别的办法、不得已才走路，应用〈只好〉；〈宁愿〉表示主动比较后情愿选择，句中没有可比较的另一项。"}, {"text": "他没有帮忙，宁愿添了乱。", "explanation": "这里应该用〈反而〉。〈宁愿〉表示有意选择，而“没有帮忙却添乱”是与预期相反的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我宁愿晚点回家，也想挤地铁。", "corrected_sentence": "我宁愿晚点回家，也不想挤地铁。", "error_description": "“宁愿……”后面要用“也不……”与之呼应，表示比较后的取舍；这里漏掉了“不”，说成“也想挤地铁”，与“宁愿”的意思矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我宁愿吃冷饭，所以不想现在去买菜。", "corrected_sentence": "我宁愿吃冷饭，也不想现在去买菜。", "error_description": "“宁愿……”后面要用“也不……”与之呼应，表示比较后的取舍；“所以”表示因果，与比较选择不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739b2a7f-3298-49ca-b413-3977069a6cf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
