INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95685, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家里养的、很可爱的小动物，比如小猫小狗。", "primary_collocate": null, "pronunciation": "chǒng wù", "ipa": "ʈʂʰʊŋ˨˩˦ u˥˩", "syllable_count": 2, "sentences": [{"text": "我家有一只宠物。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫是我最爱的宠物。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天带着宠物去公园。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想养什么宠物？", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的宠物是一只小狗。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宠物也是家里的一个成员。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子很喜欢家里的宠物。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给宠物买了新玩具。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有宠物，因为家太小。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宠物吃饭的时间到了。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "宠物狗", "label": "复合"}, {"form": "寵物", "label": "繁体"}], "register": "口语", "sense_fingerprint": "家里养的可爱小动物，如小猫小狗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95685, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宠物", "is_correct": true, "explanation": "“宠物”指家里养的可爱小动物，与量词“只”搭配，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车的量词是“辆”，不能说“一只汽车”。"}, {"text": "桌子", "is_correct": false, "explanation": "量词：桌子用“张”，不能说“一只桌子”。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：电脑的量词是“台”，不能说“一只电脑”。"}], "explanations": {"宠物": "“宠物”指家里养的可爱小动物，与量词“只”搭配，符合句意。", "汽车": "搭配：汽车的量词是“辆”，不能说“一只汽车”。", "桌子": "量词：桌子用“张”，不能说“一只桌子”。", "电脑": "搭配：电脑的量词是“台”，不能说“一只电脑”。"}, "sentence_index": 0, "correct_answer": "宠物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只宠物生活在森林里，很少见到人。", "explanation": "这里应该用〈动物〉。宠物指供人玩赏、陪伴的家养小动物，生活在森林里的野生动物不叫宠物。"}, {"text": "这头猪是农民养来卖的宠物。", "explanation": "这里应该用〈家畜〉。猪是农民养来卖的家畜，不是供人玩赏陪伴的宠物。"}, {"text": "孩子最喜欢的宠物是那辆红色的小汽车。", "explanation": "这里应该用〈玩具〉。宠物是家养的小动物，小汽车是玩具，不能叫宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宠物", "is_correct": true, "explanation": "“宠物”是家里养的小动物，孩子喜欢它，符合句意。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：孩子不会喜欢家里的垃圾，句意说不通。"}, {"text": "蟑螂", "is_correct": false, "explanation": "语义：蟑螂是让人讨厌的害虫，孩子不会喜欢。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒会让人生病，不是家里养的东西，孩子不会喜欢。"}], "explanations": {"宠物": "“宠物”是家里养的小动物，孩子喜欢它，符合句意。", "垃圾": "语义：孩子不会喜欢家里的垃圾，句意说不通。", "蟑螂": "语义：蟑螂是让人讨厌的害虫，孩子不会喜欢。", "病毒": "语义：病毒会让人生病，不是家里养的东西，孩子不会喜欢。"}, "sentence_index": 6, "correct_answer": "宠物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里种着很多宠物，夏天特别漂亮。", "explanation": "这里应该用〈植物〉。宠物是供人玩赏、陪伴的动物，不能种在院子里。"}, {"text": "她每天给宠物浇水，宠物长得很好。", "explanation": "这里应该用〈花〉。宠物是家养的小动物，不是植物，不能给它浇水。"}, {"text": "他送给妈妈的宠物是一束鲜花。", "explanation": "这里应该用〈礼物〉。宠物是家养的小动物，一束鲜花是送人的礼物，不能叫宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家养了一本宠物。", "corrected_sentence": "我家养了一只宠物。", "error_description": "量词错误：“宠物”指动物，应用量词“只”，不能用“本”（“本”用于书籍）。正确说法是“一只宠物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把一台宠物带进了屋里。", "corrected_sentence": "她把一只宠物带进了屋里。", "error_description": "量词错误：“宠物”是动物，应用量词“只”，“台”用于机器、电器。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
