INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95686, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人玩赏、陪伴的家养小动物。", "primary_collocate": null, "pronunciation": "chǒng wù", "ipa": "ʈʂʰʊŋ˨˩˦ u˥˩", "syllable_count": 2, "sentences": [{"text": "很多人养宠物来陪伴自己。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店卖宠物的食物。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带宠物去看医生。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人有宠物陪着，不太孤单。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里不能带宠物。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给宠物洗个澡。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把宠物放在包里。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种宠物很安静，适合小房间。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他养过各种各样的宠物。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常和宠物玩。", "target_word": "宠物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "宠物店", "label": "复合"}, {"form": "寵物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "供人玩赏、陪伴的家养小动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc47c301-ed4a-4c66-ad41-95bf2b4b9f5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宠物", "is_correct": true, "explanation": "“宠物”指供人玩赏、陪伴的家养小动物，养来陪伴自己，符合句意。"}, {"text": "债务", "is_correct": false, "explanation": "语义：债务不能被饲养，也不能陪伴人，句意说不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能被饲养，也不能陪伴人，句意说不通。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒会让人生病，不能被养来陪伴自己。"}], "explanations": {"宠物": "“宠物”指供人玩赏、陪伴的家养小动物，养来陪伴自己，符合句意。", "债务": "语义：债务不能被饲养，也不能陪伴人，句意说不通。", "垃圾": "语义：垃圾不能被饲养，也不能陪伴人，句意说不通。", "病毒": "语义：病毒会让人生病，不能被养来陪伴自己。"}, "sentence_index": 0, "correct_answer": "宠物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "很多宠物生活在森林里，很少见到人。", "explanation": "这里应该用〈动物〉。宠物指供人玩赏、陪伴的家养小动物，森林里的野生动物不叫宠物。"}, {"text": "客厅里的宠物是一张旧沙发。", "explanation": "这里应该用〈家具〉。宠物是活的家养小动物，沙发是家具，不能叫宠物。"}, {"text": "孩子最喜欢的宠物是那套积木。", "explanation": "这里应该用〈玩具〉。宠物是家养的小动物，积木是玩具，不能叫宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宠物", "is_correct": true, "explanation": "“宠物”是可以装进包里带着的小动物，符合句意。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体形庞大，装不进包里。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：“放”的宾语应是具体的物体，“微笑”不能被放进包里。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子体积太大，不能放进包里，句意说不通。"}], "explanations": {"宠物": "“宠物”是可以装进包里带着的小动物，符合句意。", "大象": "体貌：大象体形庞大，装不进包里。", "微笑": "配价：“放”的宾语应是具体的物体，“微笑”不能被放进包里。", "房子": "语义：房子体积太大，不能放进包里，句意说不通。"}, "sentence_index": 6, "correct_answer": "宠物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园里种着很多宠物，夏天很漂亮。", "explanation": "这里应该用〈植物〉。宠物是供人玩赏、陪伴的动物，不能种在公园里。"}, {"text": "他每天给宠物浇水，希望它长得快。", "explanation": "这里应该用〈花〉。宠物是家养的小动物，不是植物，不能给它浇水。"}, {"text": "这几头牛是农民养来耕地的宠物。", "explanation": "这里应该用〈家畜〉。牛是农民养来耕地的家畜，不是供人玩赏陪伴的宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他养了一台宠物，每天陪着他。", "corrected_sentence": "他养了一只宠物，每天陪着他。", "error_description": "量词错误：“宠物”指动物，应用量词“只”，不能用“台”（“台”用于机器、电器）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把一张宠物抱上了床。", "corrected_sentence": "她把一只宠物抱上了床。", "error_description": "量词错误：“宠物”是动物，应用量词“只”，“张”用于纸、桌子等平面物体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25b4f233-5028-4915-936b-2a6895521eb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
