INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95687, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只为了一件事特别做的。", "primary_collocate": null, "pronunciation": "zhuān xiàng", "ipa": "ʈʂwan˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学校为这次比赛做了专项训练。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了这次停电，电力公司进行了专项抢修。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司开展了专项检查。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们安排了专项练习。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院为老人提供专项服务。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练给他做了专项体能训练。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专项活动是为了帮助孩子读书。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们成立了专项小组来解决这件事。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在开展专项行动。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次专项调查只检查食品安全。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专项训练", "label": "复合词"}, {"form": "专项检查", "label": "复合词"}, {"form": "专项行动", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "只为某一件事特地安排的（训练、检查、行动）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95687, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专项", "is_correct": true, "explanation": "专项指只为某件事特别安排的，符合“为这次比赛做了……训练”的句意。"}, {"text": "善良", "is_correct": false, "explanation": "搭配：“善良”描述人的品性，不能修饰“训练”。"}, {"text": "悠闲", "is_correct": false, "explanation": "语义：“悠闲”与为比赛做准备的训练意思相反，句子不通。"}, {"text": "雪白", "is_correct": false, "explanation": "搭配：“雪白”形容颜色，不能修饰“训练”。"}], "explanations": {"专项": "专项指只为某件事特别安排的，符合“为这次比赛做了……训练”的句意。", "善良": "搭配：“善良”描述人的品性，不能修饰“训练”。", "悠闲": "语义：“悠闲”与为比赛做准备的训练意思相反，句子不通。", "雪白": "搭配：“雪白”形容颜色，不能修饰“训练”。"}, "sentence_index": 0, "correct_answer": "专项"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春运期间加开了一趟专项。", "explanation": "这里应该用〈专列〉。“专项”不能指列车，“专列”才指为某事专门加开的列车。"}, {"text": "学校派了一辆专项去接老师。", "explanation": "这里应该用〈专车〉。“专项”不能指车辆，“专车”才指专门用来接送的车。"}, {"text": "他每周在报纸上写一个专项。", "explanation": "这里应该用〈专栏〉。“专项”不能指报纸上的固定版面，“专栏”才指报刊上专门的栏目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95687, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专项", "is_correct": true, "explanation": "专项指为某一件事专门安排的，与“为了帮助孩子读书”的目的相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容环境或物体的状态，不能修饰“活动”。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”形容空间，不能修饰“活动”。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容嗓音，不能修饰“活动”。"}], "explanations": {"专项": "专项指为某一件事专门安排的，与“为了帮助孩子读书”的目的相符。", "潮湿": "搭配：“潮湿”形容环境或物体的状态，不能修饰“活动”。", "狭窄": "搭配：“狭窄”形容空间，不能修饰“活动”。", "沙哑": "搭配：“沙哑”形容嗓音，不能修饰“活动”。"}, "sentence_index": 6, "correct_answer": "专项"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他乘坐了一架专项出访。", "explanation": "这里应该用〈专机〉。“专项”不能指飞机，“专机”才指专为某人安排的飞机。"}, {"text": "这位专项很有经验。", "explanation": "这里应该用〈专家〉。“专项”不能指人，“专家”才指在某领域有专长的人。"}, {"text": "这个专项卖化妆品。", "explanation": "这里应该用〈专柜〉。“专项”不能指售货柜台，“专柜”才指专门的柜台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们为明年的考试做了专项了复习。", "corrected_sentence": "我们为明年的考试做了专项复习。", "error_description": "错误：“专项”后多加了“了”；正确：去掉“了”。“专项”是修饰语，直接接中心词“复习”，中间不能加“了”，应说“做了专项复习”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校为这个专项地活动制定了计划。", "corrected_sentence": "学校为这个专项活动制定了计划。", "error_description": "错误：在“专项”后多加了“地”；正确：不加“地”。“地”用于修饰动词，“专项”直接修饰名词“活动”，应说“专项活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
