INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95688, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "专门用于某一项目的。", "primary_collocate": null, "pronunciation": "zhuān xiàng", "ipa": "ʈʂwan˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这笔钱是专项资金，不能乱用。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专项经费只能用在这个项目上。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司为新产品设立了专项基金。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专项账户只用来存学费。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行给小公司提供专项贷款。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府拿出专项补贴帮助农民。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔专项款已经到账了。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的专项奖学金每年发一次。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里为修路准备了专项预算。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔专项拨款只能用来修桥。", "target_word": "专项", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专项资金", "label": "复合词"}, {"form": "专项基金", "label": "复合词"}, {"form": "专项贷款", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "款项、经费等专门用在某一个项目上的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '947a8989-3ea8-4ff4-ac51-5abddac5eb04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专项", "is_correct": true, "explanation": "专项指专门用于某一项目的，符合“专项资金，不能乱用”的句意。"}, {"text": "甜蜜", "is_correct": false, "explanation": "搭配：“甜蜜”形容感情或生活的愉快，不能修饰“资金”。"}, {"text": "慷慨", "is_correct": false, "explanation": "搭配：“慷慨”形容人的性情，不能修饰“资金”。"}, {"text": "自由", "is_correct": false, "explanation": "语义：“自由资金”指可以任意使用的资金，与“不能乱用”矛盾。"}], "explanations": {"专项": "专项指专门用于某一项目的，符合“专项资金，不能乱用”的句意。", "甜蜜": "搭配：“甜蜜”形容感情或生活的愉快，不能修饰“资金”。", "慷慨": "搭配：“慷慨”形容人的性情，不能修饰“资金”。", "自由": "语义：“自由资金”指可以任意使用的资金，与“不能乱用”矛盾。"}, "sentence_index": 0, "correct_answer": "专项"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商场一楼有一个化妆品专项。", "explanation": "这里应该用〈专柜〉。“专项”不能指售货柜台，“专柜”才指专门售卖某类商品的柜台。"}, {"text": "这场演唱会是他的专项。", "explanation": "这里应该用〈专场〉。“专项”不能指演出场次，“专场”才指专为某人或某类节目安排的演出。"}, {"text": "这家报纸每周都有一个专项。", "explanation": "这里应该用〈专栏〉。“专项”不能指报刊的固定版面，“专栏”才指报纸上固定的专门栏目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专项", "is_correct": true, "explanation": "专项指专门用于某一项目的，符合“专项款已经到账”的句意。"}, {"text": "大方", "is_correct": false, "explanation": "搭配：“大方”形容人的举止，不能修饰“款”。"}, {"text": "无效", "is_correct": false, "explanation": "语义：“无效款”指无效的款项，与“已经到账”矛盾。"}, {"text": "空白", "is_correct": false, "explanation": "搭配：“空白”指没有内容，不能用来修饰“款”。"}], "explanations": {"专项": "专项指专门用于某一项目的，符合“专项款已经到账”的句意。", "大方": "搭配：“大方”形容人的举止，不能修饰“款”。", "无效": "语义：“无效款”指无效的款项，与“已经到账”矛盾。", "空白": "搭配：“空白”指没有内容，不能用来修饰“款”。"}, "sentence_index": 6, "correct_answer": "专项"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条车道是公交专项。", "explanation": "这里应该用〈专用〉。“专用”可作谓语，表示只供某种用途使用；“专项”不能作谓语，也不指车道。"}, {"text": "这里开通了一条专项。", "explanation": "这里应该用〈专线〉。“专项”不能指线路，“专线”才指专门开通的线路。"}, {"text": "这位专项负责此事。", "explanation": "这里应该用〈专员〉。“专项”不能指人，“专员”才指专门负责某项工作的人员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔专项了资金已经存进了账户。", "corrected_sentence": "这笔专项资金已经存进了账户。", "error_description": "错误：“专项”后多加了“了”；正确：去掉“了”。“专项”直接修饰“资金”，中间不能加“了”，应说“专项资金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府拨了一笔专项地补贴。", "corrected_sentence": "政府拨了一笔专项补贴。", "error_description": "错误：在“专项”后多加了“地”；正确：去掉“地”。“专项”直接修饰“补贴”，不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1455cbac-e43b-40e3-a5ec-e4dc7254ffd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
